window.__D("text/ner-mitzva/c002",{"p":[[2800530134,"כלל ויותר עליון מזה שהוא בבחינת קדם אשר לא נעשו כו' כמ\"ש למעלה משום דאו\"ח חוזר לקדמותו ממש שלזה נקרא ארץ חפץ לע\"ל שהוא עלי' הב' דמל' שלזה היה עיקר ירידתה וכנ\"ל בסוף הפ' האומר עצתי תקום וכל חפצי אעשה כו' וד\"ל אך באמת לכאורה יש כאן סתירה גדולה מיניה וביה שהרי כל הטעם ביושר שהוא בחינת רוח למעלה מנפש דעגולים זהו מפני ירידת האור למטה מטה בהגשמ' בחיצוניות האברים כו' והרי זהו מבחינת או\"י דוקא שהולך ויורד ומתמעט<sup data-n=\"1529\">1</sup> כידוע שהארץ היא מבחי' יושר<sup data-n=\"1530\">2</sup> והשמים מבחי' עיגולים ולפי טעם הנ\"ל בעלי' הב' דארץ בסוף למעלה גם מתחלתן דהיינו בבחי' קדם אינו אלא מטעם שהוא בבחינת או\"ח דוקא שחוזר לקדמותו ממש כנ\"ל וזהו כמו תרתי דסתרי ממש מהיפך להיפך וכן בענין חידוש יש מאין שיש במל' יותר מראשי' דחכמה הכל מטעם או\"ח דסוף מעשה עלה כו' וזהו היפך ענין הנ\"ל בבחי' עגולים ויושר דכל מעלת בחי' יושר הוא מטעם או\"י שבא דרך ירידה דוקא כנ\"ל וד\"ל:\n(מ) <b>אך</b> הנה יש להקדים תחלה בשור' ענין ארץ וים שהוא דומה לרקיע<sup data-n=\"1531\">3</sup> כו' שמבואר למעלה<sup data-n=\"1532\">4</sup> בענין יקוו המים כו' שהים הי' מקיף תחלה לכל כדור הארץ ולבסוף הורד כו' וכמו יורדי הים<sup data-n=\"1533\">5</sup> כו' וזהו לרוקע הארץ<sup data-n=\"1534\">6</sup> כו' דהנה כפי המבואר בס' המקובלים<sup data-n=\"1535\">7</sup> הרי ודאי הים והרקיע הן בבחי' עיגולים והארץ הוא בבחי' יושר שהרי אנו רואים שהמים שבים הן בבחינת מקיפים וסובבים כו' ואין כל חדש כלל במים ורקיע בכו\"מ כנ\"ל והארץ היא בבחי' ציור אדם<sup data-n=\"1536\">8</sup> כמו עין הארץ טבור הארץ<sup data-n=\"1537\">9</sup> ערות הארץ פי הארץ<sup data-n=\"1538\">10</sup> וכה\"ג ואין המקומות שבה שוין כי ארץ זו מגדלת תבואות וארץ זו מגדלת בשמים או זית וגפן כמו ארץ זית שמן<sup data-n=\"1539\">11</sup> כו' וארץ זבת חלב ודבש<sup data-n=\"1540\">12</sup> וכ\"ז רק לפי שהארץ היא בבחי' התיקון דמיון פרצוף אדם באברים חיצונים שכל אבר ואבר פעולתו מיוחד בפ\"ע כי ה' בחכמה יסד ארץ<sup data-n=\"1541\">13</sup> בבחי' מ\"ה דחכמה דאדם או\"כ כו' כידוע אך<sup data-n=\"1542\">14</sup> הנה יש בזה להבין דאם היה הארץ בעצם רק מבחי' יושר למה הארץ היא כדורית<sup data-n=\"1543\">15</sup> ועגולית כעיגול וכדור הרקיע וכמו שאנו רואים בגוף שטח הארץ בכללותו שהוא כדור עיגולי כידוע לכל וגם מצד עצם גוף גשם עפר הארץ הנה שוה הוא בכל המקומות בתוארו וממשו כמו גוף וגשם השמים והים שאין שינוי במקו' ואקלים זה מזולתו מצד גשם עצמו כלל רק בגידול הדצח\"מ שבארץ משונים המה זמ\"ז דבאקלים זה גדל בארץ מין זה ובאופן זה ובאקלים אחר גדל מין אחר ובמהות ואופן אחר (כמו ארץ מגדלת חכמים<sup data-n=\"1544\">16</sup> באקלים זה ואנשי מדות רעים ובאקלים זולתו מגדלת טפשים ואנשי מדות טובים וכה\"ג בדו\"צ כו') (וגם הנה אנו רואים בד' יסודות ארמ\"ע<sup data-n=\"1545\">17</sup> שע\"ג הארץ עד הרקיע גם הן בבחי' מקיפים<sup data-n=\"1546\">18</sup> וסובבים על הארץ ולא יש בהן שינוי וחידוש כלל ככו\"מ ברקיע השמים כו' שהרי יסוד האש משכנו למעלה ע\"ג יסוד הרוח בבחי' עיגול מקיף ויסוד הרוח ע\"ג יסוד המים ויסוד המים ע\"ג יסוד העפר ויסוד העפר שבארץ ג\"כ עיגול כדורי כנ\"ל ואין כל חדש בהן כלל כידוע רק באופני הרכבתן יש אופן חידוש ולא שיחודשו בעצם כלל כו') אך הענין",[["1529","1","<b>או\"י. . ויורד ומתמעט</b>: ראה ביאורי הזהר אחרי עז, א. ג. מאמרי אדה\"ז על מארז\"ל ע' ערב. פרשיות התורה ח\"ב ע' תשפח ואילך. תקס\"ח ח\"א ע' תקכא. מאמרי אדה\"א ויקרא ח\"ב ע' תתסט. תו\"ח תולדות קמה, ד."],["1530","2","<b>שהארץ. . יושר</b>: בסה\"מ תקס\"ה כאן ע' רלב [והוא הנחת הר\"מ]: ”גשמיות כדור הארץ הוא מבחי' עגולי'. . (כמ\"ש בס' התמונה ע' ביסוד עולם). . אך בחי' כחות רוחניי' המלובשי' בארץ הוא מבחי' תחתונה דיושר\". ע\"ש. ראה מאמרי אדה\"ז תקס\"ב ח\"א ע' קצח ואילך. ח\"ב ע' תעו. פרשיות התורה ח\"ב ע' תרכא. דרך מצותיך פא, סע\"א. קסב, ב. לקו\"ת שלח לז, ד. מאמרי אדה\"א ויקרא ח\"ב ע' תקצה. דברים ח\"ב ע' תסד. סה\"מ תרמ\"ט ע' רנד. וראה לקמן פ\"מ (בפנים)."],["1531","3","<b>וים שהוא דומה לרקיע</b>: סוטה יז, א."],["1532","4","<b>שמבואר למעלה</b>: נ, א."],["1533","5","<b>יורדי הים</b>: תהלים קז, כג."],["1534","6","<b>לרוקע הארץ</b>: שם קלו, ו."],["1535","7","<b>כפי המבואר בס' המקובלים</b>: להבא להלן ראה סה\"מ תרמ\"ט ע' רנא ואילך."],["1536","8","<b>והארץ. . ציור האדם</b>: ראה אדר\"נ ספל\"א."],["1537","9","<b>עין הארץ טבור הארץ</b>: בא י, ה. ס' שופטים ט, לז."],["1538","10","<b>ערות הארץ פי הארץ</b>: מקץ מב, ט. יב. בראשית ד, יא. קרח טז, ל. לב. פינחס כו, י."],["1539","11","<b>ארץ זית שמן</b>: עקב ח, ח."],["1540","12","<b>וארץ זבת חלב ודבש</b>: שמות ג, ח."],["1541","13","<b>ה' בחכמה יסד ארץ</b>: משלי ג, יט."],["1542","14","<b>אך</b>: ראה סה\"מ תרמ\"ט ע' רנד."],["1543","15","<b>הארץ כדורית</b>: ראה ירושלמי (ע\"ז פ\"ג, ה\"א) הובא בתוד\"ה כדור ע\"ז מא, א. במדב\"ר פי\"ג יד [וכן צ\"ל בהנסמן בסמוך]. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שדמ ובהנסמן במ\"מ לשם. מאמרי אדה\"א הנחות תקע\"ז ע' קמד. וש\"נ."],["1544","16","<b>ארץ מגדלת חכמים</b>: נסמן לקמן קמו, א."],["1545","17","<b>בד' יסודות ארמ\"ע</b>: ראה סה\"מ תש\"ח ע' 204 הערה ו. אג\"ק מכ\"ק אדמו\"ר שליט\"א חי\"ט ע' רלט."],["1546","18","<b>בד' יסודות. . מקיפים</b>: ראה רמב\"ם הל' יסוה\"ת פ\"ג ה\"י."]]],[2800530135,"הוא דבאמת גם הארץ מצד עצמה היא בבחי' עיגולים דתהו וראיה ממ\"ש והארץ היתה תהו<sup data-n=\"1547\">19</sup> כו' כי היו מי הים מקיפים אותה והיא היתה מובלעת שם ג\"כ בבחי' עיגולים דמים המקיפים עליה כו' אך פנימית ותוך תוכה של הארץ דהיינו בעומק של עפר הארץ יש בכח הצומח שבה מבחינת היושר דוקא שהוא כח המגדל ומצמיח שבארץ להוציא צמחה וכל פרי תבואת הארץ בכמה מיני מדריגות ואופנים שונים זמ\"ז ממקום למקום עד שאין מקום אחד דומה לחברו במינים הגדילים כנ\"ל שיש מקום בארץ מגדלת פירות ותבואות כאלה ויש מקום בארץ מגדלת באופן אחר לגמרי ומין אחר לגמרי כאיברי אדם עינים ורגלים וידים כו' שכל אחד מהות מיוחד בפ\"ע כו' כנ\"ל וזהו שאמר בספרי המקובלים שהארץ היא ממדריגה היותר תחתונה שבבחי' יושר והיינו מבחי' מל' דמל' דיושר דעשיה<sup data-n=\"1548\">20</sup> והשמים מבחי' התחתונה שבעגולים דעשיה כו' ועד\"ז ממש יובן בשמים וארץ הרוחניים עד רום המעלות עד בחי' מל' דאצי' שנקרא ארץ עילאה שהוא מבחי' מל' דיושר דוקא היינו דוקא בכח הצומח האלקי שבתוך תוכה להצמיח ולהוליד כל יש מאין כגידול פרי ותבואת הארץ שלמטה וכמאמר תוציא הארץ<sup data-n=\"1549\">21</sup> ארץ עילאה כו' אבל מצד עצמה היא ג\"כ בבחי' עיגולים כים ורקיע העליון כו' כי הרי היו המים מקיפים אותה עד שאמר יקוו המים כו' ותראה היבשה שהוא עלמא דאתגליא עד שהכל היה מן העפר<sup data-n=\"1550\">22</sup> כידוע וד\"ל:\n<b>ומעתה</b> הנה יובן הטעם מה שיש בכח הארץ לחדש יש מאין ממש (עד שגם כל הד\"י הרוחניים כשבאו בתוך תוך הארץ נעשו בבחי' התחדשות גמורה כיסוד הרוח ואש וגם יסוד המים כמו שנקרא מים חיים כו' שאינו בד\"י כלל כו') ואמנם זהו מצד כח הגידול וצמיחה שיש בתוך הארץ וזה נעשה בה אחר שאמר יקוו המים כו' דוקא דכל זמן שהיתה הארץ מובלעת בתוך הים לא היה בה כח זה עדיין כי היתה כלולה בבחי' עיגולים דתהו ואע\"פ שקדמה ארץ לשמים במ\"ת היינו בסוף מעשה כשנתגלה היבש' אח\"כ אבל בסדר ההשתלשלות עיגולים קדמו ליושר ושמים קדמו לארץ כמ\"ש יהי רקיע כו' ולזאת אין בארץ מצד עצמ' כח זה לחד' יש מאין קודם שיקוו המים מעלי' רק אח\"כ שנאמר לרוקע הארץ על המים וכמשל הנ\"ל בנפ' האדם שהתכללות הכחות בהעלם בנפ' הי' תחל' ואח\"כ באו באברי הגוף ושם נמצא יתרון מעלה זו דבחי' יושר בפרצוף אדם גם בענין התולד' כנ\"ל וד\"ל אך אין הענין הנ\"ל מתיישב לנכון דאם עיקר הטעם דחידו' יש מאין שבארץ הוא מצד בחי' או\"ח דוקא שהוא בבחי' עיגולים למה הי' להיפך שחידו' יש מאין נמצא בה אחר שיקוו המים שהן בבחי' עיגולים כו' וגם בגוף הענין יש להבין דמשמע מלשון ארץ שהיא מצד עצמה דוקא בבחי' או\"ח דוקא כמאמר הנ\"ל למה נקרא שמה ארץ<sup data-n=\"1551\">23</sup> שרצתה כו' (וראיה מגוף הגידול והצמיח' שהוא עול' בבחי' או\"ח מלמטה למעלה דוקא וגם המים שמתחדשים בארץ שנק' מים חיים המה נובעי' מלמטה למעל' שלא כטבע המים דחסדים דאו\"י שהולך מגבוה לנמוך כו') אך הנה יש להקדים תחלה בענין הידוע ומבואר במ\"א<sup data-n=\"1552\">24</sup> בפי' יהי רקיע בתוך המים ויהי מבדיל כו' ואח\"כ אמר יקוו",[["1547","19","<b>והארץ היתה תהו</b>: בראשית א, ב."],["1548","20","<b>שהארץ. . מל' דמל'. . דעשיה</b>: ע\"ח (שער ציור עולמות) שמ\"ג פ\"א."],["1549","21","<b>תוציא הארץ</b>: בראשית א, כד."],["1550","22","<b>שהכל היה מן העפר</b>: קהלת ג, כ."],["1551","23","<b>למה נקרא שמה ארץ</b>: נסמן לעיל נד, א."],["1552","24","<b>בענין הידוע ומבואר במ\"א</b>: ראה סה\"מ תקס\"ב ח\"א ס\"ע רמו ואילך. ע' רנג ואילך. אמ\"ב שער הק\"ש טו, ד."]]],[2800530136,"המים שמתחת השמים ותראה היבשה כו' דהנה תחלה היה מים במים<sup data-n=\"1553\">1</sup> מ\"ע ומ\"ת כאחד כו' עד שאמר יהי רקיע להבדיל בין מים עליונים למ\"ת כו' והענין הוא דמ\"ע הוא בבחי' הרוחניות של השפע העליונה שלא היה יכול להיות התהוות מציאת גשמית כמו שנתהווה מן הארץ דכתיב הכל היה מן העפר כו' וע\"כ הוצרך לצמצם ולעשות הבדלה בין הרוחניות והגשמיות ע\"י הרקיע הזה והוא שע\"י הבדל' זו עלו המ\"ע למעלה בבחי' הרוחניות ביותר ונבדלו המ\"ת להיות בבחי' ההגשמ' יותר וע\"כ ירדו עוד למט' עד למט' מן הארץ וכמ\"ש במדר' שגער בהן בנזיפה<sup data-n=\"1554\">2</sup> כו' כמשל המסננת שמבדלת הברור ועוש' את הנשאר בגסות יותר משא\"כ קודם שמסנן מעורב הדק עם הגס יחד כו' כמ\"ש במ\"א<sup data-n=\"1555\">3</sup> וד\"ל וכך יובן טעם ענין הבדלת רקיע זה להבדיל בין מ\"ע ומ\"ת שיהיו מ\"ת בירידת המדריג' ביותר ויפלו למטה כדי שיתגלה היבשה בגובה על המים ואז יהיה בארץ כח הגידול והצמיחה מלמטה למעלה כו' (דמ\"ש לרוקע הארץ על המים הכונה כדי שהארץ תקבל ממי התהום שלמטה ממנו שיעלו בגידי הארץ דרך נביעה מלמטה למעל' וכמ\"ש כי הוא על ימים יסדה<sup data-n=\"1556\">4</sup> ועל נהרות יכוננה כו' וכמ\"ש במ\"א באריכות) ועד\"ז יובן בעולמות העליונים הרוחניי' שזהו בחי' הפרסא המבדיל ומפסיק לצמצם ולהעלים אור הרוחניות שבעליון כדי שיוכל לבא השפע למטה בהגשמה לפ\"ע המקבלים כמו שידוע בענין הפרסא המבדיל בין אצי' לבריאה<sup data-n=\"1557\">5</sup> ומבריאה ליצי' ומיצי' לעשיה כו' וכך הוא עד רום המעלות גם בין עצמות המאציל לנאצלים כו' וכמ\"ש במ\"א בענין אור מים רקיע<sup data-n=\"1558\">6</sup> שבג\"ע יש ג\"כ רקיע המבדיל כו' וד\"ל וכך יובן עד\"ז בבחי' עגולים ויושר הנ\"ל דהיינו כמו בנפש האדם שצריך להיות צמצום והעלם הרוחניות שבכחות הנפש כדי שיבואו בהגשמה בציור אברי אדם וכמו מ\"ע הרוחניי' שנשארו למעלה כו' והנה עכ\"ז יש יתרון מעלה בהגשמת שפע שבארץ אחר שירדו מ\"ת למטה במה שיש בה כח החידוש יש מאין שאין זה במ\"ע גם קודם ההבדלה מטעם שיש מעלה ביושר שאין בעגולים כנ\"ל במשל בנפש האדם בגוף כו' ואמנם הגם שזה החידוש יש מאין הוא בתוך הארץ דוקא כנ\"ל אבל הנה עיקר סיבתו בא להיותו בבחי' או\"ח דוקא וכנ\"ל דכדור הארץ עגולי כו' אע\"פ שהצמיחה באה מצד בחי' היושר דוקא כנ\"ל שהרי עיקר הטעם הוא משום דאו\"ח לקדמותו וכמ\"ש ארץ שרצתה לעשות רצון קונה וכמו רץ לבך<sup data-n=\"1559\">7</sup> כו' ושרש הענין הוא<sup data-n=\"1560\">8</sup> דיש בארץ משני המדריגות דאו\"ח ואו\"י דהנה הים ג\"כ יש בו מבחי' ארץ שהרי הים נקרא סופא דכ\"ד כמו הארץ כמ\"ש כל הנחלים הולכים אל הים<sup data-n=\"1561\">9</sup> כו' דכל השפעות עליונות הכל נמשך אל הים וידוע דים<sup data-n=\"1562\">10</sup> וארץ<sup data-n=\"1563\">11</sup> שניהם הוא בבחי' המל' שנקרא סופא דכולא<sup data-n=\"1564\">12</sup> כו' אך ההפרש ביניהם הוא כך דהארץ הוא מבחי' המל' דיושר ע\"כ יש בה בחי' או\"ח להיותה מבחי' המל' שהוא בבחי' או\"ח עכ\"פ וע\"כ הארץ עגולי' ונקרא ארץ שרצתה כו' והים הוא מבחי' מל' דעגולים בבחי' או\"ח ממש כו' ותחלה יש להבין מהו ההפרש דרך כלל בין או\"ח דעיגולים לאו\"ח דיושר שזהו בחי' ים",[["1553","1","<b>תחלה היה מים במים</b>: נסמן לעיל נג, ב."],["1554","2","<b>שגער בהן בנזיפה</b>: נסמן לעיל שם."],["1555","3","<b>כמשל המסננת. . במ\"א</b>: ראה סה\"מ תקס\"ב שם ע' רנד. אמ\"ב שם."],["1556","4","<b>כי. . ימים יסדה</b>: תהלים כד, ב. ראה גם סה\"מ תקס\"ב ח\"א ע' קעד."],["1557","5","<b>הפרסא. . אצי' לבריאה</b>: נסמן לקמן קטז, א."],["1558","6","<b>בענין אור מים רקיע</b>: ראה לקו\"ת תזריע כב, ד. מאמרי אדה\"א ויקרא ח\"ב ע' תעג."],["1559","7","<b>רץ לבך</b>: ס\"י פ\"א מ\"ח. ת\"ז בהקדמה (ז, א)."],["1560","8","<b>ושרש הענין הוא</b>: ראה גם סה\"מ תרמ\"ט ע' רנד."],["1561","9","<b>כל הנחלים הולכים אל הים</b>: קהלת א, ז."],["1562","10","<b>דים. . המל'</b>: ראה זהר בהעלותך קנ, ב. מאמרי אדה\"א שמות ח\"ב ע' תסג. וש\"נ."],["1563","11","וארץ. . המל' ראה זהר (תוספתא) בראשית לא, ב."],["1564","12","<b>המל' שנקרא סופא דכולא</b>: נסמן לקמן קמב, ב."]]],[2800530137,"וארץ כנ\"ל ויש להקדים ענין אחד והוא מ\"ש אם אין חכמה<sup data-n=\"1565\">13</sup> אין יראה אם אין יראה אין חכמה וידוע הקושיא דא\"כ באיזה יקדים שאיך יקדים בחכמה שאם אין יראה אין חכמה ואיך יקדים ביראה שאם אין חכמה אין יראה אלא הענין הוא שיש הפרש בזה בין בחי' עיגולים דתהו ליושר דתיקון הנ\"ל שבדרך כלל העיגולים הן בבחי' או\"ח והיושר באו\"י וידוע שבע\"ס דאו\"י הכתר קודם לחכמה והמל' אחרון ובע\"ס דאו\"ח<sup data-n=\"1566\">14</sup> נהפוך הוא שהמל' קודם לבא והכתר והחכמה אח\"כ (וזהו עד דמטי רגלין<sup data-n=\"1567\">15</sup> דאו\"י ברגלין דאו\"ח וכמ\"ש ועמדו רגליו<sup data-n=\"1568\">16</sup> כו' דבירורים דאו\"י מלמעלה למטה מכתר עד מל' ובירורי' דאו\"ח מלמטה למעלה ממל' עד הכתר כו') וזהו שאם אין חכמה אין יראה היינו בע\"ס דאו\"י מלמעלה למטה החכמה קודם ליראה ובע\"ס דאו\"ח אם אין יראה שבסוף שהוא המל' אין חכמה שבראש כו' וזהו שכל שיראת חטאו קודמת<sup data-n=\"1569\">17</sup> דוקא לחכמתו חכמתו מתקיימת כו' וכמ\"ש ראשית חכמה<sup data-n=\"1570\">18</sup> יראת ה' שכל טוב לעושיהם ולא ללומדיהם כו' וכן תכלית חכמה<sup data-n=\"1571\">19</sup> תשובה ומע\"ט כו' וא\"כ לכאורה יש להבין בזה דהלא ידוע שנש\"י הן בבחי' היושר כמ\"ש והאלקים עשה את האדם ישר<sup data-n=\"1572\">20</sup> כו' ואתם קרויים אדם<sup data-n=\"1573\">21</sup> כו' וכידוע וא\"כ למה בכנ\"י היראה עיקר ותחלה וכמ\"ש מה ה' אלקיך שואל ממך כ\"א ליראה<sup data-n=\"1574\">22</sup> כו' וכן דוד אמר אחת שאלתי<sup data-n=\"1575\">23</sup> כו' שבתי בבית ה' כו' וכמ\"כ ויהי נועם ה'<sup data-n=\"1576\">24</sup> כו' ומעשה ידינו דוקא כוננהו בצדקה תכונני<sup data-n=\"1577\">25</sup> וכתיב בזאת יבא<sup data-n=\"1578\">26</sup> כו' וכה\"ג ולכך א' דדוקא כשיראת חטאו קודמת לחכמתו חכמתו מתקיימת וכמ\"ש סוף דבר<sup data-n=\"1579\">27</sup> כו' את האלקים ירא כו' כי זה כל האדם דהמעשה עיקר וגם מה שתלמוד גדול<sup data-n=\"1580\">28</sup> אינו אלא מפני שמביא למעשה כידוע כו':\n(מא) <b>אך</b> הנה יש להבין תחלה בבחי' ההפרש בין ים לארץ בדרך כלל מאחר ששניהם בבחי' או\"ח דוקא אלא שזה ממל' דעגולים וזה ממל' דיושר מהו ההפרש בזה בין עיגולים ויושר כו' והנה יובן זה בעבודת ה' שיש ב' מיני התפעלות הפכיים אע\"פ ששניהם בבחי' רצוא והסתלקות מלמטה למעלה מן המקבל אל המשפיע הא' כמו שאנו רואים בהתפעלות התלהבות הלב לפרקים בתשוקה וצמאון גדול לה' אחד דהיינו שתכסוף הנפש ותכלה להיות נפשו משגת בהשגה וראי' עין השכל לאסתכלא ביקרא דמלכא<sup data-n=\"1581\">29</sup> כמו שאמר מתי אבא ואראה<sup data-n=\"1582\">30</sup> פני אלקים וכן צמא' לך נפשי<sup data-n=\"1583\">31</sup> כו' כן בקדש חזיתיך<sup data-n=\"1584\">32</sup> והיינו גודל התשוקה ברשפי אש להשיג ולראות אור פני מלך כו' אך לא יכול לראות מצד ריחוקו כמו בארץ ציה<sup data-n=\"1585\">33</sup> כו' או מצד שלא יכיל כלי מוחו ולבו להגיע ולעמוד בדביקות והתקשרות זו מפני שהוא למעלה מכלי השגתו כענין מה פשפשת<sup data-n=\"1586\">34</sup> כו' וזהו כמו שא' נכספ' וגם כלתה נפשי<sup data-n=\"1587\">35</sup> כו' ואמר בזהר דגם מאן דמיכסיף לאסתכלא<sup data-n=\"1588\">36</sup> ולא יכיל לאדבקא כו' עכ\"ז שבחא אית ליה כו' לפי שזהו בבחי' התשוקה עכ\"פ שהוא בבחי' או\"ח דעיגולים שכולו נמשך כלפי מעלה ורוצה לצאת וליכלל להדבק באחד רק שלא יכיל לאדבקא כו' והיינו כמו גלי",[["1565","13","<b>אם אין חכמה</b>: אבות פ\"ג מי\"ז."],["1566","14","<b>שבע\"ס דאו\"י. . דאו\"ח</b>: נסמן לעיל לה, א."],["1567","15","<b>עד דמטי רגלין</b>: ראה זהר פקודי רנח, א ובמק\"מ שם. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תתמה־ דברים ח\"א ע' עז."],["1568","16","<b>ועמדו רגליו</b>: זכרי' יד, ד."],["1569","17","<b>שכל שיראת חטאו קודמת</b>: אבות פ\"ג מ\"ט."],["1570","18","<b>ראשית חכמה</b>: תהלים קיא, י. ראה ברכות יז, א (הגי' שהובא עה\"ג שם)."],["1571","19","<b>תכלית חכמה</b>: ברכות יז, א."],["1572","20","<b>והאלקים. . ישר</b>: קהלת ז, כט [ושם: עשה האלקים — ראה הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תקצה־ דברים ח\"ב ע' תקנא. לקמן קיד, ב]."],["1573","21","<b>ואתם קרויים אדם</b>: יבמות סא, א."],["1574","22","<b>מה. . כ\"א ליראה</b>: עקב י, ב."],["1575","23","<b>אחת שאלתי</b>: תהלים כז, ד."],["1576","24","<b>ויהי נועם ה'</b>: שם צ, יז."],["1577","25","<b>בצדקה תכונני</b>: ישעי' נד, יד."],["1578","26","<b>בזאת יבא</b>: אחרי טז, ג."],["1579","27","<b>סוף דבר</b>: קהלת יב, יג."],["1580","28","<b>שתלמוד גדול</b>: קידושין מ, ב."],["1581","29","<b>לאסתכלא ביקרא דמלכא</b>: נסמן לקמן קיא, א."],["1582","30","<b>מתי אבא ואראה</b>: תהלים מב, ג."],["1583","31","<b>צמא' לך נפשי</b>: שם סג, ב."],["1584","32","<b>כן בקדש חזיתיך</b>: תהלים שם, ג."],["1585","33","<b>בארץ צי'</b>: תהלים סג, ב. ירמי' ב, ו. יחזקאל יט, יג."],["1586","34","<b>מה פשפשת</b>: זהר בהקדמה א, ב."],["1587","35","<b>נכספ' וגם כלתה נפשי</b>: תהלים פד, ג."],["1588","36","<b>דגם מאן דמיכסיף לאסתכלא</b>: ראה זהר נח סט, ב."]]],[2800530138,"הים שבטבעם לעלות למעלה מעלה בגובה מאד (כרבב\"ח שראה רוממות הגל ש' פרסי<sup data-n=\"1589\">1</sup> כו') וז\"ש בשוא גליו אתה תשבחם<sup data-n=\"1590\">2</sup> תורידם למטה<sup data-n=\"1591\">3</sup> ומפרש בזהר ל' שבח<sup data-n=\"1592\">4</sup> דשבחא אית ליה כו' וזהו בחי' מל' כשנקרא ים העליון כד סליק גלגלוהי<sup data-n=\"1593\">5</sup> כו' שהוא בחי' או\"ח דמל' דעיגולים דוקא וד\"ל אבל הארץ היא בבחי' או\"ח דמל' דיושר ויובן זה בעבודת ה' שיש בחי' רצוא ותשוקה למעלה אך שהתשוקה היא שיומשך גלוי אור אלקי מלמעלה למטה בתוך לבו ודעתו וכנ\"ל בפי' ארץ שרצתה לעשות רצון קונה שכל התשוקה והרצון אינו רק לעשות רצון קונה והוא לעשות המשכת רצון העליון בתו\"מ בגלוי אור בנפשו וזהו שלע\"ל תקרא ארץ חפץ<sup data-n=\"1594\">6</sup> וכו' ואע\"פ שזהו ג\"כ בחי' העלאה דאו\"ח אבל הוא בשביל ירידה והמשכה למטה (וכמו ואל אישך תשוקתך<sup data-n=\"1595\">7</sup> שתשוקה זו לקבל השפע כו') וזהו כמו היפך הרצוא דאו\"ח דעיגולים שהוא לצאת מעצמו ליכלל למעלה (בל\"א אויש גין פון זיך) ורצוא זה לעשות רצון קונה התשוקה היא שתקבל אור העליון לעצמה (בל\"א צו זיך כו') ולכך נקרא מל' דאו\"י והיינו בארץ שפנימיות' ותוכה בבחי' היושר ממש ברבוי כלים מכלים שונים כפרצוף אדם ממש כנ\"ל אך כדור הארץ בכללותה שהוא עגול כעיגולים דגלגלים גם הוא בבחי' רצוא ומרוצה ותשוק' רצון רק שהוא בבחי' או\"ח דמל' דיושר וד\"ל (אבל החידוש יש מאין שבארץ הוא בפנימית בכח הצומח שבארץ דוקא) ונמצא שהים וארץ שניהם מבחי' או\"ח רק שזה ממל' דעגולים וזה ממל' דיושר (וז\"ש לרוקע הארץ על המים שצוה שיעלה מל' דיושר למעלה על מל' דעיגולים שצריך שיגבר או\"י על או\"ח בכלל ובפרט כמשי\"ת) וזהו עיקר ענין קי\"ס מה שהעביר ישראל בתוך הים ביבשה דוקא דהנה נש\"י בשרשם הם מבחי' היושר דהיינו מבחי' שם מ\"ה דתיקון בחי' אדם והוא היפוך בחי' או\"ח דעגולים דים העליון הנ\"ל דאו\"י דיושר הולך ונמשך מלמעלה למטה דוקא בבחי' החסדים היפך או\"ח דגבורות שעולה מלמטה למעלה ולזה העביר לישראל להגביר כח האו\"י דבחי' יושר דאדם על בחי' או\"ח דים כשעברו בו ביבשה דוקא שהרי הים נבקע מפניהם דוקא כמ\"ש לגוזר י\"ס לגזרים<sup data-n=\"1596\">8</sup> כל\"ח שח\"ע דאו\"י גבר לגזור לים סוף לגזרים (שזהו כמו בשוא גליו אתה תשבחם תורידם למטה כך נמתקו ונתבטלו הגבו' דאו\"ח ונבקע הים כמ\"ש הים ראה וינוס<sup data-n=\"1597\">9</sup> כו') וביאור הדברים ידוע שהמלאכים בעצם מהותם מבחי' או\"ח דעגולים (אע\"פ שפני אדם לארבעתן<sup data-n=\"1598\">10</sup> ויש ציור קומה שוקי החיות<sup data-n=\"1599\">11</sup> וכו' מ\"מ בהתכללות כא' עולין בתשוקה כללי' כגלגלים הגשמיים שסובבים כולם בבת אחת כו') וז\"ש משרתיו אש לוהט כו' כאש שטבעו לעלות בהתלהבות התשוקה וכן מלאכים שנק' רוחות<sup data-n=\"1600\">12</sup> כו' אך נשמות הם במהותם בהיפוך ממש מזה והוא מ\"ש בנפש אדם ויהי האדם לנפש חיה<sup data-n=\"1601\">13</sup> כו' פי' לנפש חיה שיחיה באברים רבים כלים מכלים שונים כפרצוף גופו של אדם שכלול מהכל עין ואזן ורגל ולא כרגל דמלאכים שכלול בכנפיה' כעוף וחיה<sup data-n=\"1602\">14</sup> אלא שהאור מיוחד בכל אבר בפ\"ע בסדר ציור אדם בשכל במוח",[["1589","1","<b>כרבב\"ח. . הגל ש' פרסא</b>: ראה ב\"ב עג, א."],["1590","2","<b>בשוא גליו אתה תשבחם</b>: תהלים פט, י. ראה גם ד\"ה זה בסה\"מ תקס\"ג ח\"ב ע' תשלד."],["1591","3","<b>תשבחם תורידם למטה</b>: ראה מפרשים לתהלים שם."],["1592","4","<b>בזהר ל' שבח</b>: זהר נח שם."],["1593","5","<b>כד סליק גלגלוהי</b>: ראה זהר בשלח מח, ב. וראה גם זהר נח שם."],["1594","6","<b>ארץ חפץ</b>: מלאכי ג, יב."],["1595","7","<b>ואל אישך תשוקתך</b>: בראשית ג, טז."],["1596","8","<b>לגוזר י\"ס לגזרים</b>: תהלים קלו, יג."],["1597","9","<b>הים ראה וינוס</b>: שם קיד, ג."],["1598","10","<b>שפני אדם לארבען</b>: ראה יחזקאל א, י."],["1599","11","<b>שוקי החיות</b>: חגיגה יג, א."],["1600","12","<b>משרתיו אש לוהט. . רוחות</b>: תהלים קד, ד."],["1601","13","<b>ויהי האדם לנפש חיה</b>: בראשית ב, ז."],["1602","14","<b>כרגל דמלאכים. . וחיה</b>: ראה לעיל סד, א."]]],[2800530139,"ומדות בלב וידים ורגלים כו' שזהו רק בחי' פירור ופירוד אור וחיות הנפש בחלקים רבים כו' וזהו שיש בטבע הנשמות לקבל כל אור ואור האלקי בהתחלקות שבבחי' אדם למעלה שבא בבחי' או\"כ בפרט כמו כל התו\"מ שהן באין בריבוי ההתחלקות בכלים מכלים שונים כמו ברמ\"ח מ\"ע שנק' רמ\"ח אברין דמלכא<sup data-n=\"1603\">16</sup> ושס\"ה ל\"ת<sup data-n=\"1604\">15</sup> כו' שהרי כל תשוקת הנשמה האלקי' רק להמשיך אור א\"ס ברבוי כלים דוקא כמו בכל מצוה ומצוה בפרט שכמו טבע היא בנפש אדם דוקא לפי שאתם קרויים אדם דוקא בצלם אדם העליון ולכך הנשמות דישראל דוקא היו ראויים להיות בחי' כלי קיבול לקבל הי' דברות כללות התו\"מ בשעת מ\"ת ולא זולתם וגם למלאכים לא נתנה משום שנאמר זאת תורת האדם<sup data-n=\"1605\">17</sup> דוקא וכן אלה המצות<sup data-n=\"1606\">18</sup> אשר יעשה אותם האדם דוקא להיותם בשרשם בבחי' פרצוף אדם דבחי' היושר דוקא כנ\"ל וד\"ל. ולזה הטעם העבירם בתוך הים ביבשה שבהם היה הכח של המשכת או\"י בריבוי כלים בתו\"מ שהן בבחי' יושר דאדם ע\"כ העבירם בים כדי שיגבר כח דאו\"י על או\"ח דים ויתבטל ממציאותו עד שנהפך ליבשה כמ\"ש בקע הים ויעבירם<sup data-n=\"1607\">19</sup> כו' לפי שזהו עיקר כל התו\"מ והיה זה הכנה למ\"ת שיוכלו בנ\"י לקבל התו\"מ שהוא בבחי' יושר דפרצוף אדם פב\"פ וד\"ל ויובן זה בעבודת ה' שעיקר שלימות העבודה שבלב ומוח בתפלה הוא להגביר כח התשוקה בגלוי אלקות למטה ע\"י תורה ומצות וכה\"ג על התפעלו' התשוק' בהתלהבו' רשפי אש העולה ליכלל למעלה שזהו להגביר בחי' או\"י על או\"ח וכמו שנראה בחוש הטבעי בכל נשמת אדם שגם שתתפעל בהתלהבות לעלות ולידבק באחד (שזהו בל\"א פון זיך) כמו כלתה נפשי כנ\"ל יגבר בו כח הרצון בהמשכת גלוי אור ה' בנפשו בקבלת עומ\"ש בתו\"מ כמו והאר עינינו<sup data-n=\"1608\">20</sup> בתורתיך ודבק לבנו במצותך כו' עד שבוקע ועובר על בחי' הרצו' והתשוק' לעלו' כו' כענין בע\"כ אתה חי<sup data-n=\"1609\">21</sup> לקיי' תו\"מ כו' שזה כל האד' שבבחי' יוש' כנ\"ל רק שהתשוק' לזה הוא בבחי' רצו' ג\"כ אבל הוא בחי' רצו' להמשכה וירידה דוקא שזה נק' מל' דיושר כנ\"ל בפי' ארץ שרצתה לעשות רצון קונה והקבלה בנפשו לעשות התו\"מ בפ\"מ זהו בחי' חב\"ד וחג\"ת ונה\"י כל ציור קומת אדם דיושר כנ\"ל וד\"ל וזהו שנבקע הים מפני ישראל לי\"ב גזרים דוקא שהוא לנגד י\"ב שבטים<sup data-n=\"1610\">22</sup> שכל שבט ושבט יש לו מדריגה מיוחדת באופן היריד' והמשכ' אלקות באו\"כ כו' (ובע\"ח מבוא' דבג' מקומו'<sup data-n=\"1611\">23</sup> בוקע האו\"י דיושר לאו\"ח דעיגולי' לבד ואמנ' בקי\"ס היה הבקיע' דיושר בעיגולי' דים לי\"ב גזרים לפי שהג' מקומו' שהן חב\"ד נחלקו לי\"ב שהן י\"ב ג\"א<sup data-n=\"1612\">24</sup> דו\"ק ששרש נש\"י בו\"ק<sup data-n=\"1613\">25</sup> העליוני' ע\"כ נבקע הים לכאו\"א כנגד חלקו ושרשו למעל' וזהו לגוז' י\"ס לגזרי' שיהיה לעו' חסדו דאו\"י דור אחר דור מקבלת התורה עד משיח בקיום התו\"מ שישראל מקיימין שכ\"ז נעשה מן הליכתם בי\"ס שהיה זה הכנה למ\"ת כנ\"ל וד\"ל) ובכ\"ז יתורץ הקושיא דלעיל בענין דאם אין יראה אין חכמה שזהו בע\"ס דאו\"ח שהיראה שהו' המל' קודם כו' אע\"פ שנש\"י הן בבחי' היוש' דהנ' בחי' מל' דיושר הוא בחי' הרצו' והתשוק' להמשכ' וגלוי אלקו' בתו\"מ כנ\"ל שזהו שרצתה לעשות רצון קונה ואמנם העיקר הוא גופה של המעש' בפו\"מ שהוא בקבלת עול לבד להמשיך",[["1603","16","<b>רמ\"ח אברין דמלכא</b>: נסמן לעיל ד, ב."],["1604","15","<b>ברמ\"ח מ\"ע. . ושס\"ה ל\"ת</b>: מכות כג, סע\"ב."],["1605","17","<b>זאת תורת האדם</b>: ראה שמו\"ב ז, יט. חוקת יט, יד. מאמרי אדה\"א נ\"ך ע' שכה. וש\"נ. הנחות תקע\"ז ע' קיד. שע\"ת ח\"א מב, ב."],["1606","18","<b>אלה המצות</b>: ראה בחוקותי כז, לד. אחרי יח, ה. הנסמן במאמרי אדה\"א הנחות תקע\"ז ע' כ־ לשע\"ת ט, ב. לעיל ט, א. סה, א. לקמן סט, ב."],["1607","19","<b>בקע הים ויעבירם</b>: תהלים עח, יג [ושם: ים]."],["1608","20","<b>והאר עינינו</b>: ברכת (אהבת עולם) ק\"ש שחרית."],["1609","21","<b>בע\"כ אתה חי</b>: אבות ספ\"ד."],["1610","22","<b>שנבקע הים. . לי\"ב גזרים. . י\"ב שבטים</b>: ראה פדר\"א פמ\"ב. תנחומא בשלח י. רש\"י תהלים קלו, יג. וראה גם מכילתא בשלח יד, טז. לקמן פג, א. צו, ב. לקו\"ת צו טו, ד. יז, א-ב. ד. בהעלותך לא, ב. מסעי צד, ד. מאמרי אדה\"א ויקרא ח\"א ע' רכא. וש\"נ."],["1611","23","<b>דבג' מקומו'</b>: ראה גם סה\"מ תקס\"ה כאן ע' רלה."],["1612","24","<b>י\"ב ג\"א</b>: נסמן לקמן קכה, א. וראה גם לקמן עג, א."],["1613","25","<b>ששרש נש\"י בו\"ק</b>: ראה גם לעיל יח, א."]]],[2800530140,"אור בכלי דוקא וזהו ענין היראה שקודמ' לחכמ' שהירא' הוא קבלת עמ\"ש לעשות בפ\"מ והרצון והתשוקה לזה הוא כטפל לגבי העיקר והיינו בבחי' ע\"ס דאו\"ח דהיינו בבחי' י\"ס דאו\"ח שבבחי' היושר דוקא שהמל' הוא בחי' כתר והכתר שהוא הרצון הוא האחרון וז\"ש מה ה' שואל מעמך מלמטה למעלה שהוא בבחי' קבלת התו\"מ רק ליראה בפו\"מ ואם אין יראה אין חכמה שזה כל האדם דיושר כו' משא\"כ בבחי' או\"ח דעיגולים נהפוך הוא שבחי' הרצון והחכמה קודם ואם אין חכמה אין יראה כו' וה\"ז עד\"מ אדם שרוצה לבנות בנין שהרצון קודם למעשה הבנין אבל העיקר הוא בפועל מעשה הבנין שלזה היה עיקר המכוון ברצון הרי המעשה קודם לרצון עד שהרצון שיש לו במעשה זו כטפל לגבי העיקר שלזה הטעם אמרו ארץ קדמה דסוף מעשה בפ\"מ עבמ\"ת כידוע (ולפ\"ז בחי' מל' דיושר אחרון מפני שהוא הכונה ורצון לעשות אבל המעשה עצמה הוא בחי' כתר דבחי' יושר קודם לכל וכענין שכר מצוה מצוה<sup data-n=\"1614\">1</sup> עצמה וזהו בחי' כתר ש\"ט שעולה ע\"ג ג' כתרים דכתר תורה גם שהן בבחי' יושר כו' וד\"ל. וכמ\"ש במ\"א שזהו בחי' משיח<sup data-n=\"1615\">2</sup> ב\"ד דכתיב ביה ואלה דברי דוד<sup data-n=\"1616\">3</sup> האחרונים כו' הוקם על דוקא שזהו דוד מ\"י חי וקיים<sup data-n=\"1617\">4</sup> כו'<sup data-n=\"1618\">5</sup> וזהו תכלית חכ' דיושר תשוב' ומע\"ט בפו\"מ דוקא וז\"ש סוף דבר כו' את האלקים ירא ואת מצותיו שמור שיראה זו רק למעשה זהו כל האדם דיושר וזהו ענין שמחה ש\"מ שבפו\"מ שגדול משמח' וכונה עליונה שבמצוה וראי' מר\"י לוריא שלא זכה לסודות התורה ולגילוי אליהו ורוה\"ק רק משמחה של מצוה<sup data-n=\"1619\">6</sup> בפו\"מ ולא מן השמחה שבכונה וזהו כמ\"ד מצות א\"צ כונה<sup data-n=\"1620\">7</sup> רק קבלת עול למעש' בלבד וכמ\"ש ומעשה ידינו כוננהו כנ\"ל וד\"ל:\n(מב) <b>וזהו</b><sup data-n=\"1621\">8</sup> אז ישיר משה<sup data-n=\"1622\">9</sup> ובני כו' אשירה לה' כי גאה גאה וגאה הא' בחולם וגאה הב' בקמץ<sup data-n=\"1623\">10</sup> כידוע ויש להקדים תחל' ענין המאמר דג' קשרים הן<sup data-n=\"1624\">11</sup> ישראל מתקשראן באוריי' כו' ויש להבין לכאור' דלפעמים משמע<sup data-n=\"1625\">12</sup> מדברי רז\"ל בהיפך והוא מ\"ש מורשה מאורשה<sup data-n=\"1626\">13</sup> שהתורה נק' כלה וכנ\"י נק' חתן אך הנה אמרו דבי' דברים<sup data-n=\"1627\">14</sup> ברא ה' את העולם בחכמ' ובתבונה ובדעת כו' ונחלקו לז' מדות שכללותם יו\"ד מאמרות וכולם בחכמה עשית<sup data-n=\"1628\">15</sup> שזהו מאמר דבראשית ופרטיהם מתחלקים לאין שיעור בצרופי אותיות עד שנתהווה רבוא רבבות עולמות בריבוי ההשתלשלות דבי\"ע כידוע וידוע שכמו שאין ערוך<sup data-n=\"1629\">16</sup> לנברא עם הבורא כך אין ערך לנאצל עם המאציל רק ע\"י בחי' צמצום הראשון הי' סיבת ההמשכה להאציל כו' והוא מפני שטבע הטוב להטיב<sup data-n=\"1630\">17</sup> ונק' חפץ חסד שבעצמותו כי מצד עצמות המאציל נבדל בערך מהיות גם בחי' מקור למקור לאצילות כידוע וז\"ש כי אמרתי עולם חסד יבנה<sup data-n=\"1631\">18</sup> לשון הוה שיבנה תמיד מפני שצריך לחדש הבנין של העולמות ממקור הראשון מקורא דכולא<sup data-n=\"1632\">19</sup> מצד העלאת מ\"ן דמעשה התחתוני' ומתחלה הי' חפץ חסד מעצמו ואח\"כ צריך להיות ע\"י העלאת מ\"ן מלמטה כמ\"ש בע\"ח<sup data-n=\"1633\">20</sup> וזהו עולם חסד יבנה שצ\"ל נבנה בכל פעם כו' והנה עד שקבלו ישראל התורה הי' העלאת מ\"ן מנשמו' הצדיקים הגדולים שבדורות הראשונים שמאדה\"ר עד אברהם כחנוך<sup data-n=\"1634\">21</sup> ומשותלח ונח כו' והאבות והשבטים",[["1614","1","<b>שכר מצוה מצוה</b>: אבות פ\"ד, מ\"ב."],["1615","2","<b>כתר ש\"ט. . משיח</b>: ראה אבות פ\"ד, מי\"ג. מאמרי אדה\"א בראשית ע' לה. וש\"נ. נ\"ך ע' רטו. וש\"נ. תו\"ח נח סג, א ובהערה 9."],["1616","3","<b>ואלה דברי דוד</b>: שמואל-ב כג, א."],["1617","4","<b>דוד מ\"י חי וקיים</b>: נסמן לעיל יא, א."],["1618","5","<b>כו'</b>: כנצ\"ל: כו')."],["1619","6","<b>מר\"י לוריא. . מצוה</b>: ראה ס' חרדים בהקדמה (תנאי המצות, התנאי הרביעי). מאמרי אדה\"א נ\"ך ע' כז. וש\"נ. דרושי חתונה ח\"ב ע' תנז."],["1620","7","<b>מצות א\"צ כונה</b>: נסמן לעיל ה, א."],["1621","8","<b>וזהו</b>: להבא להלן (פמ\"ב-נ\"א) ראה הנסמן לעיל בריש הדרוש (ח, ב)."],["1622","9","<b>אז ישיר משה</b>: בשלח טו, א."],["1623","10","<b>גאה גאה. . בחולם. . בקמץ</b>: ראה גם לקמן עז, א."],["1624","11","<b>דג' קשרים הן</b>: נסמן לעיל סב, ב."],["1625","12","<b>דלפעמים משמע</b>: ראה מאמרי אדה\"ז על פרשיות התורה כאן ע' רפב. תקס\"ה כאן ע' רלו. מאמרי אדה\"א שמות ח\"א ע' א. ח\"ב ע' תיג. ויקרא ח\"א ס\"ע שלב. דרושי חתונה ח\"ב ע' תקיג ובהנסמן בהנ\"ל."],["1626","13","<b>מורשה מאורשה</b>: ברכה לג, ד. ברכות נז, א."],["1627","14","<b>דבי' דברים</b>: ראה חגיגה יב, א."],["1628","15","<b>וכולם בחכמה עשית</b>: תהלים קד, כד."],["1629","16","<b>שכמו שאין ערוך</b>: ראה גם לקמן צח, א."],["1630","17","<b>שטבע הטוב להטיב</b>: נסמן לעיל כב, א."],["1631","18","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."],["1632","19","<b>מקורא דכולא</b>: לשון הזהר בראשית לג, א."],["1633","20","<b>העלאת מ\"ן. . בע\"ח</b>: ראה ע\"ח (שער דרושי הנקודות) ש\"ח ספ\"ו. מאמרי אדה\"א בראשית ע' תקסו. וש\"נ."],["1634","21","<b>כחנוך</b>: ראה תו\"א שמות נא, ד."]]],[2800530141,"ואחר שקיבלו ישראל תו\"מ אז עיקר העלאת מ\"ן הוא מכנ\"י וזהו שתנאי הי' להקב\"ה<sup data-n=\"1635\">22</sup> בוימ\"ב אם יקבלו ישראל כו' וא\"ל יחזיר' כו' וזהו בראשית בשביל ישראל<sup data-n=\"1636\">23</sup> שנק' ראשית כו' ודוקא בתו\"מ בפ\"מ שישראל עושין למטה עי\"ז דוקא נתעורר למעלה להמשיך אורות דאצילות מחדש להקרו' בשם חכים וחסדן כו' כמו בצדקה וחסד שעושין נק' בתקונא דא חסד דרועא ימינא<sup data-n=\"1637\">24</sup> דקוב\"ה כו' וכיוצא בזה בכל המצו' מעשיות דכתיב ועשיתם אתם כאלו עשאוני<sup data-n=\"1638\">25</sup> ברמ\"ח אברים שהן רמ\"ח אברי' העליונים הרוחני' בציור קומת אדם דאצי' וכללותם מצות ת\"ת שעי\"ז ממשיכים אא\"ס בח\"ע שזהו לשמה לשם התורה<sup data-n=\"1639\">26</sup> כידוע והנה באמת יש להבין מאין יש לכנ\"י כח גדול כזה עד שיהי' עי\"ז חיבור וקשר עצמות המאציל בנאצלים שלא הי' כזה גם בראשית ההשתלשלות דאבי\"ע גם ע\"י צמצום הראשון שהרי ידוע בעיקר מעלת יחודים עליונים שבמ\"ע למעלה היינו להוסיף אור גדול מפנימיות ועצמות אא\"ס שלמעלה הרבה מבחי' הצמצום דמאמר קו המדה כו' וכמ\"ש בע\"ח שכל עיקר המצו' להוסיף אור באצילות<sup data-n=\"1640\">27</sup> אך הענין הוא דיש בנש\"י ב' מדרגות הא' במקור שרשם למעלה בפנימית ועצמות אא\"ס ממש כי חלק הוי\"ה עמו<sup data-n=\"1641\">28</sup> שישראל עלה במח'<sup data-n=\"1642\">29</sup> בעצמות ממש טרם שצמצם עצמו שנמלך בנשמתן של צדיקים<sup data-n=\"1643\">30</sup> כו' וע\"כ בעשות א' מישראל גם בגוף גשמי בעה\"ז הגשמי איזה מצוה בפ\"מ או ע\"י מס\"נ אם בכח במוח ולב בק\"ש או בפועל כתשובה מעומק הלב (כתשוב' דראב\"ד וכה\"ג) אזי מעוררים לבחי' שרשם הראשון למעל' מעלה במהו\"ע ממש בבחי' הפנימי' ועצמות ממש עד שיש בכח זה לעורר מחדש להוסיף ולהמשיך אור חדש ממהו\"ע באצילות והן בחי' רמ\"ח אברים דמלכא שנעשים באו\"כ שע\"י המצות שלמטה נמשך תוס' אורות בכלים כמו בצדקה וחסד נמשך תוס' אור באור חסד דאצילות וכה\"ג וכנ\"ל לפי שבחי' הפנימית דנש\"י בשרשם בפנימית ועצמות מעורר להמשיך תוס' אור פנימית בע\"ס או\"כ כו' כנ\"ל וזהו שהי' התנאי לוימ\"ב העליונים עד רום המעלות אם יקבלו ויקיימו ישראל תו\"מ כו' דסוף מעשה זו דנשמות הצדיקים עבמ\"ת וזהו עיקר ההעלאת מ\"ן יותר מהעלאת מ\"ן דנשמות שבדורות הראשונים עד מ\"ת וד\"ל אך זהו מצד בחי' הפנימי' של נש\"י בשרשם למעלה בפנימית ועצמות ע\"כ הן העושין את המצות עליונות למעלה וכמ\"ש כאלו עשאוני כו' שנמצא שישראל מנשאין ומגביהי' למצות העליונו' שיומשכו מלמעלה כו' אבל המדריגה הב' בישראל היינו בחי' החיצוניות שבהם שהוא למטה הרבה מן המצות הרוחניות דאצילות עד שהמצות שעושין המה מנשאין ומעלין לנש\"י למעלה כמ\"ש אלה המצות<sup data-n=\"1644\">31</sup> אשר יעשה אותם האדם וחי בהם דחיות נש\"י שנק' אדם הוא ע\"י המצות דוקא והענין הוא לפי שנשמות ישראל שבגופים באו למטה בדרך השתלשלות בבחי' בריאה מאין ליש ממש כידוע דנר\"נ דבי\"ע נמשך מחיצוניות הכלים דאצילות על ידי יחוד זו\"נ כו' וכמו שאנו אומרים<sup data-n=\"1645\">32</sup> אתה בראת אתה יצרת כו' וכן אמ' בפי' ויברא ה' את האדם כו' וייצר<sup data-n=\"1646\">33</sup> כו' וכתיב לכבודי בראתיו יצרתיו<sup data-n=\"1647\">34</sup> כו' וכמו חי ה' אשר עשה לנו את הנפש הזאת<sup data-n=\"1648\">35</sup> וכידוע ולפ\"ז בסיבת קיום רצון העליון שבמצות נמשך תוס' אור להאיר בנשמות דבי\"ע עד בחי' הנפ' דעשי' והיינו",[["1635","22","<b>שתנאי הי' להקב\"ה</b>: ראה שבת פח, א. הנסמן במאמרי אדה\"א בראשית ע' קמ־ תו\"ח בראשית ב, ד הערה 37."],["1636","23","<b>בראשית בשביל ישראל</b>: בראשית א, א וברש\"י שם. הנסמן בלקו\"ש (מקץ) כרך ג ע' 820."],["1637","24","<b>בתקונא דא. . ימינא</b>: ת\"ז בהקדמה (יז, א)."],["1638","25","<b>ועשיתם אתם כאלו עשאוני</b>: בחוקותי כו, ג. ראה זהר שם קיג, סע\"א. מאמרי אדה\"א הנחות תקע\"ז ע' רלה. וש\"נ."],["1639","26","<b>לשמה לשם התורה</b>: ראה פע\"ח שער הנהגת הלימוד. מאמרי אדה\"ז על פרשיות התורה כאן ע' רפג. תקס\"ה כאן ע' רלו. שע\"ת ח\"ב ט, ד. מאמרי אדה\"א שמות ח\"א ע' א. וש\"נ. ח\"ב ע' שסז. נ\"ך ע' רעח. תו\"ח לך פג, ג."],["1640","27","<b>בע\"ח. . המצו' להוסיף אור באצילות</b>: ראה ע\"ח (שער מ\"ן ומ\"ד) של\"ט, די\"א כלל טז. הנסמן במאמרי אדה\"א שמות ח\"ב ע' תיג. תו\"ח לך פ, ג ובהערה 31."],["1641","28","<b>כי חלק הוי\"ה עמו</b>: האזינו לב, ט."],["1642","29","<b>שישראל עלה במח'</b>: נסמן לעיל לז, ב."],["1643","30","<b>שנמלך בנשמתן של צדיקים</b>: ראה ב\"ר פ\"ח, ז. רו\"ר פ\"ב, ג. שע\"ת ח\"ב מא, ב."],["1644","31","<b>אלה המצות</b>: נסמן לעיל סח, ב."],["1645","32","<b>שאנו אומרים</b>: בברכת אלקי נשמה."],["1646","33","<b>ויברא. . וייצר</b>: בראשית א, כז. ב, ז."],["1647","34","<b>לכבודי בראתיו יצרתיו</b>: ישעי' מג, ז [ושם: ולכבודי]."],["1648","35","<b>חי ה'. . הנפש הזאת</b>: ירמי' לח, טז. ראה גם לקמן צח, ב. שע\"ת ח\"א נז, א. מאמרי אדה\"א קונטרסים ע' שו. וש\"נ."]]],[2800530142,"שאמר וחי בהם ממש וכן במצות ת\"ת בכללות הכל אמ' כי אמרתך חייתני<sup data-n=\"1649\">1</sup> וכה\"ג וראי' לכל זה הוא מ\"ש והלך לפניך צדקך<sup data-n=\"1650\">2</sup> שכל צדקה ומצוה שעושה אדם בעוה\"ז מוליך לנשמתו בג\"ע כו' וגם בעה\"ז אנו רואים שצדקה תרומם גוי<sup data-n=\"1651\">3</sup> ותציל ממות<sup data-n=\"1652\">4</sup> כו' וכן במצות תפילין נאמר כי שם הוי\"ה נקרא עליך<sup data-n=\"1653\">5</sup> ויראו ממך ובמצות תלמוד תורה נשמר מכל קטרוג רע ברוחניות וגשמיות וכה\"ג אף על פי ששכר מצוה בהאי עלמא ליכא הרי אמרו אלו דברים<sup data-n=\"1654\">6</sup> שאדם אוכל פירותיהן בעוה\"ז והקרן קיימת לעוה\"ב כו' ובפרט בזמן בהמ\"ק שכל חיותם ושפעם הגשמי בברכה בבית ובחוץ הכל הי' ע\"י המצות דוקא כמ\"ש אם בחקותי תלכו כו' ונתתי גשמיכם<sup data-n=\"1655\">7</sup> כו' וכ\"ש מצות הקרבנות בבהמ\"ק שהיה האור ושפע האלקית נמשך על ידן לכל ישראל וכמו עבודת כ\"ג ביום הכפורים בבגדי לבן ובגדי זהב וכל עבודת היום ובפרט עבודתו בהיכל ק\"ק שהיה נמשך ברכה לישראל על כל השנה לפי שמצות עבודה דכ\"ג ביו\"כ היה מרומם ומעלה לנשמת הכ\"ג להיות לו כח לעורר חסדים ור\"ר העליונים מי\"ג מדה\"ר כו' ונמצא מובן עכ\"פ שהמצות גבוהים הרבה מנש\"י שלמטה עד שמעלין אותם לתכלית העילוי ברוחניות וגשמיות וזהו היפך ענין הנ\"ל במדרגה הפנימית בשורש נש\"י שגבוהין מן המצות הרוחניות דאצי' עד שעושין וממשיכים למצות דאצי' להוסיף אור באצי' כנ\"ל וזהו כמו ב' הפכים לכאורה והכל במקום אחד בנש\"י אך הענין מובן שאין זה ב' הפכים כלל דמצד בחי' הפנימית דכנ\"י למעלה מעלה הן המנשאין ומעלין למצות ומצד בחי' החיצוניות שלהם מטה הן מקבלים האור והשפע שלהם מן המצות והמצות מנשאין אותן ומ\"מ ה\"ז כמו ב' הפכים בנושא א' ויובן זה ע\"ד דוגמא כמוהו שמצינו בארון האלקים שאמרו ארון נושאיו נשא<sup data-n=\"1656\">8</sup> כו' שגם כאן הרי יש ב' הפכים כאחד שאם נשאוהו נושאים הרי יש בכח הנושאים להגביהו כו' ומה שנושאיו נשא הרי הארון מקור העולה וגבוה מהם שנושא לנושאיו ושניהם אמת דאע\"פ שנשאוהו נושאים הוא נושא לנושאיו כמו והחיות נושאים את הכסא<sup data-n=\"1657\">9</sup> שנושאות ונישואות כו' ויובן זה ע\"ד הנ\"ל במצות וכנ\"י דאע\"פ שהמצות מנשאים לישראל ישראל מנשאים למצות (או להיפך דאע\"פ שישר' מנשאים למצות מצד שרשם בפנימית מ\"מ המצות מנשאים אותם והכל אחד ואין המשל דומה עם הנמשל לכאורה דמה שארון נושאיו נשא היינו מפני שבו שוכן האור האלקי המהו' את המרכב'<sup data-n=\"1658\">10</sup> הנושאים כמ\"ש אדני בם<sup data-n=\"1659\">11</sup> כו' ע\"כ גם מה שיש בכחם לנשאות בהעלאת מ\"ן שלהם בא ונמשך מכח ואור האלקי שבארון וזהו שנושא לנושאיו (כמו ענין כח המעל' מ\"ן כו') וזהו ונישואות כו' או כמו דתפיס בכ\"ע<sup data-n=\"1660\">12</sup> ולית מאן דת\"ב וכן הוא מקומו ש\"ע<sup data-n=\"1661\">13</sup> ואין העולם מקומו כך בא אור האלקי מתצמצם ונתפס במרכבה עד שנושאות את הכסא ובאמת למדת\"ב וד\"ל אבל בענין המצות א\"א לומר כן דמה שהמצות מנשאים לישראל מצד שרשם למעלה ונש\"י הן למטה וכן להיפך דכנ\"י מנשאים למצות מצד שרשם למעלה והמצות הן למטה שניהם אמת ואינו דומה לענין ארון ונושאיו אלא צ\"ל דבזה דומה לארון ונושאיו",[["1649","1","<b>כי אמרתך חייתני</b>: תהלים קיט, נ."],["1650","2","<b>והלך לפניך צדקך</b>: ישעי' נח, ח. סוטה ג, ב."],["1651","3","<b>שצדקה תרומם גו'</b>: משלי יד, לד."],["1652","4","<b>שצדקה. . ותציל ממות</b>: משלי י, ב. יא, ד."],["1653","5","<b>כי שם הוי\"ה נקרא עליך</b>: תבוא כח, י."],["1654","6","<b>ששכר מצוה. . אלו דברים</b>: קידושין לט, ב. ראה מאמרי אדה\"א שמות ח\"ב ע' שטז. וש\"נ. קונטרסים ע' שיא ואילך."],["1655","7","<b>אם בחקותי. . ונתתי גשמיכם</b>: בחוקותי כו, ג. ד."],["1656","8","<b>ארון נושאיו נשא</b>: ראה סוטה לה, א. מאמרי אדה\"א בראשית ע' שעג. וש\"נ."],["1657","9","<b>והחיות נושאים את הכסא</b>: ראה בחיי תרומה כה, י בשם הפדר\"א פ\"ד. הנסמן במאמרי אדה\"א בראשית שם."],["1658","10","<b>המהו' את המרכב'</b>: כנראה קאי על והחיות נושאים את הכסא."],["1659","11","<b>אדני בם</b>: תהלים סח, יח."],["1660","12","<b>דתפיס בכ\"ע</b>: נסמן לקמן קטו, ב."],["1661","13","<b>הוא מקומו ש\"ע</b>: נסמן לעיל ב, א."]]],[2800530143,"דאע\"פ שישראל מנשאים למצות מצד שרשם למעלה להוסיף אור בע\"ס באו\"כ מ\"מ המצות שלמטה מנשאים אותם מפני שיש כח במצות בשרשם במהו\"ע לנשאות לנושאיהם כמו בארון לפי שגם שמלובשים בגשמיות למטה אין זה תפיס' והלבשה כלל ויכולים לנשאו' לנש\"י אע\"פ שנשמות ישראל בשרשם למעלה בפנימית כו' והיינו מטעם דסוף מעשה עבמ\"ת כו' ע\"כ נותנים כח לישראל לנשאות המצות גם למעלה דמצות שלמטה גבוהים ממצות שלמעלה וכידוע בענין שכר מצוה מצוה עצמה שמזה נמשך מקור חיי העוה\"ב<sup data-n=\"1662\">14</sup> והוא קיבול שכר לנשמות גם לפ\"ע שרש מדרגתם למעלה בפנימית אא\"ס כמ\"ש להנחיל אוהבי יש<sup data-n=\"1663\">15</sup> כו' ומזה ראיה ברורה לענין מעלת המצות דנושאיהם נושאים כמו בארון וד\"ל) והיותר נכון שגם בארון מה שנושאיו נשא הרי זה דבר והיפוכו כאחד ושניהם אמת והיינו מטעם המבו' במ\"א דיש כח במרכב' דפני ארי' ושור לנשאות לבחי' אדם<sup data-n=\"1664\">16</sup> שעל הכסא מצד שרש הבהמות וחיות בבחינת התהו שקדם לתיקון וכמו שאנו רואים למטה באדם שיחי' ויקבל שפעו מבשר וכה\"ג ומ\"מ האדם מעלה לבשר באכלו כידוע דמ\"ה מברר לב\"ן<sup data-n=\"1665\">17</sup> וכך הארון שבו הלוחות בחי' אדם נושאיו נשא וגם זה אמת שיש בכחם מדרגה עליונה לנשאות הארון וא\"כ זהו כמו שלא נודע ראש וסוף מאחר שנושאים זה לזה כמו עד\"מ הראש ורגל שהרגל מעמיד לראש והראש מוליך לרגל כידוע לפי שיש בזה מה שאין בזה וכלולים זע\"ז עד שזה מקבל מזה וזה משפיע לזה ולא נודע מי משפיע ומי מקבל כו' (ועד\"ז הוא בענין המצות דהמצות משפיעים לנשמות שלמטה ונשמות שלמעל' מעלה משפיעים למצות וזה מקבל מזה כו' עד שלא נודע ראש וסוף דשניהם אמת וע\"כ יש כאן דבר והיפוכו כאחד כו' ולפ\"ז המשל עם הנמשל אחד הוא ממש כו' וד\"ל):\n(מג) <b>ובכל</b> הנ\"ל יובן מ\"ש אז ישיר משה כו' פי' אז משמעו לשעבר כתרגומו מקדמת דנא<sup data-n=\"1666\">18</sup> כו' וישיר משמעו להבא והל\"ל אז שר אבל איך אמר דבר והיפוכו כאחד עבר ולהבא יחד אז ישיר כו' וכן יש להבין מ\"ש משה ובנ\"י דהל\"ל ישירו וכולל בנ\"י בלשון יחיד ישיר דמשה אך משום דמשה ובנ\"י ג\"כ ב' הפכים כאחד דשרש משה מבחי' או\"י ובנ\"י מבחינת או\"ח שהוא מל' דיושר והיינו ענין עבר ולהבא דאז ישיר כאחד שנתחברו יחד כו' וביאור הדברים הנה יובן ע\"ד הנ\"ל בישראל ומצות שמנשאים זה לזה ומתחברים כאחד כו' דהנ' מבואר למעל' בשרש ענין קי\"ס שנבקע הים מפני ישראל שזהו התגברות דאו\"י על או\"ח ובאמת עיקר בקיעת הים הי' מפני משה דוקא כמ\"ש ויט משה את ידו על הים<sup data-n=\"1667\">19</sup> כו' וכמו בוקע ים לפני משה<sup data-n=\"1668\">20</sup> דוקא דשרש נשמת משה מן המים עליונים משיתיהו<sup data-n=\"1669\">21</sup> שהוא מבחי' קדם אשר לא נעשו<sup data-n=\"1670\">22</sup> כו' וזהו אז מקדמת דנא מבחי' קדמון לכל הקדומים<sup data-n=\"1671\">23</sup> הנ\"ל והים הוא מבחי' מל' דעגולים ע\"כ גבר או\"י דמשה על או\"ח דים כו' וכך הי' ענין חיבור דמשה ובנ\"י שבנ\"י הן מבחי' מל' דיושר כנ\"ל בפי' ארץ שרצתה לעשות רצון קונה וכמו שהי' במ\"ת שאמרו נעשה<sup data-n=\"1672\">24</sup> שתשוקתם בבחי' מקבל לקבל בנפשם בחי' המעשה דוקא שזהו ענין הרצוא והתשוקה לקבל גלוי המשכת אלקות ע\"י",[["1662","14","<b>מצוה. . חיי העוה\"ב</b>: ראה גם מאמרי אדה\"א בראשית ע' שצב. וש\"נ. תו\"ח לך פג, א ובהערה 11."],["1663","15","<b>להנחיל אוהבי יש</b>: משלי ח, כא."],["1664","16","<b>כח במרכב'. . לנשאות לבחי' אדם</b>: ראה מאמרי אדה\"ז אתהלך לאזניא ע' קעא. תקס\"ט ע' קנג. תו\"א יתרו עב, ב."],["1665","17","<b>דמ\"ה מברר לב\"ן</b>: נסמן לקמן קלג, א."],["1666","18","<b>אז. . מקדמת דנא</b>: נסמן לעיל נ, א."],["1667","19","<b>ויט משה. . הים</b>: בשלח יד, כא."],["1668","20","<b>בוקע ים לפני משה</b>: תפלת ערבית."],["1669","21","<b>מן המים. . משיתיהו</b>: ראה מאמרי אדה\"א שמות ח\"ב ע' שצד. וש\"נ."],["1670","22","<b>קדם אשר לא נעשו</b>: ישעי' מו, י."],["1671","23","<b>קדמון לכל הקדומים</b>: נסמן לעיל נא, א."],["1672","24","<b>במ\"ת שאמרו נעשה</b>: יתרו יט, ח. משפטים כד, ז."]]],[2800530144,"תו\"מ בפ\"מ כנ\"ל ושרש משה מבחי' המשפיע שהרי נקרא שושבינא דמלכא<sup data-n=\"1673\">1</sup> דוקא שמביא וממשיך לגלוי אור א\"ס מלמעלה למטה ע\"י תו\"מ כמ\"ש תורה צוה לנו משה<sup data-n=\"1674\">2</sup> כו' וכמו במ\"ת שהי' משה מדבר כו' כמ\"ש משה ידבר<sup data-n=\"1675\">3</sup> כו' להיותו מבחי' או\"י דבחי' חב\"ד דיושר כו' ובנ\"י הן מבחי' מל' דיושר וגבר כח החסדים דמשפיע דבחי' משה על בחי' או\"ח דבנ\"י ומהפך אותם למדריגתו להיות גם הם בחי' משפיעים וממשיכים גלוי אור א\"ס בתו\"מ כו' וכנ\"ל דהמצות מקבלים מישראל כו' וזהו אז ישיר משה ובנ\"י אז מקדמין לכל כו' שזהו בחי' משה ישיר להבא שזהו בבחי' התכללות דבר והיפוכו דאו\"י דמשה ואו\"ח דבנ\"י שהוא בחינת עבר ולהבא כאחד והענין הוא לפי שנעוץ תחילתן בסופן<sup data-n=\"1676\">4</sup> וסופן בתחלתן מבלי שימצא ראש וסוף<sup data-n=\"1677\">5</sup> כו' אך כעת התכללות זו דסופן בתחילתן הוא בהעלם ולע\"ל יתגל' דהיינו בימי משיח שיקראו בנ\"י ארץ חפץ כו' כנ\"ל ולכך אמר לשון להבא ישיר שזהו לעתיד דוקא ועכשיו נתחברו עבר דאז עם ישיר דלהבא בהעלם עכ\"פ לפי שסוף מעשה דבנ\"י עלה במח' הקדומה דקדמון כו' וד\"ל וזהו דוקא בקי\"ס שהוא מעין דלעתיד כנ\"ל נתחברו או\"י ואו\"ח דמשה ובני ישראל על כן אמר אז ישיר ב' ההפכים כאחד כו' ודי למבין ויובן זה על דרך הנ\"ל בחיבור ב' הפכים כאחד כמו בארון שנושאיו נשא וכן במצות מעשיות שמנשאים לישראל וישראל מנשאים למצות כו' דשניהם אמת דמצד הפנימית דישראל מנשאים למצות ומצד חיצוניות שלהם המצות מנשאים אותן כו' ואף כאן בשעת קי\"ס הנה מצד בחי' הפנימית דישראל כמו שהם בשרשם למעלה בבחי' קדם הנ\"ל דישראל עלה במח' הקדומה שבפנימית מהו\"ע כו' ע\"כ נבקע הים מפניהם שהים הוא למטה מהם (שהוא בחי' או\"ח דעיגולים דתהו כנ\"ל אע\"פ שנקרא ים הקדמוני הרי אמר שיצאו מ\"ח מירושלים<sup data-n=\"1678\">6</sup> אל הי\"ק לפי שמח' הקדומה שישר' עלה שם הוא סוף מעש' שעבמ\"ת כו' וזהו ארץ שרצתה כו' כנ\"ל) וכמו לרוקע הארץ<sup data-n=\"1679\">7</sup> כו' יקוו המים ותרא' היבש'<sup data-n=\"1680\">8</sup> כנ\"ל וזהו כמו שישראל מצד הפנימית שלהם שמוסיפים אור גם במקיף הכללי דע\"ס בתוס' אור חדש בכלים כנ\"ל הטעם וזה היה עיקר הכונה שהעביר ישראל בתוך הים שיבקע הים ויעברו בתוכו ביבשה דוקא כדי שיהיה מזה הכנה למ\"ת שיקבלו תו\"מ באופן שע\"י מעשה המצות שלהם דוקא יעלו למצו' העליונות כנ\"ל וד\"ל אך יש בזה דבר והיפוכו דהיינו כמו מה שיש בכח המצות לנשאות ולהעלות לנש\"י מצד בחי' החיצוניות דישראל שהן למטה מן המצות וכך הי' בענין העבר' שלהם בים בשביל עלי' לנש\"י שהן למטה בגופים שהוא ע\"י הים דוקא שיש בים מעלה ומדריגה יתירה עד שיש ביכולתו להעלות ולנשאות לישראל כמו שהמצוה מגביה ומעלה לנפ' האלקית (משום דים הוא בחי' עיגולים דתהו שקדם לנש\"י דתקון כו') וענין הבקיעה שנבקע הים מפני ישראל שאו\"י גבר על או\"ח כנ\"ל היינו כמו שהנפ' אלקית בשרשה עושה את המצות למעלה ושניהם אמת וזהו כמו שארון נושאיו נשא דשניהם אמת דמה שנשאו נושאים לארון (משום דבחי' ב\"ן דתהו בשרשו למעלה מבחי' אדם דתיקון כנ\"ל) שזהו כמו המצות שמנשאים לנשמות ישראל (לפי שהמצות מבירורים",[["1673","1","<b>משה. . שושבינא דמלכא</b>: ראה זהר (רע\"מ) ויקרא כ, א. הנסמן במאמרי אדה\"א דברים ח\"א ע' קג. שמות ח\"ב ע' שטו וע' שכז."],["1674","2","<b>תורה צוה לנו משה</b>: ברכה לג, ד."],["1675","3","<b>משה ידבר</b>: יתרו יט, יט."],["1676","4","<b>שנעוץ תחלתן בסופן</b>: ראה ס\"י פ\"א מ\"ז."],["1677","5","<b>מבלי שימצא ראש וסוף</b>: ראה קהלת ג, יא."],["1678","6","<b>שיצאו מ\"ח מירושלים</b>: זכרי' יד, ח."],["1679","7","<b>לרוקע הארץ</b>: תהלים קלו, ו."],["1680","8","<b>יקוו המים ותרא' היבש'</b>: בראשית א, ט."]]],[2800530145,"דרפ\"ח דתהו שקדם לנשמות ישראל דתיקון כו') וכמו הים שנשא והגביה לנש\"י (מטעם הנ\"ל וד\"ל) ומה שארון נושאיו נשא היינו כמו שהנפש אלקית מצד בחי' הפנימית למעלה מעלה ומגביה ועושה למצו' כו' וזהו כמו שנבקע הים מפני ישראל דגבר או\"י על או\"ח מצד שרשו של או\"ח בבחי' פנימית ממש דג' קשרין הן ישראל ואוריי' וקוב\"ה הכל בבחי' סתי' שהוא סדכ\"ס עצמו דלמת\"ב כלל אפי' בחי' הים הקדמוני בחי' סובב הכללי כו' וד\"ל ונמצ' עכ\"פ שנתחברו בקי\"ס או\"י ואו\"ח באופן שנושאי' זא\"ז ואין לחל' ביניהן למצו' בהם ראש וסוף וד\"ל (ובאמ' י\"ל בהיפך דמה שנבקע הים מפני ישראל שגבר או\"י על או\"ח היינו מצד נש\"י שלמטה בתו\"מ בפ\"מ שעבמ\"ת סוף מעשה דוקא וזה היה הכנה למ\"ת לקיום תו\"מ בפ\"מ למטה דוק' וזהו כמו שהמצות בציור אדם למטה מנשאי' לנש\"י מצד סוף מעש' דמצות כשהן בגשמיות דוקא כמו והלך לפניך צדקך וכנ\"ל ומה שנתעלו נש\"י ע\"י הים היינו מפני שעלו נש\"י ע\"י הים במח' הקדומה דים הקדמוני כו' שזהו כמו שהנש\"י בשרשם שמעלין למצות עליונות לעשות לאדם דאצי'<sup data-n=\"1681\">9</sup> (וכך משמע בזהר בעיקר ענין קי\"ס שזה היה עליות הנשמות מבריאה לאצי' שהבקיעה היא ג\"כ מלמטה למעלה אך לפי' האריז\"ל<sup data-n=\"1682\">10</sup> בקי\"ס שהוא כמו לידת הנשמות מלמעלה למטה א\"כ הרי בבקיעת הים מחולקי' ולפ\"ד הזהר עליי' לנש\"י ע\"י הים ע\"י הבקיע' ולפ\"ד האריז\"ל הבקיעה היה ירידה שזהו התגברות דאו\"י על או\"ח להורידו למטה שהוא כישראל מנשאים למצות שזהו כפי' הא' וממילא מובן דעלי' דנש\"י ע\"י הים זהו כמו המצות שמנשאים לישראל ולפ\"ד הזהר זהו כישראל שמנשאים למצות כפי' הב' וד\"ל) והנה כמו כן ע\"ד כל זה היה חיבור משה ובנ\"י דכמו שלגבי הים נק' ישראל או\"י וגובר על או\"ח דים כך משה לגבי ישראל נק' או\"י שגובר על או\"ח דכנ\"י הוא מבחי' מל' דיושר כנ\"ל ומשה השפיע להם תו\"מ מבחי' הרוחניו' דח\"ע למטה בגשמיות כו' וזה היה ענין שירת הים דבקיעת הים ענין בפ\"ע ושירת הים ענין בפ\"ע דהיינו ששירת הים הוא בחי' הפנימי' המכוון שבבקיעת הים וכמו שבבקיעת הים היה משה עיקר וישראל טפל כנ\"ל כך גם בשירת הים כשכבר נכנסו בתוך הים אמר משה השירה וזהו אז ישיר משה דוקא ובנ\"י נכללו בו וזהו ישיר לשון יחיד והענין הוא דמשה הי' מקור התו\"מ כמו שהוא למעלה בפנימית מהו\"ע כמ\"ש ואהיה אצלו אמון<sup data-n=\"1683\">11</sup> אצלו ממש שעשועי' העצמיי' וכו' ואע\"פ שישראל ג\"כ עבמח\"ק<sup data-n=\"1684\">12</sup> זהו בחי' חיצוניות לגבי פנימיות זו ויש כאן חיבור דבר והיפוכו כא' עד מבלי שימצא ראש וסוף ע\"ד הנ\"ל בבקיעת הים ובמצות וישראל וכמו ארון נושאיו נשא כו' דאז בחי' קדם דמשה וישיר להבא וכן משה ובנ\"י יחדיו ידובקו מבלי ימצא בהן ראש וסוף דודאי כמו שארון נשאוהו נושאיו) כטעם<sup data-n=\"1685\">13</sup> הנ\"ל במצוה שתהו קדם לתיקון בשרשו) כך יש כח ברצוא דאו\"ח דיושר דישראל שאמ' נעשה וכארץ שרצתה כו' לנשאות למשה (וראי' כשחטאו ישראל בעגל אמר למשה לך רד כלום<sup data-n=\"1686\">14</sup> כו') וכארון שנשא לנושאיו",[["1681","9","<b>דאצי'</b>: אוצ\"ל: דאצי')."],["1682","10","<b>בזהר. . האריז\"ל</b>: ראה זהר בשלח מח, ב. פע\"ח (שחה\"מ) שכ\"א, פ\"ח. לקמן פד, א. פו, א ואילך. סידור שחה\"מ רפט, ד ואילך. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רנח ואילך. מאמרי אדה\"א ויקרא ח\"א ע' ריב ואילך וע' רנ ואילך. תו\"ח בשלח רפ, א."],["1683","11","<b>ואהי' אצלו אמון</b>: משלי ח, ל."],["1684","12","<b>עבמח\"ק</b>: עלו במחשבה קדומה."],["1685","13","<b>נושאיו) כטעם</b>: אוצ\"ל: נושאיו (כטעם."],["1686","14","<b>לך רד כלום</b>: תשא לב, ז. ברכות לב, א."]]],[2800530146,"כך משה נשא לישראל כאשר ישא האומן<sup data-n=\"1687\">1</sup> כו' (כמו שנש\"י בשרשם מעלין למצות וכמו שנבקע הים מפני ישראל כנ\"ל הטעם בפי' הא') דאו\"י גובר על או\"ח כמו ביטול דרצוא בתפלה לגבי בחי' שוב דהמשכת מ\"ה דתורה כך נתבטל רצוא דאו\"ח דמל' דיושר שרצתה כו' לגבי אור אמיתית פנימית ההמשכה דח\"ע שבתו\"מ כו' ולהיות כן לא נודע מי ראש ומי סוף כו' שכלולים זע\"ז והיו לאחדים ממש (ולפי' הב' בבקיעת הים יתפרש ג\"כ עד\"ז בשירת הים דמשה ובנ\"י דהכל ענין א' הוא וד\"ל) וזהו אז ישיר משה ובנ\"י שזה השיר הי' תכלית ההכנה למ\"ת בתו\"מ שניתן ע\"י משה לישראל ובא לקיום בפו\"מ דור אחר דור עד ימות המשיח דקאי ע\"ז ישיר להבא שאז יתגלה התכללות זו דסופן בתחלתן תחלתן בסופן עד מבלי שימצא ראש וסוף שעכשיו הוא בהעלם בתו\"מ דמשה ובנ\"י ובשירת הים היה בגילוי מעין דלע\"ל שיקראו בנ\"י ארץ חפץ כו' שסוף מעשה יעלה לתחלת התחלות דבחי' קדם דאז וזהו אז ישיר עבר ולהבא כאחד וכן משה ובנ\"י ועכשיו הוא בהעלם כארון שנושא לנושאיו וכה\"ג וד\"ל ובכל זה יובן מ\"ש שני פסוקים בענין קי\"ס הא' מ\"ש לגוזר ים סוף לגזרים כל\"ח והב' מ\"ש והעביר ישראל<sup data-n=\"1688\">2</sup> בתוכו כל\"ח דלכאורה חסד א' הוא מה שגזר הים והעבירם בתוכו ולמה חלקם לב' חסדים אך עפ\"י הנ\"ל יובן דגוזר הים זהו בקיעת או\"י על או\"ח דהיינו שרש נש\"י שהן בבחי' או\"י שגובר על או\"ח דגלי הים שיתבטלו ממציאות עלי' כו' וזהו כי לעולם חסדו שיהיה תוס' אור וחסד עליון לעולם הנאצל להיות עושים המצות למעלה כנ\"ל והב' מה שהעביר לישראל בתוך הים שיהי' עליי' לישראל ע\"י הים כמו שהמצות מעלין לישראל שבגופים כנ\"ל כל\"ח חסד לעולם שלמטה ושניהם כלולים כא' מבלי שימצא ראש וסוף כלל כענין ארון נושאיו נשא כו' כנ\"ל (או להיפך דהעברת ישראל בים להעלות לים ע\"י שעברו ביבשה דוקא בתוך הים והוא קיום התו\"מ בפ\"מ שסוף מעשה עבמ\"ת כו' ומה שנתעלו ישראל ע\"י הים הוא ע\"י מה שגזר י\"ס לגזרים נגד י\"ב שבטים שיעלה כל שבט לשרשו העצמי כו' וד\"ל) (וזה יותר נכון דשירת הים יוכיח שהי' בעברם בתוך הים ביבשה דוקא ושירת הים כמו לע\"ל הוא):\n(מד) <b>והנה</b> מעתה יש להבין מ\"ש עוד וניער פרעה וחילו<sup data-n=\"1689\">3</sup> בי\"ס כל\"ח מה זה שייך לב' פסוקים דסמיך לי' לגוזר י\"ס והעביר ישראל כו' ועוד למה חלק זה לדבר חסד בפ\"ע הלא ממילא נעש' זה שנטבעו פרעה וחילו אחר שעברו ישראל בתוך הים כו' כידוע אך הענין יובן ע\"פ מ\"ש בזהר דכד ארי' ואריותא<sup data-n=\"1690\">4</sup> קיימין לאזדווגא ווי למאן דעאל ועבר ביניהון להפרידם שניזוק מיד כו' וזהו משל לבחי' יחוד עליון דארי' עילאה כו' דאריה גי' גבור'<sup data-n=\"1691\">5</sup> גבורה עילא' והוא בחי' גבורו' דמשפיע כשרוצ' להשפי' לנוק' שנק' אריות' כו' וכמ\"כ בחי' גבורה תתאה דנוק' שתשוקת' להתייח' בדכור' והיינו בחי' היחוד דאו\"י דדכר עם או\"ח דנוק' כאשר באין להזדווג ולהתכלל יחד כנ\"ל בענין אז ישיר משה ובנ\"י או ישראל בעברם בים כו' אז ווי למאן דעבר ביניהם להפריד יחודם שהן פרעה",[["1687","1","<b>כאשר ישא האומן</b>: בהעלותך יא, יב."],["1688","2","<b>לגוזר ים סוף. . והעביר ישראל</b>: תהלים קלו, יג. יד."],["1689","3","<b>וניער פרעה וחילו</b>: תהלים קלו, טו."],["1690","4","<b>דכד ארי' ואריותא</b>: ראה זהר ואתחנן ער, א."],["1691","5","<b>דאריה גי' גבור'</b>: ראה פי' הראב\"ד לס\"י פ\"א מי\"ב. מאו\"א מערכת ארי' סק\"א. מאמרי אדה\"א דברים ח\"ג ע' א'ל. וש\"נ. ד\"ה דור לדור מכ\"ק אדה\"א (קה\"ת תשנ\"ב) ע' 18. וש\"נ. שע\"ת ס, א."]]],[2800530147,"וחילו שרדפו אחריהם בים להפריד בין הדבקים כו' ע\"כ נטבעו ונאבדו מיד כמ\"ש וברוח אפיך נערמו מים כו' קפאו כו' עד נשפת ברוחך<sup data-n=\"1692\">6</sup> כו' צללו כעופרת כו' וזהו שאמ' וניער פרעה וחילו בענין חסד בפ\"ע שרצה פרעה להפריד היחוד עליון דאו\"י ואו\"ח וניערו בים כו' בבחי' תוקף הגבורות עליונות על המנגד ליחוד עליון דאו\"י ואו\"ח כי פרעה וחילו הן דכר ונוק' דקליפה שזהו סוס ורוכבו<sup data-n=\"1693\">7</sup> כו' והוא המונע אור השפע עליונה דבחי' או\"י לירד למטה וגם מונע עליי' המקבל בבחי' או\"ח ולפי שבקי\"ס נתחברו יחד או\"י ואו\"ח מבלי יפרדו כלל אז נמשך תוקף הגבורות על המפרידם כמשל הנ\"ל בארי' ואריותא שמפני תוקף התשוקה זע\"ז להזדווג יגבר יותר תוקף החימה על העובר ביניהם להזיקו כו' וד\"ל וזהו שאמ' תחילה ב' פסוקים בענין היחוד דאו\"י ואו\"ח שהוא מ\"ש לגוזר י\"ס שגבר או\"י על או\"ח להמתיקן והעביר ישראל כו' שזהו ג\"כ עליי' דנש\"י ע\"י הים בבחי' או\"ח כו' ושניהם כלולים כא' מבלי שימצא בהם ראש וסוף כלל כנ\"ל בענין בקיעת הים ובענין שירת הים דמשה ובנ\"י ע\"כ מיד וניער פרעה כו' כשרצה להפרידם וע\"כ אמר זה לבחי' חסד לעולם בפ\"ע כדי שיהיה קיום ליחוד עליון דאו\"י ואו\"ח בתו\"מ דישראל לעולם וד\"ל אך הנה עדיין יש להבין בזה דאם היה היחוד עליון הזה דאו\"י ואו\"ח כדוגמת היחוד דדכר ונוק' בתשוקה והתכללות יתכן שיפול כעס וחרון אף גדול על המונע ומפריד כו' אבל באמת הרי בחי' או\"י ואו\"ח המה מנגדי' זע\"ז בתכלית כאש ומים שזה טבעו לירד מגבוה לנמוך כמים וזה טבעו לעלות כאש כו' וע\"כ אמר לגוזר ים סוף שגבר או\"י על או\"ח ונבקע הים שנתבטל ממציאת עליית גליו כמו בשוא גליו אתה תשבחם<sup data-n=\"1694\">8</sup> להשקיטם כנ\"ל וא\"כ איך שייך בזה ענין יחוד בתשוקה עד שיפול גבורות ודינין על המונע ומפריד היחוד כו' ואמנם אין זה קושיא כ\"כ שהרי גם בדכר ונוק' יש ב' הפכים אלה דחו\"ג כמים ואש ממש דתיאובתא דדכורא<sup data-n=\"1695\">9</sup> לנוק' בבחי' מי החסדים להתמשך ולהתדבק בשפע מ\"ד באהבה ולא ברשפי אש צמאון משא\"כ בנוק' תיאובתא<sup data-n=\"1696\">10</sup> דילה ברשפי אש צמאון כמו ואל אישך תשוקתך<sup data-n=\"1697\">11</sup> בבחי' העלאה כאש העולה כו' ועכ\"ז תשוקת שניהם להתייחד זע\"ז משום דהיא הנותנת דלפי שהזכר בבחי' חסדים<sup data-n=\"1698\">12</sup> והנוק' בבחי' גבורות<sup data-n=\"1699\">13</sup> תשוקתם להכלל זע\"ז כו' וכמו\"כ ביחוד עליון הרוחני דאו\"י ואו\"ח למעלה לפי שהן ב' הפכים בחי' או\"י הוא בבחי' ירידה והמשכה כמים וטבע או\"ח לעלות כאש כו' ע\"כ תשוקתם להתייחד ולהכלל זה עם זה דוקא וממילא יפול הדין והכעס על המנגד כמו על דרך דוגמא בבחי' רצוא ושוב שבתפלה כאשר יתפעל ברצוא בתשוקה שבלב לעלות ולידבק באחד מיד ירצה בחשק ההמשכ' וירידה שיהי' גלוי אלקות בנפשו באמצעות תו\"מ ויפול מצמאון הראשון והא בהא תליא שכאשר אין לו בחי' רצוא בצמאון לא יהי' לו החשק ואהבה בגלוי אור אלקי בתו\"מ כלל שהרי האומר אין לו אלא תורה<sup data-n=\"1700\">14</sup> אפי' תורה אין לו וכן להיפך בצמאון שבתפלה בלא תו\"מ יפול הנופל במעט רגע כידוע וד\"ל אך יש להבין עוד שלכאורה יש סתירה גדולה לכל ענין הנ\"ל בבחי' בקיעת או\"י על או\"ח דמשמע שכל עיקר ענין קי\"ס אינו רק מה שגבר האו\"י על או\"ח ובאמת מצינו מפורש במקרא שעיקר סיבת",[["1692","6","<b>וברוח אפיך. . נשפת ברוחך</b>: בשלח טו, ח. י."],["1693","7","<b>דכר ונוק'. . סוס ורוכבו</b>: נסמן לעיל לו, ב."],["1694","8","<b>בשוא גליו אתה תשבחם</b>: תהלים פט, י. לעיל סח, א."],["1695","9","<b>דתיאובתא דדכורא</b>: ראה זהר נח סו, ב. לך פה, ב. תרומה קסה, סע\"א."],["1696","10","<b>בנוק' תיאובתא</b>: ראה זהר בראשית לה, א. נח ס, ב. לך פה, ב."],["1697","11","<b>ואל אישך תשוקתך</b>: בראשית ג, טז."],["1698","12","<b>שהזכר בבחי' חסדים</b>: ראה זהר תזריע מח, ב. נשא קמה, ב. ע\"ח (שער מ\"ן ומ\"ד) שט\"ל, דרוש י."],["1699","13","<b>והנוק' בבחי' גבורות</b>: ראה זהר בראשית מח, ב. אחרי סה, א. בהערה שלפנ\"ז. ע\"ח (שער קיצור אבי\"ע) ש\"נ, פ\"ד."],["1700","14","<b>האומר. . אלא תורה</b>: ראה יבמות קט, ב."]]],[2800530148,"קי\"ס היה כמה שאמ' ויולך ה' ברוח קדים<sup data-n=\"1701\">1</sup> עזה כל הלילה ויבקעו המים כו' הרי היה עיקר סיבת הבקיעה רק מרוח הקדים עזה הזה וזה היה קודם בחי' או\"י דישראל ומשה כו' וד\"ל אך הנה ידוע מ\"ש בזהר בכ\"מ דכד אינון תלת<sup data-n=\"1702\">2</sup> אינון ארבע פי' במצי' השלש' כאשר מתכללי' יחד בהכרח שימצ' רביעי שמחברם וכוללם יחד (וכמו שיר משולש ושיר מרובע<sup data-n=\"1703\">3</sup> מפני שבהתכללו' דת\"ת המכריע<sup data-n=\"1704\">4</sup> בהכרח ימצא בו ב' אופנים דחו\"ג הרי ד' מדריגות וכידוע בטעם ענין י\"ב ג\"א<sup data-n=\"1705\">5</sup> משום דבבחי' ת\"ת שבחו\"ג נחלק כל א' מהג' דחג\"ת לד' מדריגות<sup data-n=\"1706\">6</sup> והן התחלקות י\"ב שבטים מהאבות<sup data-n=\"1707\">7</sup> שהן ד' דגלים כו') וכמו שאנו רואים בשכל שמטה כלפי חסד שכלול מגבורה שבחסד ובחי' המכריע שביניהן הרי שלשה והרי במכריע זה כלול מב' דעות דחו\"ג דהיינו באופן ההכרעה אם לחסד יותר או לדין יותר ה\"ז ד' מדריגות בחסד וכמו\"כ במדת הדין שכלול מחסד שבדין ויש בו ג\"כ דעת המכריע הרי שלשה והוא כלול מב' לחסד ולדין הרי ד' מדריגות בבחי' הדין וכמו\"כ בבחי' ת\"ת עצמו שכלול מחו\"ג ובו יש ב' נטיות לחו\"ג הרי יש בחג\"ת י\"ב מדריגות וד\"ל (וכמו\"כ בשיר כפול דחו\"ג ושיר משולש דת\"ת הממוזג מחו\"ג כאמ\"ר<sup data-n=\"1708\">8</sup> שהרוח כלל<sup data-n=\"1709\">9</sup> מאש ומים ויש ברוח זה עצמו ב' נטיות לחסדים דמים ולגבורות דאש הרי ד' שנק' שיר מרובע וכן בגוונין דירוק שכלול מחו\"ג ונק' ארגמן<sup data-n=\"1710\">10</sup> כו') והנה בעבודת ה' יובן זה כמו התפעלות הביטול שמצד האהבה והתפעלות הביטול שמצד היראה שנק' חו\"ג וכן הוא בשיר של חדוה ושיר של מרירות והרי יש התפעלות הביטול דיראה כלול באהבה כמו וגילו ברעדה<sup data-n=\"1711\">11</sup> במקום גילה שם תהא רעדה כמו יראה דאברהם שנאמר בו עתה ידעתי<sup data-n=\"1712\">12</sup> כי ירא אלקים אתה אע\"פ שעצם מדרגתו באהבה שנק' אברהם אוהבי<sup data-n=\"1713\">13</sup> רחימא דמלכא<sup data-n=\"1714\">14</sup> כו' וכן פחד יצחק<sup data-n=\"1715\">15</sup> שהיה כלול בו מאהבה דאברהם בתוך תוכו כמו במקום גילה שמבחוץ שם תהא רעדה מבפני' כו' כך להיפך במקום פחד וביטול דיראה מבחוץ שם תהא האהבה וגילה מבפנים כמו שרי המלך שיושבים ביראה ואימת מלך ומבפנים יגילו בשמחתו או להיפך שיגילו מבחוץ ויראים מבפנים והממוצע שכלול מאוי\"ר דאברהם ויצחק הוא יעקב שאמר אלקי אבי אברהם<sup data-n=\"1716\">16</sup> ופחד יצחק היה לי שכלולים בבחי' ת\"ת שהוא הרחמים<sup data-n=\"1717\">17</sup> ובחי' ת\"ת כלול מב' אופנים דחו\"ג וכנ\"ל וזהו בחי' המל' שנק' ארגמן<sup data-n=\"1718\">18</sup> וכמ\"ש ודלת ראשך כארגמן<sup data-n=\"1719\">19</sup> שגם שמקבל מת\"ת אבל נעשה בבחי' מרובע מד' מדריגות והן י\"ב ג\"א די\"ב שבטים דנוק' אע\"פ ששרשם ביעקב שכולל רק שלש' הרי מג' נעשה ארבע' וז\"ש כד אינון תלת אינון ד' וד\"ל:\n(מה) <b>ומעתה</b> הנה יובן עד\"ז ג\"כ בענין ב' הפכים דאו\"י ואו\"ח דודאי מאחר שהמה ב' הפכים בתכלית איך יתחברו ולא עוד אלא שיש בהם תשוקה להתכלל יחד כנ\"ל בענין זיווג זו\"נ כו' א\"כ מוכרח לומר שיש כח שלישי העליון משניהם יחד שממשיך ומחבר אותם וכמו שאמ' בזהר דכד אינון ג' אינון ד' כך כאשר יש ב' הפכים עליון ותחתון יש כח ג' העליון מהם שמחברם והענין הוא לפי שנחלק כל א' וכלול מהיפוכו ע\"כ יחשוק להכלל גם דבר עם היפוכו כמו אש ומים<sup data-n=\"1720\">20</sup> לפי שיש באש מחלקי המים וכל יסוד נמשך לשרשו<sup data-n=\"1721\">21</sup>",[["1701","1","<b>וילך ה' ברוח קדים</b>: בשלח יד, כא [בדילוג]."],["1702","2","<b>דכד אינון תלת</b>: ראה זהר ויחי רמה, א. ואתחנן רסד, ב. (אד\"ז) האזינו רצב, ב. מאמרי אדה\"א במדבר ח\"א ע' עא. וש\"נ."],["1703","3","<b>שיר משולש. . מרובע</b>: ראה הנסמן לעיל מה, א (הערה שיר פשוט). תו\"ח בראשית לז, ד ואילך."],["1704","4","<b>דת\"ת המכריע</b>: נסמן לקמן קכד, ב."],["1705","5","<b>י\"ב ג\"א</b>: נסמן לקמן קכה, א."],["1706","6","<b>דחג\"ת לד' מדריגות</b>: ראה גם מאמרי אדה\"א במדבר שם ס\"ע ע ואילך."],["1707","7","<b>י\"ב שבטים מהאבות</b>: ראה גם תו\"ח חיי שרה קל, ב ובהערה 19. מאמרי אדה\"א במדבר שם ע' עא."],["1708","8","<b>כאמ\"ר</b>: ראה הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תעב."],["1709","9","<b>כלל</b>: אוצ\"ל: כלול."],["1710","10","<b>דירוק. . ארגמן</b>: ראה גם תו\"ח בראשית מא, ג. מאמרי אדה\"א שמות ח\"ב ע' תרעו. שע\"ת ח\"א טז, ד."],["1711","11","<b>וגילו ברעדה</b>: תהלים ב, יא. ברכות ל, ב. ראה מאמרי אדה\"א שמות ח\"א ע' מז. וש\"נ. שע\"ת ח\"א לה, א ואילך. תו\"ח בראשית כו, ד ובהערה 35."],["1712","12","<b>עתה ידעתי</b>: וירא כב, יב."],["1713","13","<b>אברהם אוהבי</b>: ישעי' מא, ח."],["1714","14","<b>רחימא דמלכא</b>: נסמן לעיל כה, א."],["1715","15","<b>פחד יצחק</b>: ויצא לא, מב."],["1716","16","<b>אלקי אבי אברהם</b>: נסמן לעיל שם."],["1717","17","<b>ת\"ת שהוא הרחמים</b>: נסמן לקמן קלג, ב."],["1718","18","<b>המל' שנק' ארגמן</b>: ראה זהר שלח קסג, ב [הובא ב]פרדס (שער הגוונים) ש\"י פ\"ד."],["1719","19","<b>ודלת ראשך כארגמן</b>: שה\"ש ז, ו."],["1720","20","<b>כמו אש ומים</b>: ראה גם תו\"ח בראשית יד, סע\"ב ואילך ובהנסמן במ\"מ לשם. מאמרי אדה\"א דברים ח\"ד ס\"ע א'תלא ואילך. וש\"נ."],["1721","21","<b>וכל יסוד נמשך לשרשו</b>: ראה גם מאמרי אדה\"א נ\"ך ע' תצא. וש\"נ. שע\"ת ח\"א יז, א."]]],[2800530149,"ושואב בעצמו כך אש זה הגם שהמים היפוכו אבל מים שבאש נמשך אל יסוד המים וכן אש שבמים נמשך אל יסוד האש נמצא יכול להיות תשוקת ההתכללות באש ומים לפי שב' אלה הן ד' בהתכללות דבר מהיפוכו אך באופן שיהיה בכל א' מזיגה נכונה בהתכללות זו לא ירבה ויוסיף זע\"ז רק באופן שיוכלו להכלל יחד וע\"ד דוגמא מסממני הרפואה שעושה הרופא החכם הרכבה ומזיגה במדה נכונה מדברים המחממים ודברים המקררים יחד באופן שיהיה התכללות' במדה יפה והיינו בחלוקי ההרכבה שבכל א' מן היפוכו כאשר מחלקם וממזגם אח\"כ במדה טובה לא יוסיף ולא יגרע מכפי הצריך וכן בקול ונגון שמורכב מחו\"ג הפכיי' שכל א' כלול מהיפוכו במזג נכון אזי הקול הממוזג יפה ערב ביותר וכן בטעם מורכב מחמיצו' ומתיקו' במזג יפה היינו מכל החלוקי הרכב' מדבר בהיפוכו כאשר בא ההתחלקות וההתכללות במדה יפה יהיה טעם ערב ביותר וכן בגוונין וכנ\"ל בבחי' הת\"ת שכלול מחו\"ג באופן מזיגה טובה דוקא וד\"ל ונמצא בהכרח לומר שעל כל אופני ההרכב' שבכל דבר בהיפוכו ואיך שיבא במדה נכונה לפי הצריך זהו בא מכח עליון שלמעלה מכל ההפכיים שבחו\"ג וכמו עושה שלום בין מיכאל וגבריאל שאין מכבים זא\"ז<sup data-n=\"1722\">22</sup> או כמ\"ש בס\"י טרף אש ומים<sup data-n=\"1723\">23</sup> ובללן זה בזה או כמ\"ש בע\"ח דאור החסד בכלי הגבורה<sup data-n=\"1724\">24</sup> ואור הגבורה בכלי החסד שכל אלה וכה\"ג הכל בא במזג והרכבה מדודה במדה נכונה ביותר כנ\"ל ואין זה כ\"א עפ\"י כח העליון מהכל שהוא הנקרא מאמר קו המדה<sup data-n=\"1725\">25</sup> שנותן מדה ושיעור לכל התחלקות דבר והיפוכו איך וכמה יבא בהתחלקות והתכללות בכל מציאת דבר באופן שיוכלו להכלל בתשוקה נפלאה כנ\"ל וד\"ל (וכמו בעבודת ה' בתפלה ברצוא שבצמאון האהב' בלב כלול מהיפוכו בחי' שוב דיראה במדה נכונה וכן ביראה ופחד כלול מהיפוכו מאהבה דרצוא אז גם בממוצע שביניהם מזוג יפה וכשיר מרובע כנ\"ל אזי יהיה ברו\"ש זה התכללות ויחוד וחיבור עד שלא יפרדו לעולם וכמו שאנו רואים ברו\"ש דתפלה ותורה שמתאחדים ממש ואין לא' שלימות בלא זולתו כאומר אין לי אלא תורה וכן להיפך כנ\"ל) ועד\"ז יובן גם בבחי' או\"י ואו\"ח לפי שכלול או\"י מאו\"ח ואו\"ח מאו\"י במזיגה נכונה ע\"ד הנ\"ל ע\"כ מתכללים יחד בתשוקה (וכמו בחי' רצוא שבאו\"י היינו כמו ארץ שרצתה לעשות רצון קונה הנ\"ל הרי הוא ברצוא והתשוקה עכ\"פ אע\"פ שזהו בירידת והמשכת גלוי אלקות וכן להיפך בבחי' או\"ח ממש יש בזה בחי' הביטול דכח מ\"ה שגורם ירידת והמשכת אלקות וכמו גם ברצוא דצמאון בתפלה שע\"י בחי' הביטול ושפלות גורם דוקא בחי' שוב שהוא עסק התורה לשמה ומעשה המצות בפ\"מ וה\"ז בחי' שוב שבאו\"ח וכך יש כמה מיני אופנים בדבר והיפוכו שמתכללים יחד אך כ\"ז במדה נכונה שלא יוסיף זע\"ז ולא יגרע רק כפי הצריך באופן שיוכללו הכל והיו לאחדים וזהו רק עפ\"י כח העליון הנעלה מרצוא ושוב שנותן מדידה זו כך וכך יהי' ההעלאה דאו\"ח בבחי' רצוא וכך וכך יהיה בחי' השוב דאו\"י באופן שישכנו יחדיו באופן מדידה זו דוקא בל יפרדו לעולם וא\"כ בהכרח שהממוצע הזה גבוה מכול' יחד והיינו למע' מבחי' או\"י ואו\"ח לגמרי ע\"כ ביכולתו",[["1722","22","<b>עושה שלום. . זא\"ז</b>: נסמן לקמן קכה, ב."],["1723","23","<b>טרף אש ומים</b>: נסמן לקמן קכד, ב."],["1724","24","<b>דאור החסד בכלי הגבורה</b>: נסמן לקמן קלא, א."],["1725","25","<b>מאמר קו המדה</b>: ראה לקמן קכ, ב. מאמרי אדה\"א בראשית ע' תו. וש\"נ. נ\"ך ע' עא. וש\"נ."]]],[2800530150,"לעשות מדידה בפרטית אופן היחוד ביניהם וד\"ל (וזהו מבחי' העיגול שסובב הקו והחוט שעובר מעליונו לתחתיתו שבודאי בקו\"ח זה שייך לשון עלייה וירידה שהן ב' הפכים אבל מצד בחי' העיגול עצמו שוין עלייה וירידה ואינם ב' הפכים כלל וגם באותו הקו היורד ונמשך אם מאיר בו מעצמות העיגול יש בו הכח שבעיגול עצמו וזהו משל לענין הארת הקו\"ח שנקרא קו המדה שמודד כל עליי' דאו\"ח וירידה דאו\"י איך וכמה באופן שיהיה בהם התכללות דחו\"ג כנ\"ל וד\"ל) וזהו ויט משה את ידו על הים ויולך ה' את הים ברוח קדים<sup data-n=\"1726\">1</sup> עזה כו' פי' דמה שמשה נטה ידו המשיך לבחי' רוח קדים עזה כו' שהוא מבחי' קדמון לכל כו' שנקרא קדמונו ש\"ע והיינו בחי' קדם הנ\"ל שלמעלה מעלה מבחי' ראשית ואחרית דקו שעובר מעליונו של עיגול שהוא הנקרא סובב הכללי מחשבה הקדומה כו' שאו\"י ואו\"ח לא שייך רק בבחי' ההשתלשלות דקו\"ח שעובר מלמעלה למטה ממקור האצילות עד סוף העשיה כידוע אבל בחי' רוח קדים זה הוא מעצמות אא\"ס הפשוט שלפני צמצום הראשון כו' שלמעלה מעלה מהשתלשלות דאבי\"ע גם למעלה מהיות בחי' סובב לממלא כו' (דהיינו למעלה גם ממח' אחת שצופה כו' כנ\"ל) ומה שנקרא רוח קדים עזה שהוא מבחי' הגבורות דוקא היינו להיות שזה האור העליון הנעלה מכל ההשתלשלות דאו\"י ואו\"ח העושה אופן היחוד וחיבור בהם הוא בא בבחי' גבורות וצמצומים באופן המדידה ונקרא שורש המדידה כמו מי מדד<sup data-n=\"1727\">2</sup> כו' ונקרא קו המדה שהוא מקור כל מדידה כו' (והן בחי' ה' גבורות דבצ\"ק<sup data-n=\"1728\">3</sup> שלפני האצילות כידוע ונקרא בזהר בל' משחתא<sup data-n=\"1729\">4</sup> כו') כנ\"ל שבא למדוד כמה יהי' באו\"י ואו\"ח כו' (וזהו שאנו מוצאים שגם בקו\"ח שעובר באצילות יש בו דוקא הכח לחבר ב' הפכים שזהו לאכללא שמאלא בימינא וימינא בשמאלא<sup data-n=\"1730\">5</sup> כו' ולהחליף האור בכלי המנגדו כמו אור החסד בכלי הגבורה כו' לפי ששרשו מעצמות אא\"ס שלפני הקו\"ח כו') (וכמ\"ש במ\"א<sup data-n=\"1731\">6</sup> שזהו כמו ענין מקו' ארון אינו מן המדה<sup data-n=\"1732\">7</sup> ואע\"פ שעמד הארון בשטח מקום לא נתפס במדה כו' ואעפ\"כ הוא מקור כל מדה כו' והיינו משום דגם דאיהו תפיס בכולהו עלמין<sup data-n=\"1733\">8</sup> לית מאן דתפיס בי' שהוא מבחי' קדם הנ\"ל דוקא וד\"ל):\n<b>ומעתה</b> יתורץ הקושיא הנ\"ל דאף על פי שבאמת עיקר בקיעת הים היה ע\"י בחי' רוח קדים עזה הנ\"ל אבל זה לא היה רק כדי שיגבר האו\"י על האו\"ח כשיבקע הים בעבור משה ובנ\"י בתוך הים ביבשה שזהו כל עיקר ענין התו\"מ שלזה הי' הכוונ' בתחיל' ההשתלשלות ולא שיהי' עליי' דאו\"ח לקדמותו שזה נגד המכוון העיקר שנתאוה להיות לו דירה בתחתונים<sup data-n=\"1734\">9</sup> דוקא ולזה היה קי\"ס רק כמו הכנה למ\"ת כנ\"ל וד\"ל ובכל הנ\"ל יובן מ\"ש נכון כסאך מאז מעולם<sup data-n=\"1735\">10</sup> כו' פי' מאז מקדמת דנא<sup data-n=\"1736\">11</sup> כמו אז ישיר כו' והיינו מבחי' קדם דקדמונו ש\"ע<sup data-n=\"1737\">12</sup> הנ\"ל והענין הוא דבחי' כסא הכבוד העליון כתיב בו והוכן בחסד כסא<sup data-n=\"1738\">13</sup> שעיקר יסודו והכנתו מבחי' החסד עליון להיות שעיקר בנין העולם הוא מבחי' החסד כמ\"ש כי אמרתי<sup data-n=\"1739\">14</sup> עולם חסד יבנה שיהיה אור ושפע להחיות רוח שפלים<sup data-n=\"1740\">15</sup> שזהו חסד ח\"ס דלי\"ת<sup data-n=\"1741\">16</sup> כו' והיינו בחי' כסא העליון שהוכן בחסד",[["1726","1","<b>ברוח קדים. . קדמונו ש\"ע</b>: ראה מאמרי אדה\"ז על פרשיות התורה כאן ע' רפה. תקס\"ה כאן ע' רלט. הנסמן לעיל נה, ב."],["1727","2","<b>מי מדד</b>: ישעי' מ, יב."],["1728","3","<b>ה' גבורות דבצ\"ק</b>: ראה שהיחוה\"א ספ\"ד. מאמרי אדה\"א שמות ח\"א ע' קל."],["1729","4","<b>בזהר בל' משחתא</b>: ראה זהר בראשית יח, ב. ביאוה\"ז פקודי נז, ד."],["1730","5","<b>לאכללא שמאלא. . בשמאלא</b>: כ\"ה בכ\"מ — ראה זהר וארא כז, א. תו\"ח בראשית כו, א ובהערה 3."],["1731","6","<b>וכמ\"ש במ\"א</b>: ראה ד\"ה לבך יהגה אימה במאמרי אדה\"א נ\"ך ע' עד. — ובאם כאן הכוונה למאמר זה אז נאמר מאמר הנ\"ל בין השנים תקע\"ט-תק\"פ (שער האמונה נדפס בשנת תק\"פ). וראה בריש המאמר (שם ע' נה] בהערה."],["1732","7","<b>מקו' ארון אינו מן המדה</b>: יומא כא, א. ראה מאמרי אדה\"א ויקרא ח\"א ע' קפח. וש\"נ. שע\"ת ח\"א יד, ג. הנסמן בתו\"ח נח סה, ג הערה 38."],["1733","8","<b>דאיהו תפיס בכולהו עלמין</b>: נסמן לקמן קטו, ב."],["1734","9","<b>שנתאוה. . דירה בתחתונים</b>: תניא רפל\"ו. וראה הנסמן בליקוט פירושים לשם."],["1735","10","<b>נכון כסאך מאז מעולם</b>: תהלים צג, ב."],["1736","11","<b>מאז מקדמת דנא</b>: ראה גם פיה\"מ פט, סע\"ד. לעיל נ, א. וש\"נ."],["1737","12","<b>קדם דקדמונו של עולם</b>: נסמן לעיל נה, ב."],["1738","13","<b>והוכן בחסד כסא</b>: ישעי' טז, ה."],["1739","14","<b>כי אמרתי</b>: תהלים פט, ג."],["1740","15","<b>להחיות רוח שפלים</b>: ישעי' נז, טו."],["1741","16","<b>חסד ח\"ס דלי\"ת</b>: ראה גם לקמן קמב, א ובהנסמן במ\"מ לשם."]]],[2800530151,"עליון כמו כסא המלך שיושב עליה לדון ולשפוט שאע\"פ שיש בזה מדת הדין אבל עיקר ענין כסא המלוכה היינו להשגיח ולהטיב לכל בחסד ורחמים באור פני מלך חיים<sup data-n=\"1742\">17</sup> כו' רק שכלול גם ממדת הדין לענוש למי שראוי לעונש שגם בזה הוא קיום הארץ שלא יהיה איש את רעהו חיים בלעו<sup data-n=\"1743\">18</sup> כו' וא\"כ זהו חסד ולא דין וע\"כ כל יסוד ענין כסא בנוי על החסדים וכך למעלה יש עתים שישב לדין הוא ע\"פ העלאת מעשה התחתונים שמעוררים דינים וגבורות ויש עתים שישב לחסד מצד מעשה התחתונים לטוב וא\"כ כלול מחו\"ג וזהו ענין המרכבה שנושאות את הכסא כו' שלפעמים הן בבחי' החסדים דאו\"י להמשיך אור ושפע למטה ופעמים הן בבחי' העלאה דגבורות דאו\"ח כו' (ונק' רתיכין ומשריין<sup data-n=\"1744\">19</sup> רתיכין נושאים את הכסא בבחי' או\"ח ומשריין ממשיכים ומורידין אור אלקי שעל הכסא למטה כו' כמ\"ש במ\"א) וזהו נכון כסאך פי' נכון שהוכן הכסא עליון במדה נכונה בחו\"ג דאו\"י ואור חוזר כפי הצריך באופן שיהיה בבחי' התיקון והתכללות מאו\"י ואו\"ח שישכנו יחד והוא ע\"פ מאמר קו המדה כנ\"ל שנמשך מבחי' קדם דקדמונו ש\"ע כנ\"ל הטעם בענין בחי' או\"י ואו\"ח דמשה ובנ\"י כו' בבחי' רו\"ש דתו\"מ ותפלה וכה\"ג שב' הפכי' אלה יוכלו לשכון כא' ע\"פ המדה שנמדד בהם ממא' קו המדה כו' וכך בכסא העליון הוכן בחסד וגם בדין במדה נכונה דוקא באופן שישכנו יחדיו כאחד דוקא והוא בא מכח העליון הממוצע המחברם כנ\"ל וד\"ל והיינו נכון כסאך מאז דוקא מקדמת דנא שהוא בחי' קדם דהיינו כמו בחי' רוח קדים עזה הנ\"ל שבקע הים וכנ\"ל וד\"ל וזהו המשך הפסוקים ה' מלך גאות לבש<sup data-n=\"1745\">20</sup> דקודם הצמצום דקו\"ח שעלה במח' הקדומה להיות מלך כו' הרי הוצרך זה הדבר להיות בבחי' לבוש שיתלבש ברצון ומחשבה זו דבחי' מל' וכאשר בא בהתלבשות דלבוש מל' אז דוקא הוכן כסא המלוכה שיהיה באופן מדה הנכונה מבחי' החו\"ג כנ\"ל ויצא לידי גילוי אח\"כ אחר הצמצום שהוא מל' דא\"ס שבקו\"ח דאבי\"ע דכתיב מלכותך מלכות כ\"ע<sup data-n=\"1746\">21</sup> כו' וזהו נכון כסאך מאז דוקא לשעבר שכבר הי' כו' וד\"ל ומ\"ש והוכן בחסד כסא בחסד לבד גם זה אמת דעיקר הכונה הוא שיגבר האו\"י דחסדים על גבורות דאו\"ח והיינו לאכללא שמאלא בימינא שזהו כל יסוד התו\"מ כידוע אבל גם זה הוא בא ע\"פ קו המדה שיהיה באופן מדה נכונה איך וכמה והיינו כל עיקר התורה שניתנה במדה ושיעור כמ\"ש מימינו אש דת<sup data-n=\"1747\">22</sup> כו' כלול מחו\"ג וכמ\"ש כל אמרת אלוה צרופה<sup data-n=\"1748\">23</sup> כו' ונקרא חכמה ברורה שכבר הוברר בחכמה הקדומה כו' וז\"ש לבש ה' עוז<sup data-n=\"1749\">24</sup> ואין עוז אלא תורה<sup data-n=\"1750\">25</sup> וכמ\"ש ואהיה אצלו אמון<sup data-n=\"1751\">26</sup> כו' וכידוע וד\"ל:\n(מו) <b>וזהו</b> שנא' בשירת הים מכון לשבתך פעלת ה'<sup data-n=\"1752\">27</sup> כו' דמשמע שבקי\"ס זה מכון לשבתו פעל והיינו בזמן בהמ\"ק כשיביא' ויטעם בהר נחלתו ואז כבר מכון לשבתו שם פעל וזה פלא דתביאמו ותטעמו<sup data-n=\"1753\">28</sup> לשון עתיד ומכון לשבתך פעלת שכבר פעל כו' הענין יובן ע\"פ הנ\"ל בעיקר",[["1742","17","<b>באור פני מלך חיים</b>: משלי טז, טו."],["1743","18","<b>איש. . חיים בלעו</b>: אבות פ\"ג מ\"ב."],["1744","19","<b>רתיכין ומשריין</b>: זהר (ס\"ת) ויצא קמט, א. בשלח מח, ב ובביאוה\"ז לשם (לט, ד ואילך). מאמרי אדה\"א דברים ח\"ד ע' א'רח. קונטרסים ע' תקפ."],["1745","20","<b>ה' מלך גאות לבש</b>: תהלים צג, א."],["1746","21","<b>מלכותך מלכות כ\"ע</b>: תהלים קמה, יג."],["1747","22","<b>מימינו אש דת</b>: ברכה לג, ב. ראה שהיחוה\"א פ\"ה."],["1748","23","<b>כל אמרת אלוה צרופה</b>: משלי ל, ה. ראה גם תו\"ח בראשית יד, ד ובהערה 49."],["1749","24","<b>לבש ה' עוז</b>: המשך הכתוב ה' מלך."],["1750","25","<b>ואין עוז אלא תורה</b>: ראה ספרי ברכה לג, ב. מאמרי אדה\"א ויקרא ח\"א ע' שלח. בראשית ע' קלח ובהנסמן בהנ\"ל."],["1751","26","<b>ואהי' אצלו אמון</b>: משלי ח, ל."],["1752","27","<b>מכון לשבתך פעלת ה'</b>: בשלח טו, יז."],["1753","28","<b>דתביאמו ותטעמו</b>: התחלת הכתוב מכון לשבתך."]]],[2800530152,"ענין קי\"ס שאז נתחברו בחי' או\"י ואו\"ח דבחי' משה ובנ\"י בקבלת התו\"מ לתכלית המכוון שזה כבר הוכן מאז במדה נכונה דבחי' רו\"ש דאו\"י ואו\"ח זה כנ\"ל בפי' נכון כסאך מאז דוקא והוא ע\"י בחי' רוח קדים עזה שממנו נבקעו המים די\"ס כנ\"ל ע\"כ אז אמרו מכון לשבתך פעלת כבר כו' שכבר נעשה וכבר פעלת מכון לשבתך שזהו תיקון והכנת כסא מושבו כמ\"ש נכון כסאך מאז במדה יפה ונכונה כו' וד\"ל אך הנה תחילה יש להבין מ\"ש לשבתך דוקא מהו ענין ישיבה זו דוקא שנעשה מכון כו' דהנה כתיב וישב ה' מלך לעולם<sup data-n=\"1754\">1</sup> בבחי' ישיבה דוקא דהנה עד\"מ באדם התחתון כשיושב נשפל קומתו שכאשר הוא עומד זקוף הרי ראשו מוגבה למע' כשיעו' קומתו ורגליו מושפלי' ועומדי' בארץ לפי שגופו נתפש' כמו שהו' שרגליו רחוקי' מראשו בעמיד' כשעומד שכפי סדר מצב קומתו כך הוא שבסדר מצב קומתו כשירצ' אד' לילך רגליו בארץ וראשו רחוק מרגליו אבל כאש' אד' יושב הנה כופף קומתו לישב ורגליו מוגב' מן הארץ ומתקרבים אל הגוף וראשו ומפני הכפיפה שכופף א\"ע ראשו קרוב לרגליו הרבה יותר מכשהוא עומד עד שראשו וגופו כאחד קרובים לשוקיו ורגליו בישיבתו כידוע ועיקר ענין ההפרש הוא שהעומד והולך רגליו בארץ וראשו זקוף כסדר הבריאה היינו רק שרגליו משמשין לגוף רק לענין ההליכה שמוליכים לגופו וראשו וכן בעמידה יעמודו לגוף וראש שישען אדם על קיום וחוזק שברגליו וזהו בחי' חיצוניות שברגלים שנקרא נה\"י שטפל ומשמש לחג\"ת גופא וחב\"ד שבראש כו' אבל בישיבה עיקר הענין הוא שמוחי' שבראש ומדות שבלב שולטים לעניני צרכיו לעצמו והנהגת משפט על זולתו או לעסוק בלימודו וכה\"ג שאז א\"צ לרגלים לשמש לגוף בעמידה או הילוך ונכללים בגוף וראש כו' ע\"כ המה מוגבהים מן הארץ ונעשו קרובים לראש ביותר כנ\"ל והיינו בחי' פנימיות נו\"ה שנכללים בחג\"ת שבלב וחב\"ד שבראש כו' שאין זה לפי סדר מצב חיצוניות קומתו כשעומד והולך וכה\"ג וד\"ל והדוגמא מזה יובן לענין ציור קומת אדם למעלה שנקרא שיעור קומה של יוצר בראשית<sup data-n=\"1755\">2</sup> אע\"פ שאין לו גוף<sup data-n=\"1756\">3</sup> ולא דמות כו' רק לשכך האוזן<sup data-n=\"1757\">4</sup> וכו' וכמ\"ש ועל הכסא דמות<sup data-n=\"1758\">5</sup> כמראה אדם שזהו בחי' אדם דאצילות שהאורות דע\"ס מלובשין בכלים כמו חכמה מוחא<sup data-n=\"1759\">6</sup> חסד דרועא כו' כציור קומת אדם שכולל ג' המדריגות בכלל חב\"ד חג\"ת ונה\"י כו' הרי בבחי' עמידה כמו הנה ה' עומד<sup data-n=\"1760\">7</sup> כו' (אע\"פ שאין למעלה לא עמידה<sup data-n=\"1761\">8</sup> ולא ישיבה ולא כל תוארי אדם אבל בבחי' הצמצום דאור המאציל נאצל בציור אדם כמ\"ש כמראה אדם כו' וע\"כ נזכר בכתובים תמיד כל תוארי אדם עומד והולך ויושב ורואה ושומע כו') ודאי שכפי סדר ההשתלשלות דאו\"כ דאדם דאצי' ממוחי' דראש עד בחי' נו\"ה שנקרא סוף כמו הארץ הדום רגלי<sup data-n=\"1762\">9</sup> (וכלשון הגמרא רגלי השכינה<sup data-n=\"1763\">10</sup> וכה\"ג) רחוק מאד מראש לרגל אשר ע\"כ עיקר השפע לג' עולמות דבי\"ע אינו רק מבחינת נו\"ה דז\"א דאצי' וכן ממל' דאצי' שנקרא אדם תתאה כו' ובחי' מוחין שברא' הוא הגבה למעלה מעלה נבדל בערך מהיות מקור לעולמות (רק מחיצוניות המדות שבלב שמאירים בנו\"ה דזו\"נ כו') לפי שבעמידה מתפשטים בחי' הרגלים",[["1754","1","<b>וישב ה' מלך לעולם</b>: תהלים כט, י. ראה גם סה\"מ תקס\"ה ח\"ב ע' תשט."],["1755","2","<b>שיעור קומה של יוצר בראשית</b>: ראה הנסמן באוה\"ת ואתחנן כרך ו ע' ב'רלג. תו\"ח מקץ רכא, ג הערה 37."],["1756","3","<b>שאין לו גוף</b>: ע\"פ פיוט יגדל. רמב\"ם פיה\"מ סנהדרין פ\"י היסוד הג'."],["1757","4","<b>לשכך האוזן</b>: מכילתא יתרו יט, יח. תנחומא שם יג."],["1758","5","<b>ועל הכסא דמות</b>: נסמן לעיל סג, ב."],["1759","6","<b>חכמה מוחא</b>: ת\"ז בהקדמה (יז, א)."],["1760","7","<b>הנה ה' עומד</b>: ראה לקמן הערה 16. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קח. מאמרי אדה\"א קונטרסים ע' שלח. תו\"ח וירא צח, ג בהערה 18. יחזקאל ג, כג."],["1761","8","<b>שאין למעלה לא עמידה</b>: ראה חגיגה טו, א וברש\"י שם. רמב\"ם הל' יסוה\"ת פ\"א, סהי\"א. פיה\"מ סנהדרין פ\"י היסוד הג'. מו\"נ ח\"א ספי\"ב."],["1762","9","<b>הארץ הדום רגלי</b>: ישעי' סו, א [ושם: והארץ — ראה הנסמן במאמרי אדה\"א קונטרסים ע' שלח־ תו\"ח וישב רא, ג בהערה 39]."],["1763","10","<b>רגלי השכינה</b>: ברכות מג, ב. חגיגה טז, א."]]],[2800530153,"לסוף הכל (והוא בדרך כלל בבחי' א\"ק שעקב דא\"ק מסתיים בסוף עולם העשיה<sup data-n=\"1764\">11</sup> כידוע) להיותם רק בחי' משמש וטפל לחיצוניות הגוף לעמוד ולילך וכה\"ג כנ\"ל וד\"ל אבל בבחי' ישיבה למעלה כמו וישב ה' מלך כו' וכה\"ג שעיקר הענין הוא שמוחי' שבראש ומדות שבלב האדם העליון מאירים בבחי' הפנימית שבו ואז בחי' נו\"ה מוגבהים ונכללים במוחי' ומדות עליונות כו' וע\"ד דוגמא כמו שאמרו רז\"ל ג\"ש ראשונות<sup data-n=\"1765\">12</sup> יושב הקב\"ה ועוסק בתור' כו' שישיבה זו עד\"מ בישיבת אדם התחתון לעסק לימודו בעיון שכלו שמאירים במדות שבלב לחו\"ג בדין ופסק הלכה לחיוב או לזכות שאע\"פ שכופף קומתו אבל הוא בחינת ירידת והמשכת המוחין דחב\"ד כו' ומכ\"ש בג\"ש שניות שיושב ודן במדות שבלב ע\"פ משפט התורה כמו המלך שיושב על הכסא לשפוט העם אע\"פ שזהו ירידה יותר וז\"ש וישב ה' מלך כו' אבל הוא בחי' הפנימית שבו ואז בחי' נו\"ה דרגלים נכללים ועולין בפנימית המדות והמוחין וזהו בחי' עליי' לנה\"י בחג\"ת כו' וכמו בשבת דכתיב אם תשיב משבת רגליך<sup data-n=\"1766\">13</sup> כו' שבחי' נה\"י עולין בחב\"ד כו' לפי ששובת ממלאכתו שנשפע מחיצוניות דנו\"ה כמשל אדם שיושב ונח ולא יצא חוץ ממקומו כו' וד\"ל וכך בזמן בהמ\"ק שהיה גלוי אלקות בהיכל ק\"ק היה בחי' ישיבה למעלה להאיר בכנ\"י מבחי' פנימיות המוחין ומדות עליונות באור פני מלך חיים כו' כמלך שיושב בהיכלו כו' (ומשחרב בהמ\"ק אין להקב\"ה בעולמו אלא רק ד\"א של הלכה<sup data-n=\"1767\">14</sup> במקום היכל ק\"ק דאורייתא היכלא עילאה דקוב\"ה<sup data-n=\"1768\">15</sup> כו') (אבל בזמן הגלות הרי הוא ית' בהסתר פנים מכנ\"י כו' ואמנם כאשר צריך להושיע לישראל מצרתם בין הגוים שהן הע' שרים כתיב הנה ה' עומד לריב עמים<sup data-n=\"1769\">16</sup> כו' וכמו שאנו אומרים בנס דחנוכה עמדת להם בעת צרתם<sup data-n=\"1770\">17</sup> עמדת דוקא והענין הוא דגם שעמידה ברגל הוא בבחינת חיצוניות כנזכר למעלה אבל כשעומד אדם לריב זהו בא מכל כחו הפנימי שעומד בכל כחו להשפיל למנגד לו העומד לנגדו וכמו במלחמה שעיקר עוז וכח וגבורה לנצח לנגדו אינו אלא בכחו בעמידה חזקה על רגליו כגבור שיעמוד בכל כחו עוז להציל עצמו וסייעתו ולהבריח למנגדו הקם עליו כו' שנמצא יש כח ברגל יותר מבראש שהרי כל גבורתו אינו אלא בכח עמידתו דוקא (שהרי תחילת נפילה ניסה<sup data-n=\"1771\">18</sup> כשלא יוכל לעמוד לנגד ויברח כו') וכמו\"כ לענין מלחמה וניצוח בדברים כמו בדברי חכמה או בטו\"ת<sup data-n=\"1772\">19</sup> ובדברים שבלב בדברי תוכחה ורוגז אינו רק בכח העמידה שכאשר יתגבר בלבו ודעתו על המנגדו יקום על רגליו דוקא ובזה ניכר דוקא כח ועוז גבורתו בחכמה ומדות כו' כמו בגבורת הלב במלחמה ממש וזהו שארז\"ל בים נדמה להם כבחור<sup data-n=\"1773\">20</sup> עושה מלחמה כמ\"ש ה' איש מלחמה<sup data-n=\"1774\">21</sup> שאע\"פ שטענה מדה\"ד מה נשתנו אלו מאלו<sup data-n=\"1775\">22</sup> הללו הן עובדי ע\"ז<sup data-n=\"1776\">23</sup> כו' ועכ\"ז נלחם במדות שבלב להטות לחסד לישראל ולדין למצרים שאלו יטבעו בים ואלו יצאו לשלום וז\"ש ה' איש מלחמה ומלחמה זו היתה בעמידה כמ\"ש הנה ה' עומד לריב עמים וכמ\"כ בכל צרת ישראל מרוב המקטרגים ברוחניות למעלה ובגשמיות למטה ה' ילחם להם כגבור עושה מלחמה",[["1764","11","<b>שעקב א\"ק. . העשיה</b>: ראה אגה\"ק ס\"כ (קלא, ב). הנסמן במאמרי אדה\"א ויקרא ח\"א ע' טו."],["1765","12","<b>ג\"ש ראשונות</b>: ראה ע\"ז ג, ב."],["1766","13","<b>אם תשיב משבת רגליך</b>: ישעי' נח, יג."],["1767","14","<b>אין. . ד\"א של הלכה</b>: ראה ברכות ח, א. מאמרי אדה\"א ויקרא ח\"ב ע' תמד, וש\"נ. הנחות תקע\"ז ע' ש. וש\"נ."],["1768","15","<b>דאורייתא היכלא עילאה דקוב\"ה</b>: ראה זהר ויקהל ר, א."],["1769","16","<b>הנה ה' עומד לריב עמים</b>: וכ\"ה גם בסמוך. מאמרי אדה\"א קונטרסים ע' שלח. וש\"נ. ראה ישעי' ג, יג. לעיל הערה 7."],["1770","17","<b>עמדת להם בעת צרתם</b>: נוסח ועל הנסים (לחנוכה). ראה גם מאמרי אדה\"א קונטרסים ע' שלח."],["1771","18","<b>תחילת נפילה ניסה</b>: סוטה מד, ב. ספרי (ורש\"י) שופטים כ, ט."],["1772","19","<b>בטו\"ת</b>: בטענות ותביעות."],["1773","20","<b>בים נדמה להם כבחור</b>: ראה מכילתא בשלח טו, ג. יתרו כ, ב (ורש\"י שם). מאמרי אדה\"א בראשית ע' רפב ואילך. שמות ח\"א ע' קלא. ויקרא ח\"א ע' רמח. וש\"נ."],["1774","21","<b>ה' איש מלחמה</b>: בשלח טו, ג."],["1775","22","<b>מה נשתנו אלו מאלו</b>: לשון הגמ' שבת נה, א. ראה זהר תרומה קע, ב. יל\"ר בשלח יד, כח."],["1776","23","<b>הללו הן עובדי ע\"ז</b>: ראה זהר ויל\"ר שם. מאמרי אדה\"א ויקרא ח\"ב ע' תטז בהערה."]]],[2800530154,"ממש כמ\"ש ותפארת בחורים כחם<sup data-n=\"1777\">1</sup> כו' למצוא זכות לישראל כמו איש גבור במדות שבלב וז\"ש ה' יחתו מריביו<sup data-n=\"1778\">2</sup> שהן המקטרגים כו' וזהו שאנו אומרים עמדת להם בעת צרתם דוקא רבת את ריבם<sup data-n=\"1779\">3</sup> דנת את דינם כו' לפי שבצרתם לו צר<sup data-n=\"1780\">4</sup> ממש כי בנים הם<sup data-n=\"1781\">5</sup> וכרחם אב על בנים<sup data-n=\"1782\">6</sup> כו' ע\"כ יתגברו ביותר רחמי האב על הבן בעת צרתו דוקא להושיע ולהציל אותו מיד הקמים עליו להורגו שאז יעמוד בכל כחו ממש להצילו בכל פנימיות כחו העצמי דוקא שכל זה ניכר בכח העמידה שברגל דוקא ובזה יש יתרון מעלה לקי\"ס להיותו נלחם בעמידה יותר ממלחמה שבמ\"ת שנדמה להם כזקן<sup data-n=\"1783\">7</sup> במלחמתה של תורה וד\"ל) וזהו מכון לשבתך פעלת ה' שזה נאמר בקי\"ס דוקא שנעש' מכון לשבתו בבחי' ישיבה כי בקי\"ס היה המלחמה בבחי' עמידה בכל כחו עוז להושיע לישראל וכמ\"ש ויושע ה'<sup data-n=\"1784\">8</sup> ביום ההוא כו' ובעמידה זו עשה מכון לשבתו על הכסא בעוז והדר מלכותו להיות מלך על עם בחירו כו' וענין הכנה זו כבר נעשה מימי קדם בבחי' הממוצע דחו\"ג דאו\"י ואו\"ח כנ\"ל ויצא לגלוי בעת קי\"ס ע\"י בחי' רוח קדים הנ\"ל שזהו מבחי' קדמונו ש\"ע שבקע הים דהיינו שיגבר או\"י על או\"\"ח במדה ושיעור דוקא והוא עיקר ההכנה לבחי' ישיבה לדון ולשפוט ע\"פ התורה כנ\"ל וזהו פעלת כבר מקדמת דנא וברוח הקדים שבקע הים יצא הפועל הזה לגלוי וזהו תביאמו לשון עתיד אבל מכון לשבתך פעלת ה' לשעבר והוא בבחי' רוח קדים הנ\"ל וד\"ל:\n(מז) <b>ובכל</b> זה יובן המדרש רבה<sup data-n=\"1785\">9</sup> ע\"פ נכון כסאך מאז כו' משל למלך ואגוסטוס (אגוסטוס קיסר<sup data-n=\"1786\">10</sup> מלך על המלכים ומלך הוא על העבדים כידוע) כשאגוסטוס יושב מלך עומד וכשאין אגוסטוס יושב מלך יושב דהיינו משנעשה אגוסטוס שהוא מלך על מלכים אז המלכים עומדים לפניו כעבדים אבל כשאין אגוסטוס המלך יושב על הכסא כו' וביאור הדברים ידוע שיש שני מיני מלוכה א' מלך על העבדים דאין מלך בלא עם והב' מלך על המלכים וכאשר המלך שעל כל המלכים שנקרא אגוסטוס בא לעיר אז המלך עומד לפניו ואגוסטוס יושב כו' והנמשל מזה יובן למעלה דיש ב' מדריגות בבחי' המל' למעלה וכמ\"ש בזהר דאית מלכא עילאה<sup data-n=\"1787\">11</sup> ומלכא תתאה ומלכא תתאה מלך זוטא אקרי שהוא מל' דאצי' בבי\"ע על עולמות שהן בע\"ג כמלך על עבדים כמ\"ש מלכותך מלכות כל עולמים<sup data-n=\"1788\">12</sup> וכתיב ומלכותו בכל משלה<sup data-n=\"1789\">13</sup> כו' ומלכא עילאה היינו כמ\"ש קרית מלך רב<sup data-n=\"1790\">14</sup> שהוא מל' דא\"ס שנעשה כתר לא\"ק<sup data-n=\"1791\">15</sup> שנקרא מלכותך ממש כידוע וזהו דרך כלל ובאמת יש ב' מדריגות אלה דמלך רב ומלך זוטא בין במל' דאצילות בין במל' דא\"ס וביאור הדברים ידוע בענין המלך המרומם לבדו<sup data-n=\"1792\">16</sup> כו' מתנשא מימות עולם שהן ב' מיני מלוכה הנ\"ל הא' מה שהוא מתנשא רק על ימ\"ע שזהו כמלך שמתנשא על העבדים שאין ההתנשאות זו רק לפי ערך העולמות לבד אבל הב' הוא מלך מרומם לבדו שאין עוד מלבדו שיתנשא עליו וא\"כ אין ההתנשאות הזאת שנקרא מלך מרומם רק בעצמותו שהוא",[["1777","1","<b>ותפארת בחורים כחם</b>: משלי כ, כט [ושם: תפארת]."],["1778","2","<b>ה' יחתו מריביו</b>: שמואל-א ב, י."],["1779","3","<b>רבת את ריבם</b>: נוסח ועל הנסים (לחנוכה)."],["1780","4","<b>שבצרתם לו צר</b>: ישעי' סג, ט. ראה גם לעיל ב, א ואילך."],["1781","5","<b>בנים הם</b>: שמות ד, כב. פ' ראה יד, א."],["1782","6","<b>וכרחם אב על בנים</b>: תהלים קג, יג. ראה גם מאמרי אדה\"א דברים ח\"ב ס\"ע תלד. וש\"נ."],["1783","7","<b>שבמ\"ת נדמה להם כזקן</b>: ראה בהנסמן לעיל עה, ב הערה בים."],["1784","8","<b>ויושע ה'</b>: בשלח יד, ל."],["1785","9","<b>המדרש רבה</b>: ראה שמו\"ר רפכ\"ג. ראה גם לעיל לג, ב ובהנסמן במ\"מ לשם."],["1786","10","<b>קיסר</b>: ראה תוד\"ה כל ע\"ז י, ב."],["1787","11","<b>דאיתא מלכא עילאה</b>: ראה זהר ויחי רלט, א. (תוספת) ויקרא ש, א."],["1788","12","<b>מלכותך מלכות כל עולמים</b>: תהלים קמה, יג."],["1789","13","<b>ומלכותו בכל משלה</b>: שם קג, יט."],["1790","14","<b>קרית מלך רב</b>: תהלים מח, ג."],["1791","15","<b>מל' דא\"ס. . לא\"ק</b>: נסמן לקמן קיד, ב."],["1792","16","<b>המלך המרומם לבדו</b>: ברכת יוצר. ראה גם מאמרי אדה\"א הנחות תקע\"ז ע' קעה. עט\"ר שער ר\"ה ה, סע\"ב ואילך."]]],[2800530155,"רק מצד בחי' רוממות עצמותו ממש ע\"כ נקרא מלך מרומם לבדו ובחי' מלוכה זו שבאה מצד עצמו מאד נבדל ומרומם בערך ממה שמתנשא על ימות עולם ואין ערוך ביניהם כלל להיות שכמו שאין ערך לבע\"ג לבלתי בעל גבול בעצם כך אין ערך גם בין ההתנשאות על בעלי גבול להתנשאות שמצד עצמותו שהוא בלתי גבול בבחי' א\"ס ממש עד שהתנשאות שעל ימ\"ע הוא כערך העבד לגבי המלך שבטל וכלא חשיב ממש או כמו השר שמושל על מדינה ועיר א' בבואו לפני מלך על כל הארץ שיש בה אלף עיירות שנתבטל מציאותו להיות שממשלתו מאד מוגבלת עד חלק אלף דכלא חשיב ומה גם שהממשלה המוגבלת על עיר זו מן המלך ניתן לו וכך הוא גם בענין מלך על המלכים שגם שכל מלך מושל ומרומ' בארצו כמלך גמור מ\"מ בבואו לפני המלך על כל הארצות יעמוד לפניו כעבד ממש לפי שהתנשאות שלו שעל ארצו כעבדות ממש יחשב לגבי ממשלת הרוממות דאגוסטוס לפי שממנו ניתן לו הממשל' המוגבלת הזאת וזהו כמו שניתן לעבד ממשלה באיז' מקום מן המלך כו' וא\"כ ה\"ז בחי' התנשאו' על התנשאו' המלכי' כמו התנשאו' המלך על העבדים ממש וזהו דמיון להבין ענין מלך מרומ' לבדו שנבדל ומרומ' ערך התנשאות זו עד שזהו כמו התנשאות האגוסטוס על התנשאו' המלכים עד שיחשבו לו כעבדים שהוא כהתנשאות המלך על עבדים ויותר מזה לפי שיותר אין ערך בין המלכים לאגוסטוס משאין ערך לעבדים לגבי המלך מאחר שבעצם ההתנשאות מובדל ערך התנשאות האגוסטוס עליה' מהתנשאו' המלכים על עבדים כנ\"ל והיינו שנראה בעליל שגדול יותר ביטול מציאת המלכים לגבי האגוסטוס מביטול העבדי' לגבי המלך מטע' זה עד שהתנשאותם יותר מעבדו' יחשב להיות התנשאות האגוסטוס נשגב ומרומם הרבה עליהם וד\"ל ולמעל' יובן מזה בב' מיני מלוכה הנ\"ל בבחי' מל' דא\"ס שמה שהוא מתנש' על ימ\"ע דאצי' ונק' סובב כ\"ע הכללי אין לזה ערך לגבי התנשאות שמצד עצמות הרוממות שלגדולתו אין חקר כלל כנ\"ל יותר משאין ערך ימ\"ע דאצילות לגבי המאציל כו' מטעם הנ\"ל במשל המלך ואגוסטוס ואמנם הנה באמת גם זה שנק' מלך על כל המלכים כמ\"ש מלכותך כו' וכמו שאמ' מלך מלכי המלכים<sup data-n=\"1793\">17</sup> כו' וכמ\"ש לך ה' הממלכה<sup data-n=\"1794\">18</sup> כו' וכה\"ג שזהו בחי' הב' במל' דא\"ס שנק' מלך מרומם לבדו ממש עכ\"ז הרי נק' בשם מלך עכ\"פ אלא שהוא מלך יחיד לבדו והרי מולך על כל המלכים כו' שיש על מי להתנשאות עכ\"פ והוא מה שעלה במח' הקדומה אנא אמלוך<sup data-n=\"1795\">19</sup> הגם שהי' זה כשהוא לבדו רק על מה שימלוך לעולם הוא שעלה במח' כו' זהו בחי' מלך מרומם כו' גם זה בחי' ירידה גדולה מעצם עצמותו כמו שהוא מתנשא מצד עצמו ממש שלא עלה במח' ורצון עדיין אנא אמלוך כו' והיינו התנשאות עצומ\"ה א\"ס ממש שלמע' מבחי' כתר למל' דא\"ס כו' וז\"ש ה' מלך גאו' לבש פי' דגם מה שנק' מלך גאות להיו' מלך על המלכי' דהיינו גאה על גאו' והתנשאו' דמל' כ\"ע כו' גם זה אינו רק בחי' לבוש וצמצום לגבי התנשאות מהו\"ע ממש וד\"ל ובכל זה יובן המדרש הנ\"ל ע\"פ נכון כסאך מאז אגוסטוס יושב ומלך עומד כו' פי' עד שלא נתגלה מבחי' מל' דא\"ס כמו שהוא לבדו מלך מרומם דהיינו שנמשך",[["1793","17","<b>מלך מלכי המלכים</b>: ברכות כח, ב. ראה גם שע\"ת קמה, ד ובהנסמן במ\"מ לשם."],["1794","18","<b>לך ה' הממלכה</b>: דהי\"א כט, יא."],["1795","19","<b>אנא אמלוך</b>: נסמן לקמן קטו, א."]]],[2800530156,"וירד בחי' התנשאות שמצד עצמות ממש להיות מתנשא על התנשאות דימ\"ע הנ\"ל אז הי' מלך יושב והוא בחי' מלך זוטא היינו מל' דא\"ס שנעשה סובב ומקיף לאצילות ובי\"ע וכן מל' דאצילות שנעשה כתר לבריאה שנק' מלך ממש יושב על כסא לשפוט עמו וכמ\"ש וישב ה' מלך לעולם כו' וכה\"ג להיותו מלך על עם כמלך על עבדים כנ\"ל אבל כאשר נתגלה מבחי' קדם הנ\"ל שהוא מחשב' הקדומה דמל' דא\"ס עצמו שנק' אגוסטוס שרש ומקור לכל בחי' מל' דאבי\"ע כנ\"ל (שזהו פי' אדון עולם אשר מלך בטרם כל כו' ומלוכ' הב' דמלך זוטא היינו מ\"ש לעת נעשה<sup data-n=\"1796\">1</sup> בחפצו כל במל' דא\"ס בקו\"ח כו' אזי מלך שמו נקרא להיות מתנשא מימ\"ע כו' וזהו ג\"כ ההפרש בין יחיד<sup data-n=\"1797\">2</sup> חה\"ע מלך<sup data-n=\"1798\">3</sup> מלך זוטא למלך יחיד חה\"ע וד\"ל) אז מלך עומד שהוא מל' דא\"ס שמתנשא מימ\"ע עומד בבחי' ביטול כמ\"ש דאפי' אור צח<sup data-n=\"1799\">4</sup> כו' אוכם הוא לגבי עה\"ע עצמו כו' וכמו ועמדו רגליו ביום ההוא<sup data-n=\"1800\">5</sup> כו' בבחי' עמידה לפי שאגוסטוס יושב בבחי' מלך וד\"ל וזהו מכון לשבתך פעלת היינו לשבתך ממש שהוא כענין אגוסטוס יושב שהוא בהתנשאות שמצד עצמו שיושב להיות מלך על כל בחי' מל' דאבי\"ע זהו מוכן ועומד מכבר ומקדמ' דנא מבחי' קדם הנ\"ל וזהו נכון כסאך מאז כסאך ממש נכון מאז דוקא מקדמונו ש\"ע הנ\"ל והוא מ\"ש ע\"פ זה נכון כסאך מאז דוקא אגוסטוס יושב ומלך עומד וד\"ל (וז\"ש מי הוא זה<sup data-n=\"1801\">6</sup> מלך הכבוד עד מי הוא זה<sup data-n=\"1802\">7</sup> מלך כו' ה' צבאו' כו' סלה סלה נצחית<sup data-n=\"1803\">8</sup> מל' דא\"ס עצמו וד\"ל) ובכל זה יובן מ\"ש בשיר' הים דוק' אשיר' לה'<sup data-n=\"1804\">9</sup> כי גאה גאה כו' ותרגומו גיאה כו' שהוא כענין מלך על המלכים הנ\"ל שנק' אגוסטוס יושב שהתנשאות זאת מובדל ומרומם לבדו ורק אפס קצהו נמשך להיות מלך על כל מלכים כו' (וע\"כ טבעו להיות משפיל גאים דוקא ומגביה שפלים<sup data-n=\"1805\">10</sup> כטבע הרם ומוגבה בעצם כמ\"ש למעלה וזה היה סיבת מפלת כתר דקליפת מצרי' כו') ולמעל' היינו בחי' גאה בחולם ע\"ג אתוון שנבדל ומרומם וגאה הב' היינו כמ\"ש ה' מלך גאות לבש להיות מתנשא על ימ\"ע (דלא כדלעיל שגם מל' על כל המלכים נק' לבוש גאות) והוא ענין הבקיע' שבקע הים ברוח קדים עזה שנמשך מבחי' גיאות והתנשאו' העצמות דבחי' קדם הנ\"ל להיות התגברות בחי' או\"י על או\"ח ולכך שייך זה לשירת הים דוקא (שאז נתגלה מעצמות ההתנשאו' להיות בכח לגבור האו\"י על האו\"ח וזהו בכנ\"י ע\"י תו\"מ כנ\"ל לפי ששרש נש\"י עלו ג\"כ במח' הקדומה<sup data-n=\"1806\">11</sup> וע\"כ נק' כל ישראל בני מלכים<sup data-n=\"1807\">12</sup> והוא ית' מלך על בני מלכים האלה שבהם יתפאר ויתנשא כמלך על המלכים ממש כמ\"ש ישראל אשר בך דוקא אתפאר<sup data-n=\"1808\">13</sup> כו' והיינו ע\"י קבלת עמ\"ש בתו\"מ דוקא שבני ישראל שנק' בני מלכים מקבלים עליהם שזהו כמלכים שנעשים עבדים כמ\"ש כי לי בנ\"י עבדים<sup data-n=\"1809\">14</sup> כו' ונק' ממלכת כהנים<sup data-n=\"1810\">15</sup> כו'<sup data-n=\"1811\">16</sup> וזהו ענין גאה הב' שהוא בקמץ בחי' כתר מל' הנ\"ל שהוא בחי' התגברות דאו\"י על או\"ח דישראל באמצעו' משה שושבינא דמלכ'<sup data-n=\"1812\">17</sup> שזהו מ\"ש אז ישיר משה ובנ\"י כנ\"ל כי גאה גאה כמ\"ש בזהר ישראל קדישא<sup data-n=\"1813\">18</sup> ואורייתא קדישא אבל אין קדוש כה'<sup data-n=\"1814\">19</sup> כו' (וע\"כ סוס ורוכבו דקליפה רמה בים דוקא משום דגיא' על גיוותנא ממש כו' מטעם הנ\"ל וד\"ל:",[["1796","1","<b>אדון עולם. . לעת נעשה</b>: נוסח תפלת השחר. ראה גם לעיל נו, ב."],["1797","2","<b>ההפרש בין יחיד. . למלך יחיד</b>: ראה גם לעיל שם ובהנסמן לשם."],["1798","3","<b>מלך</b>: ניתוסף ע\"פ דפו\"ר."],["1799","4","<b>דאפי' אור צח</b>: ראה ת\"ז ת\"ע (קלה, ב). מאמרי אדה\"א דברים ח\"ד ע' א'תה. וש\"נ."],["1800","5","<b>ועמדו רגליו ביום ההוא</b>: זכרי' יד, ד."],["1801","6","<b>מי הוא זה</b>: תהלים כד, ח [בהוספת תיבת ”הוא\"]."],["1802","7","<b>מי הוא זה</b>: שם שם, י."],["1803","8","<b>סלה נצחית</b>: ראה עירובין נד, א."],["1804","9","<b>אשיר' לה'</b>: בשלח טו, א."],["1805","10","<b>משפיל גאים. . ומגביה שפלים</b>: ע\"פ נוסח התפלה (עזרת אבותינו)."],["1806","11","<b>נש\"י עלו ג\"כ במח' הקדומה</b>: נסמן לעיל לז, ב."],["1807","12","<b>כל ישראל בני מלכים</b>: שבת סז, א. ראה גם שע\"ת ח\"א מ, ב ובהנסמן במ\"מ לשם."],["1808","13","<b>ישראל אשר בך. . אתפאר</b>: ישעי' מט, ג."],["1809","14","<b>כי לי בנ\"י עבדים</b>: בהר כה, נה."],["1810","15","<b>ממלכת כהנים</b>: יתרו יט, ו."],["1811","16","<b>כו'</b>: אוצ\"ל: כו')."],["1812","17","<b>משה שושבינא דמלכ'</b>: נסמן לעיל עא, א."],["1813","18","<b>ישראל קדישא</b>: ראה זהר תזריע מד, א. מאמרי אדה\"א ויקרא ח\"א ע' שסד. וש\"נ. תו\"ח בראשית לג, א ובהערה 2."],["1814","19","<b>אין קדוש כה'</b>: שמואל-א ב, ב."]]],[2800530157,"מח) <b>ולהבין</b> בתוס' ביאור שרש ענין קי\"ס הנ\"ל שזהו שרש ענין או\"י ואו\"ח דאו\"י בוקע על או\"ח כו' הנה יש להקדים ענין המבואר במ\"א בבחי' רצוא ושוב שזהו בחי' או\"י ואו\"ח<sup data-n=\"1815\">20</sup> כידוע דהנה שרש הרו\"ש הוא בחו\"ב<sup data-n=\"1816\">21</sup> דהיינו בחי' רצוא בבינה ובחי' שוב בחכמה וביאור הדברים ידוע דחו\"ב היינו בחי' אין ויש<sup data-n=\"1817\">22</sup> והוא ראי' ושמיעה<sup data-n=\"1818\">23</sup> דחכמה מאין כו' בבחי' ראי' ובינה בחי' יש הוא בשמיעה ואינו דומה שמיע' לראי'<sup data-n=\"1819\">24</sup> דשמיעה מרחוק וראי' מקרוב דוקא וזהו שרש ב' מיני התפעלות דרו\"ש בחי' רצוא נולד משמיעה דבינה ובחי' השוב נולד מראיה דחכמה כו' וזהו עיקר ההפרש בין ק\"ש לשמ\"ע דשמע ישראל היינו בשמיעה דבינה ונולד אהבה בבחי' רצוא רץ לבך<sup data-n=\"1820\">25</sup> בתשוקה וזהו בכל נפשך<sup data-n=\"1821\">26</sup> בחי' או\"ח מלמטה למעלה ובשמ\"ע הוא בחשאי כמו בחי' קול דממה דקה<sup data-n=\"1822\">27</sup> דתמן קאתי מלכא<sup data-n=\"1823\">28</sup> שזהו בחי' ראיה מקרוב דוקא והוא בחי' או\"י שנמשך מלמעלה למטה היפך האו\"ח כו' וד\"ל ויובן זה בהקדים תחילה ענין ב' מיני התפעלות דרו\"ש שנמשך כל א' משרשו דוקא בהיות ידוע שעיקר סיבת ההתפעלות אהבה ברשפי אש שהוא התשוקה בהתלהבות העולה מלמטה למעלה לצאת מחומר הכלי ליכלל ולידבק למעלה מעלה כו' אין זה נולד ובא רק מצד בחי' בינה שהוא בחי' ההתבוננות בהשגות אלקות איך הוא מהווה מאין ליש וכה\"ג שכל מה שיתבונן בעומק המושג יותר ודאי יולד בלבו התפעלות ברשפי אש התלהבות יותר כמו בפסד\"ז שמעמיק בהשגות גדולת ה' ונפלאותיו הרבי' ורחמיו וחסדיו הגדולים כל שיעמיק בזה יותר יותר יתלהב לבו לדבקה בו ית' בתשוקה גדולה יותר ולזה הטעם נק' בחי' בינה אם הבנים<sup data-n=\"1824\">29</sup> שמולדת אוי\"ר שנק' בן ובת<sup data-n=\"1825\">30</sup> כידוע. והנה ידוע דבינה מינה דינין מתערין<sup data-n=\"1826\">31</sup> כו' וזה פלא לכאורה שהרי א' אם הבנים שמחה<sup data-n=\"1827\">32</sup> והוא בחי' בינה כמ\"ש אם לבינה תקרא<sup data-n=\"1828\">33</sup> ויש בה בחי' השמחה והעונג דוקא וכנראה בחוש שכאשר אדם מתפעל במוח השגתו באלקו'<sup data-n=\"1829\">34</sup> יגיל וישמח בזה מאו' ואין התבוננות בלא שמח' ועונג להתענג על ה' ברוב חדו' ושמחה אלקי' לפי ערך מה שמשיג וקולט אור האלקי כל חד לפום שיעורא דילי'<sup data-n=\"1830\">35</sup> וראי' מן המלאכים שמצד העונג ושמח' שבהשגת אלקות המצומצם בהם אומרים שירה בשמחה ורינה כמו ברן יחד כו' ויריעו<sup data-n=\"1831\">36</sup> כו' וכמו שיר הלוים בבהמ\"ק<sup data-n=\"1832\">37</sup> בשמחה ע\"י ההשגה אלקי' לפי ערך מעלת ההשג' כך תגדל ההתפעלו' בשמחה וענג אלקי (דעיקר התגלו' ע\"י בבינה<sup data-n=\"1833\">38</sup> ונק' ענג שבשכל המושג שבא במורגש וכל שישיג יותר בכי טוב כנשמות נהנין מזיו<sup data-n=\"1834\">39</sup> כו' ע\"י בחי' בינה כו' יותר ירגיש העונג כו' (בל\"א דער קוועל אין שכל) וכמו\"כ מוליד בהתפעלות הלב שמחה וענג והוא השיר והניגון שנעשה בלב רק על פי אופן הענג שבשכל דוקא כשיר הלוים כו' והיינו בינה לבא שהלב מבין<sup data-n=\"1835\">40</sup> ומתפעל גם כן בענג ושמחה כו') וא\"כ איך אמר דבינה דינין מתערין מינה שהדינין הוא הרוגז והכעס שהוא היפך גמור מן השמחה וענג כו' אך הענין הוא דדינין הללו מתערין בסופה לבד (כמו היין שהוא בבינה<sup data-n=\"1836\">41</sup> שתחלתו רך וסופו קשה שהיין<sup data-n=\"1837\">42</sup>",[["1815","20","<b>רצוא ושוב. . או\"י ואו\"ח</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה כאן ע' רפז. סידור שער התפילין יז, ב. אמ\"ב שם קב, ד."],["1816","21","<b>הרו\"ש הוא בחו\"ב</b>: ראה מאמרי אדה\"ז כאן. ביאוה\"ז תזריע עב, א ואילך. סה\"מ תקס\"ה ח\"א ע' תכד."],["1817","22","<b>דחו\"ב. . אין ויש</b>: ראה לקמן קכז, סע\"א ובהנסמן במ\"מ לשם."],["1818","23","<b>דחו\"ב. . ראי' ושמיעה</b>: ראה סידור ערב שבת קסה, א. מאמרי אדה\"א הנחות תקע\"ז ע' כז. וש\"נ. לקמן צב, ב."],["1819","24","<b>ואינו דומה שמיע' לראי'</b>: נסמן לעיל ט, ב."],["1820","25","<b>רץ לבך</b>: ס\"י פ\"א מ\"ח. ת\"ז בהקדמה (ז, א)."],["1821","26","<b>בכל נפשך</b>: ואתחנן ו, ה."],["1822","27","<b>קול דממה דקה</b>: מלכים-א יט, יב."],["1823","28","<b>דתמן קאתי מלכא</b>: ראה זהר (רע\"מ) פינחס רכג, ב. ת\"ז בהקדמה (ג, ב)."],["1824","29","<b>בינה אם הבנים</b>: נסמן לקמן קי, ב."],["1825","30","<b>אוי\"ר שנק' בן ובת</b>: ראה גם לקמן שם ובהנסמן במ\"מ לשם."],["1826","31","<b>דבינה מינה דינין מתערין</b>: נסמן לקמן קכד, ב."],["1827","32","<b>אם הבנים שמחה</b>: תהלים קיג, ט."],["1828","33","<b>אם לבינה תקרא</b>: משלי ב, ג. ראה אוה\"ת משלי (כרך א) ע' תקמז."],["1829","34","<b>באלקו'</b>: ניתוסף ע\"פ דפו\"ר."],["1830","35","<b>כל חד לפום שיעורא דילי'</b>: נסמן לעיל כב, ב."],["1831","36","<b>ברן. . ויריעו</b>: איוב לח, ז."],["1832","37","<b>שיר הלוים בבהמ\"ק</b>: סוף תמיד. ר\"ה ל, ב ואילך."],["1833","38","<b>התגלו' ע\"י בבינה</b>: נסמן לקמן קלז, א."],["1834","39","<b>כנשמות נהנין מזיו</b>: ראה ברכות יז, א."],["1835","40","<b>בינה לבא שהלב מבין</b>: ת\"ז בהקדמה (יז, א). ברכות סא, א."],["1836","41","<b>היין שהוא בבינה</b>: ראה זהר נשא קכז, א. מאמרי אדה\"א ויקרא ח\"א ע' לג. וש\"נ."],["1837","42","<b>שהיין מטיב. . וכעס</b>: ראה ביאוה\"ז סג, ג."]]],[2800530158,"מטיב הלב בתחילה ומשמחו וסופו עושה רוגז וכעס כמ\"ש במ\"א) וכמו שאנו רואים בחוש במי שמתפעל בהתלהבות רשפי אש בתפלה שמחמת זה דוקא יבא לכלל כעס על המנגדו גם בעניני גופו כי הנה באמצעות רשפי אש הלהב בתפלה גורם שיכעוס על המנגד לו בדבר שבקדושה כמו על רשע עובר עבירה וכה\"ג או שיכעוס על מי שמונעו מעבודתו או לכעוס על יצה\"ר שבקרבו כענין ירגיז אדם<sup data-n=\"1838\">1</sup> כו' וכל זה רק מצד בחי' גבורות דקדושה שלא יוכל לסבול המנגד שהוא היפך הקדושה האלקי' ואח\"כ מסתעף מזה בחי' גבורות קשות שהוא הכעס גם בדבר המנגד לעניני גופו והוא מדה\"ד בגשמיות שיכעוס בקל על כל עובר רצונו וכה\"ג וזהו בחי' דינין גמורים ששרשם בגבורות דקדושה כענין רישא דעשו על חרבך תחיה<sup data-n=\"1839\">3</sup> בכעס ורציחה בעטפוהי דיצחק<sup data-n=\"1840\">2</sup> בחי' גבורות דקדושה שנמשכים מצד רשפי אש הלהב בהתפעלות השגה דבינה דוקא וז\"ש דבינה מינה דינין גמורים מתערים בחי' גבורות קשות שיש מזה שרש יניקה לחיצונים לקטרוגים רעים כו' אבל בפנימית בינה אדרבה נקרא אם הבנים שמחה בחדוה ועונג כנ\"ל ואין שם שרש לדינין כלל וראיה ממועדים לשמחה שהמועדים הן בבינה כידוע בענין מקרא קדש<sup data-n=\"1841\">4</sup> כו' וע\"כ מצוה לשמוח ביו\"ט וכמ\"ש ושמחת בחגיך<sup data-n=\"1842\">5</sup> אך מסתעף מזה גבורות ודינין קשין והוא מ\"ש פרש חגיכם<sup data-n=\"1843\">6</sup> כו' כמ\"ש בזהר וע\"כ בכל יו\"ט אמר איוב אולי חטאו בני<sup data-n=\"1844\">7</sup> כו' כידוע וד\"ל אך הנה כל זה בבחי' בינה דוקא שהוא בבחי' שמיעה מרחוק אבל אינו דומה שמיעה דבינה לראיה דחכמה מקרוב שאין משם אחיזה ויניקה לחיצונים כלל גם בסופה דחכמה וכמ\"ש ימותו ולא בחכמה<sup data-n=\"1845\">8</sup> כו' וד\"ל (וכמ\"ש בזהר פרש חגיכם<sup data-n=\"1846\">9</sup> ולא פרש שבתכם שהשבת בבחי' חכמה שנקרא קדש מלה בגרמיה<sup data-n=\"1847\">10</sup> כו' וע\"כ עיקר המצוה בשבת בענג ולא בשמחה וכמ\"ש וקראת לשבת עונג<sup data-n=\"1848\">11</sup> וע\"כ אין דין גהינם שולט בשבת<sup data-n=\"1849\">12</sup> כלל כידוע) וביאור הענין הנה ידוע ע\"פ ואחרי הרעש אש<sup data-n=\"1850\">13</sup> לא באש ה' ואחרי האש<sup data-n=\"1851\">14</sup> קול דממה דקה כו' דאש הוי' הוא שלהבת י\"ה<sup data-n=\"1852\">15</sup> דחו\"ב שנקרא אהבה בתענוגים אבל לא באש הוי' דחכמה רק אש דאלקים<sup data-n=\"1853\">16</sup> דבינה שזהו בחי' התפעלות רצוא דבינה בשמיעה מרחוק דהיינו שחפצו ותשוקתו להתדבק בה' כמו מתי אבוא ואראה<sup data-n=\"1854\">17</sup> פני אלקים עד שתכסוף וגם כלתה נפשו<sup data-n=\"1855\">18</sup> כו' שזה מצד הריחוק שעומד מרחוק וחפץ להתקרב להיות שהשגה אלקי' אע\"פ שמבין ומשיג בכי טוב הרי זהו עצמו בחי' ריחוק שמרחוק ה' נראה לו<sup data-n=\"1856\">19</sup> בהשגה זו כמו השומע דבר מה אע\"פ שמבינו היטב הרי אינו רואהו במהותו כמו שהוא רק שמציירו במחשבתו ע\"פ אופן השגתו ע\"כ נקרא שמיעה מרחוק והוא שעושה תשוקת ההתפעלות לראות כמ\"ש מתי אבוא בהיכלו ואראה פני כו' משום דלמת\"ב כלל<sup data-n=\"1857\">20</sup> כו' ולזה מהתבוננות דשמע ישראל תוליד אהבת בכל נפשך כו' אבל אינו דומה שמיעה לראיה שהוא ראיה דחכמ' שזהו כרואה בראית העין במוה\"ע<sup data-n=\"1858\">21</sup> ממש שאין שם בחי' רעש והתפעלות אש בהתלהבות כלל וכלל אלא אדרבה יתבטל ממציאותו לגמרי עד שאינו מרגיש א\"ע כלל וכלל מפני שרואה את המלך ועומד בראיה מקרוב שאז לא יתכן",[["1838","1","<b>ירגיז אדם</b>: ברכות ה, א."],["1839","3","<b>על חרבך תחי'</b>: תולדות כז, א."],["1840","2","<b>רישא דעשו. . בעטפוהי דיצחק</b>: ראה ת\"י ויחי נ, יג. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תרסב. קונטרסים ע' שלג."],["1841","4","<b>בענין מקרא קדש</b>: ראה גם לקמן קכח, א ובהנסמן במ\"מ לשם."],["1842","5","<b>ושמחת בחגיך</b>: פ' ראה טז, יד."],["1843","6","<b>פרש חגיכם</b>: נסמן בסמוך."],["1844","7","<b>אולי חטאו בני</b>: איוב א, ה. ראה שו\"ע אדה\"ז הל' פסח רסתצ\"ב. מאמרי אדה\"א במדבר ח\"ג ע' תתקע."],["1845","8","<b>ימותו ולא בחכמה</b>: איוב ד, כא."],["1846","9","<b>פרש חגיכם</b>: מלאכי יב, ג. זהר יתרו פח, ב. ראה גם מאמרי אדה\"א שמות ח\"א ע' קפה. וש\"נ."],["1847","10","<b>קדש מלה בגרמי'</b>: זהר אמור צד, ב."],["1848","11","<b>וקראת לשבת עונג</b>: ישעי' נח, יג. ראה לקמן קיג, א הערה ההפר' בין שבת."],["1849","12","<b>אין דין גהינם שולט בשבת</b>: ראה סנהדרין סה, ב וברש\"י שם. זהר יתרו פח, ב. מאמרי אדה\"א דברים ח\"ג ע' א'קיח. וש\"נ."],["1850","13","<b>ואחרי הרעש אש</b>: מלכים-א יט, יב [ושם: ואחר — ראה תו\"ח ח\"ש קמא, ג. מאמרי אדה\"א נ\"ך ע' יד. וש\"נ]."],["1851","14","<b>ואחרי האש</b>: מלכים-א שם [ושם: ואחר — ראה תו\"ח שם. מאמרי אדה\"א קונטרסים ע' שז. וש\"נ]."],["1852","15","<b>שלהבת י\"ה</b>: שה\"ש ח, ו."],["1853","16","<b>באש הוי'. . דאלקים</b>: ראה מאמרי אדה\"א נ\"ך ע' יד ואילך (ובהנסמן בריש המאמר שם)־ שמות ח\"ב ע' תרעג."],["1854","17","<b>מתי אבוא וארא</b>: תהלים מב, ג."],["1855","18","<b>שתכסוף. . נפשו</b>: שם פד, ג."],["1856","19","<b>שמרחוק ה' נראה לו</b>: ע\"פ ירמי' לא, ב."],["1857","20","<b>דלמת\"ב כלל</b>: ת\"ז בהקדמה (יז, א)."],["1858","21","<b>במוה\"ע</b>: נסמן לעיל ב, א."]]],[2800530159,"בחי' התפעלות תשוקה לקירוב כלל מאחר שכבר נתקרב והגיע לדבר שחפץ אלא אדרבה יתבטל ההתפעלות והתשוקה לגמרי מצד עוצם בחי' הביטול כל עצמותו והיינו בחי' ראי' דחכמה שהוא כח מ\"ה<sup data-n=\"1859\">22</sup> ביטול לאין אלקי בבחי' ראי' מקרוב כמו משה שאמר ונחנו מה<sup data-n=\"1860\">23</sup> כמ\"ש בו וירא ראשית<sup data-n=\"1861\">24</sup> כו' כידוע וזהו דמשה שושבינא דמלכא להמשיך גלוי אא\"ס מגבוה לנמוך שזהו בחי' השוב שאחר הרצוא דבינה וכמ\"ש ואחרי האש קול דממה דקה בחי' ביטול במציאות דתמן קאתי מלכא בעצמו אבל אהרן הוא שושבינא דמטרוניתא<sup data-n=\"1862\">25</sup> להעלות לנש\"י מלמטה למעלה בבחי' התפעלות דרצוא דבינה שזהו בחי' או\"ח ואח\"כ נמשך בחי' החסדים דאו\"י דמשה מלמעלה למטה וגובר על בחי' או\"ח דרצוא והוא בחי' המשכות גלוי אא\"ס במוה\"ע מגבוה לנמוך בבחי' ראיה מקרוב שזהו בחי' שוב בבחי' ביטול דחכמה שגובר על רצוא דבינה עד שלא יסתעף מזה שום יניקה לחיצונים כלל כמ\"ש ימותו ולא בחכמה לפי שאין יניקה לחיצונים רק בבחי' יש ודבר מה והוא בהתפעלות דרצוא בשמיעה מרחוק אבל בחכמה בראיה מקרוב ממש אין להם מקום שם כלל (דתמן קאתי מלכא כמו קומה ה' ויפוצו<sup data-n=\"1863\">26</sup> כו') וזהו ההפר' בין ק\"ש לשמ\"ע דק\"ש בשמיעה דבינה ע\"כ נתפעל באהבת בכל נפשך בבחי' או\"ח ובשמ\"ע בחשאי הוא בביטול במציאות בכריעה בברוך שהוא בחי' קול דממה דקה דתמן קאתי מלכא כידוע וד\"ל (וזהו שרחב\"ד לא הפסיק בתפלתו<sup data-n=\"1864\">27</sup> אע\"פ שנחש היה כרוך על עקבו לא הזיקו<sup data-n=\"1865\">28</sup> לפי שאין לנחש הקדמוני אחיזה בח\"י ברכאן דצלותא<sup data-n=\"1866\">29</sup> שהוא בכח מ\"ה דחכמה כנ\"ל דחויא קטיר לרגלוהי דנוק'<sup data-n=\"1867\">30</sup> ומאן דקטל לחויא<sup data-n=\"1868\">31</sup> יהבין ליה ברתא דמלכא דא צלותא כו' אבל לענין מי שתורתו אומנתו נהפוך הוא שפטור מן התפלה וחייב בק\"ש<sup data-n=\"1869\">32</sup> כר\"י הנשיא שהיה קורא פסוק ראשון דק\"ש<sup data-n=\"1870\">33</sup> משום דתורתו אומנתו<sup data-n=\"1871\">34</sup> היינו ג\"כ בחי' פנימיות כח מ\"ה דבחי' או\"י דהיינו בחי' מ\"ה דמשה שושבינא דמלכא כנ\"ל ונכלל בזה בחי' או\"י דח\"י ברכאן דצלותא כי יש בכלל מאתים מנה<sup data-n=\"1872\">35</sup> ע\"כ פטור מן התפלה אבל חייב בק\"ש להיות בבחי' רצוא דאו\"ח תחלה ואח\"כ והיו הדברים כו' ודברת בם<sup data-n=\"1873\">36</sup> כו' דאו\"י יגבר על או\"ח וד\"ל) והנה בחי' רו\"ש דאו\"ח ואו\"י דחו\"ב הנ\"ל הוא הנקרא ג\"כ בשם מ\"ן ומ\"ד כידוע דכל או\"ח הוא בחי' העלאת מ\"ן וכל או\"י שיורד מגבוה לנמוך הוא בחי' המשכת מ\"ד וידוע דהמ\"ד מברר למ\"ן<sup data-n=\"1874\">37</sup> כמו בזווג דכר ונוקבא כו' והיינו בחי' שוב שאחר הרצוא שמברר לרצוא שנקרא מ\"ן ובירור זה נקרא בירור שני כי בירור הראשון הוא בחי' הרצוא דאו\"ח עצמו שעולה ומתברר מלמטה למעלה ואח\"כ נתברר המ\"ן דאו\"ח בירור שני מן המ\"ד כו':\n(מט) <b>וביאור</b> כל זה הנה יש להקדים תחלה בענין הבירורים דרפ\"ח ניצוצין<sup data-n=\"1875\">38</sup> שנפלו בשבה\"כ מה ענינם דהנה ידוע בשורש כללות ענין הבירורים שכל עיקר השבירה היה רק כדי שיהיה העלאה ובירור אח\"כ לרפ\"ח ניצוצין כדי שמזה יהיה עונג גדול ונפלא בעצמות המאציל יותר מכל התענוגים העליונים שבעצמותו עד שמחמת העלאת מ\"ן דרפ\"ח כו' יתעורר לבא מהעלם העצמות ממש לגלוי למטה בתוס' אור רב בקו\"ח דאבי\"ע שלא הי'",[["1859","22","<b>דחכמה שהוא כח מ\"ה</b>: זהר (רע\"מ) צו כח, א. לד, א. ראה הנסמן לעיל י, א."],["1860","23","<b>ונחנו מה</b>: בשלח טז, ז. ח."],["1861","24","<b>וירא ראשית</b>: ברכה לג, כא. ראה גם לעיל מד, ב ובהנסמן במ\"מ לשם."],["1862","25","<b>אהרן. . דמטרוניתא</b>: ראה זהר (רע\"מ) ויקרא כ, א. הנסמן במאמרי אדה\"א דברים ח\"א ע' קג. מאמרי אדה\"א שמות ח\"ב ע' שטו וע' שמ."],["1863","26","<b>קומה ה' ויפוצו</b>: בהעלותך י, לה."],["1864","27","<b>שרחב\"ד לא הפסיק בתפלתו</b>: ראה תוספתא ברכות פ\"ג ה\"כ. ירושלמי שם פ\"ה ה\"א. ברכות לג, א. מאמרי אדה\"א דברים ח\"א ע' מא. וש\"נ. קונטרסים ע' שפה. וש\"נ."],["1865","28","<b>לא הזיקו</b>: ראה ירושלמי שם. רש\"י ברכות שם ד\"ה ומת הערוד. תו\"ח ויצא קעח, ג."],["1866","29","<b>בח\"י ברכאן דצלותא</b>: זהר בראשית כו, א. ברכות כח, ב."],["1867","30","<b>דחוי' קטיר לרגלוהי דנוק'</b>: ראה ת\"ז תכ\"ו (עב, א). ראה גם תו\"ח ויצא שם ובהערה 40. שע\"ת עד, ב."],["1868","31","<b>ומאן דקטל לחויא</b>: ראה ת\"ז סתי\"ג (כט, ב). תכ\"א (מג, א). תז\"ח (צט, ד)."],["1869","32","<b>מי שתורתו. . בק\"ש</b>: שבת יא, א. שו\"ע אדה\"ז הל' תפלה סק\"ו ס\"ד. הל' ת\"ת פ\"ד ס\"ה. לקו\"ש (אבות) כרך י\"ז ע' 135 ואילך. ראה גם מאמרי אדה\"א קונטרסים ע' שפג. וש\"נ."],["1870","33","<b>כר\"י הנשיא. . דק\"ש</b>: ראה ברכות יג, ב. מאמרי אדה\"א שמות ח\"ב ע' של."],["1871","34","<b>כר\"י. . דתורתו אומנתו</b>: ראה פע\"ח (שער הק\"ש) ש\"ח פ\"ד. מאמרי אדה\"א קונטרסים ע' שפה. וש\"נ. שע\"ת קג, ב ובהנסמן במ\"מ לשם."],["1872","35","<b>יש בכלל מאתים מנה</b>: ב\"ק עד, א."],["1873","36","<b>והיו הדברים. . ודברת בם</b>: ואתחנן ו, ו. ז."],["1874","37","<b>דהמ\"ד מברר למ\"ן</b>: ראה פע\"ח (שער התפלה) ש\"א פ\"ז. מאמרי אדה\"א קונטרסים ס\"ע תקמג ואילך. וש\"נ."],["1875","38","<b>דרפ\"ח ניצוצין</b>: נסמן לקמן קמ, ב."]]],[2800530160,"בא לגלוי מסדכ\"ס ע\"י כל תענוג היותר עליון שבעצמותו ממש ובאמת זהו דבר פלא ביותר דודאי גם שאו\"כ דתהו היו במעלה ומדרגה גבוה מאד נעלה וירדו למט' וחוזרים ועולין רפ\"ח ניצוצ' לשרשן מ\"מ אין זה ערוך כלל וכלל לגבי מוה\"ע<sup data-n=\"1876\">1</sup> ממש שלמעלה הרבה מבחי' התהו והתיקון כידוע ומכ\"ש אחר ירידתן למטה מטה כו' (וכמו שאנו אומרים אין דומה לך לתח\"ה<sup data-n=\"1877\">2</sup> שהן רפ\"ח ניצוצין שנפלו מז' מלכים שמתו כידוע) אך הענין הוא דתענוג גדול ונפלא זה מבירורים והעלאות דרפ\"ח כו' אין זה מצ\"ע אלא מצד שזהו דבר חידוש ונפלא ביותר שדבר הנשפל וירד כ\"כ למטה מטה עד שנעשה מזה בחי' נוגה דמעורב טו\"ר ממש יוכל להתעלות מעלה מעלה בשרשן בגבורות עליונות דאורות דתהו כמו שהיה קודם<sup data-n=\"1878\">3</sup> השבירה ממש זהו חידוש נפלא ביותר וכידוע שהתענוג מדבר מחוד' ונפלא ביותר יתפעל בעונג נפלא ביותר שאין כל עונג היותר עליון ישיגנו כי הרי יניח אדם כל תענוגים שבביתו היותר מעולים וערבים לנפשו וילך לראות בדבר חידו' נפלא שלא ראה מימיו כמו צפור המדברת<sup data-n=\"1879\">4</sup> כאדם או אדם פורח כצפור<sup data-n=\"1880\">5</sup> וכה\"ג מדברים המופלאים יתפעל בעונג נפלא יותר מכל תענוגים העצמיים וראיה שגם ברוב טרדת המלך ביותר בפנימיות רוממות מלכותו וברוב עושרו וגדולתו שלא יפנה לשום תענוגות בני היכלו אבל כאשר מביאים לפניו צפור המדברת כאדם או אדם פורח כצפור ממש יתפעל בעונג נפלא מדבר חידוש הנפלא הזה עד שיפנה ויסיח דעתו ולבו מכל הטרדא שבעצמות רוממותו ויסתכל בחידו' זה שלא ראה מעולם וכדומה לזה אשר לא היה נמשך לב המלך ולא היה נפנה לכל דבר תענוג שבעולם גם למנחת כסף וזהב ואבני חפץ מסגולת מלכים שאין לו כמוהו כי הורגל בכיוצא באלה אבל חידו' נפלא שלא ראה כמוהו עולה על כל התענוגים היותר עליונים שימשיכו בזה לב המלך גם מעומק רוממותו כו' והנמשל יובן מזה בכללות ענין התענוג הנפלא בעצמות מבירורים דרפ\"ח שירדו למטה כ\"כ ועלו למעלה בהעלאת מ\"ן כנ\"ל יותר מכל התענוגים העליונים שבעצמות עד שמזה יומשך גילוי פנימית ועצמות אוא\"ס למטה באבי\"ע לפי שזהו חידוש גדול ונפלא ביותר כמו צפור המדברת וכה\"ג ויותר חידוש מזה כי אורות וכלים דתהו שהיו למעלה כ\"כ ונפלו למטה כל כך עד התהוות חומריות העולם הזה שרובו רע גמור עולין למעלה מעלה ונכללים בעצמות המאציל בבחי' בירור והעלאות מ\"ן זהו תענוג גדול למעלה כ\"כ עד שנמשך אא\"ס ב\"ה באבי\"ע ברוב גילוי אור מהו\"ע ממש וד\"ל והנה ידוע שתכלית הכוונה בהשתלשלות העולמות היה כדי שיבוררו רפ\"ח ניצוצי' כו' שזה התענוג הגדול עלה במח' תחל' כידוע שזהו סוף מעש' שבתו\"מ שמבררי' עה\"ד טו\"ר שהן בירורים דרפ\"ח הוא שעלה במח' תחלה כו' וזהו<sup data-n=\"1881\">6</sup> שאמ' סוף דבר<sup data-n=\"1882\">7</sup> כו' והנה מטעם זה הוא שנמשך בחי' מ\"ד אחר בירור דהעלאת מ\"ן שזהו בירור השני כנ\"ל שהוא אותו התענוג הגדול שעבמ\"ת מן הבירורים הוא שיורד בבחי' או\"י על העלאת מ\"ן דאו\"ח לבררו בירור שני כנ\"ל והענין הוא דהעלאת מ\"ן העולה נקרא בירור ראשון והוא ע\"י שם ב\"ן שמברר שזהו הנק' בהמה רבה דרביעא על אלף טורין<sup data-n=\"1883\">8</sup>",[["1876","1","<b>מוה\"ע</b>: נסמן לעיל ב, א."],["1877","2","<b>אין דומה לך לתח\"ה</b>: ברכת יוצר לשבת [ושם: ואין. . לך מושיענו]."],["1878","3","<b>קודם</b>: ניתוסף ע\"פ דפו\"ר."],["1879","4","<b>צפור המדברת</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה כאן ע' רפח. תו\"ח וישלח קצ, א ובהערה 5."],["1880","5","<b>אדם פורח כצפור</b>: ראה ג\"כ רש\"י ולק\"ט לך יד, ב."],["1881","6","<b>וזהו. . כו'</b>: ניתוסף ע\"פ דפו\"ר."],["1882","7","<b>סוף דבר</b>: קהלת יב, יג."],["1883","8","<b>בהמה. . אלף טורין</b>: ראה זהר בראשית יח, ב. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' יב."]]],[2800530161,"ושתת לון בגמיע' חדא כו' (וביאור הדבר ידוע שהוא ביטול היש לאין דמלאכים שמתחדשים בכל יום ונכללים באלקות כמ\"ש בזהר ע\"פ מצמיח חציר לבהמה<sup data-n=\"1884\">9</sup> שהן המלאכים הנק' חציר שצומחים בכל יום ובחי' ב\"ן שתת לון כו' שמתבטלים ונכללים בפי המל' והיינו יוצר משרתים<sup data-n=\"1885\">10</sup> כו' כמ\"ש במ\"א (וכענין הושיט אצבעו הקטנה ביניהם ושרפן<sup data-n=\"1886\">11</sup> שמצד עוצם גלוי אור האלקי דבחי' מל' ביתר מכפי מדת' מתבטלים ונכללים במל' כו') (וכדוגמא דעליית הקרבן ע\"ג המזבח שעולה למעלה כו' ואח\"כ יורד<sup data-n=\"1887\">12</sup> אש של מעלה ונק' אריה דאכיל קרבנין<sup data-n=\"1888\">13</sup> כו') וכך מיכאל מקריב נשמות<sup data-n=\"1889\">14</sup> ע\"ג המזבח העליון שנכללים באור המל' דאצי' בבחי' העלאת מ\"ן כו') אך בירור ועלי' שנית אינו רק מן המובחר והברור בלבד אבל בחי' הפסולת שבהן לא יוכל לעלות ונופל למטה וכך מתברר עוד בירור אחר בירור עד שלא נשאר רק היותר נקי והפסולת היותר אחרון לבדו והוא בחי' בירורים דאו\"י מלמעל' למטה שאחר בירורי' דאו\"ח בהעלא' מלמטה למעלה כו' דהנה העלאה דאו\"ח בביטול היש לאין עדיין לא נברר ממנו כל חלקי הפסולת אלא כולו כמו שהוא עולה למעלה כו' ואע\"פ שנק' בשם בירור אבל זהו רק בירור הפסולת כמשל התכת כסף מעורב בסיגים ועפר הרבה כאשר נותנין אותו באש המצרף הרי האש טבעו לפרר החלקים ונפרדו כל חלקי הפסולת והסיגים ונעשים מובדלי' בפ\"ע ובהיתוך פ\"א עדיין הכסף גס ואינו נקי מפסול' לגמרי רק מפסול' גס אבל פסול' דק יש בו וכן בסיגי' יש עדיין הרבה כסף נקי ובהיתוך פ\"ב לסיגי' יוצא היותר גס שבכסף ובפ\"ג יוצ' כסף גס יותר עד פעם האחרון שהו' בירור הפסולת גמור אינו יוצא ממנו רק כסף רע אבל בהיתוך ובירור הכסף שיצא בבישול הראשון כאשר מהתכין אותו עוד פ\"ב יוצא ממנו הפסולת הדק ובפ\"ג יוצא פסולת דק יותר עד שנשאר בפעם האחרון כסף זך ונקי בתכלית נמצא בירור זה דכסף הוא בירור האחרון אחר בירור הראשון דהיינו גם לאחר שיצא ממנו הפסולת הגס מבררי' הנקי מכל פסולת דק ביותר והוא בירור היותר עליון שהוא הבירור בדבר שכבר הוברר משא\"כ בירור הפסולת נהפוך הוא כל שמבררים יותר נשאר הפסולת גס יותר והנקי גרוע ביותר ובבירור הנקי כל שמבררו יותר נשאר הכסף הנקי בתכלית והפסולת היוצא באחרונה הוא דק ביותר וב' מיני בירורים אלה הוא דמיון להבין בהפרש שבין בירורים דאו\"י לבירורים דאו\"ח הנ\"ל דבירור הפסולת דמיון לבירור דאו\"ח כמו בתשובה לברר את הרע גמור והרע מעורב בטוב הרבה ומתברר שנית עד שנשא' רק הפסולת רע גמור והטוב אינו מעולה כ\"כ משא\"כ בירור דאו\"י הוא לברר את הטוב כמו בירור הכסף הנ\"ל עד שנשאר רק הנקי בתכלית כמו מי יעלה כו' ובר לבב<sup data-n=\"1890\">15</sup> בתכלית וזהו הקרבת הנשמות שיורד אש דאצילות ומבררם עד שהן בתכלית הבירור ונק' בירור שני דמ\"ד שמברר למ\"ן ובירור המ\"ן היינו כמו בירור הפסול' הנ\"ל שהראשון שיוצא ביותר טוב והוא עצמו בא לידי בירור שני שנקרא בירור הנקי וכן בבירור שני דפסולת מבררים לנקי עד בירור הכסף הגרוע יותר שבבירור דפסולת האחרון שזהו בחי' מ\"ד שמברר למ\"ן דנשמות ומלאכים שבגופים חומריים דנוגה דעשי' אבל העלאה ובירור דמ\"ן אינו רק",[["1884","9","<b>מצמיח חציר לבהמה</b>: תהלים קד, יד. ראה הנסמן בהערה שלפנ\"ז. סידור שחרית סב, ב. מאמרי אדה\"א דברים ח\"א ע' רמג."],["1885","10","<b>יוצר משרתים</b>: ברכת יוצר. ראה הנסמן לעיל נג, א הערה במלאכים. . מוי\"ב."],["1886","11","<b>הושיט אצבעו. . ושרפן</b>: סנהדרין לח, ב. ראה מאמרי אדה\"א ויקרא ח\"א ע' קסא. וש\"נ. תו\"ח בראשית יז, ב ובהערה 9."],["1887","12","<b>דעליית הקרבן. . ואח\"כ יורד</b>: ראה מאמרי אדה\"א דברים ח\"ד ע' א'תפה. וש\"נ."],["1888","13","<b>אריה דאכיל קרבנין</b>: ראה זהר בהקדמה ו, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תקלא. וש\"נ. דברים ח\"א ע' שב. ח\"ד ע' א'תפה. דרושי חתונה ח\"א ע' רפ. לקו\"ת עקב יג, ד. לקו\"ש (צו) כרך כב ע' 16 ואילך וראה גם שם הערה 35."],["1889","14","<b>מיכאל מקרוב נשמות</b>: ראה חגיגה יב, ב [כגי' הע\"י]. תוד\"ה ומיכאל מנחות קי, א. מאמרי אדה\"א נ\"ך ע' תסז. וש\"נ. שע\"ת נו, ג ובהנסמן במ\"מ לשם."],["1890","15","<b>מי יעלה כו' ובר לבב</b>: תהלים כד, ג. ד."]]],[2800530162,"בירור הפסולת דנוגה דבי\"ע עד בירור פסולת דנוגה דעשי' האחרון כו' וד\"ל (ובאמת אין דמיון זה מתיישב לענין בירורי' דאו\"י וא\"ח הנ\"ל שמדבר הכל בענין בירור א' אלא שבירור דאו\"י נקרא בירור שני כנ\"ל ובכאן הרי ב' מיני בירורים בב' דברים מחולקים בנקי ובפסולת כנ\"ל אלא הענין הוא כך דכאשר מבררים בירור ראשון במצרף לכסף וזהב הרי הכסף היוצא הוא הגס והפסול' ועדיין כל חלקי כסף הטוב ונקי ביותר מעורבי' בסיגי' עד בירור האחרון יוצא הכסף היותר נקי מפני שהובדל מן הפסולת היותר דק (בהיפוך מענין הנ\"ל) ונמצא בבירור האחרון הרי ההבדלה בין טו\"ר נקי ופסולת הוא בתכלית הדקות שבטו\"ר היינו שגם הדק שפסולת הוברר הכל וע\"כ הכסף נקי בתכלי' עד שהנשאר פסולת הוא בתכלי' הדקו' עד שיחשב בבחי' כסף טוב יותר מכסף היוצא בבירור הראשון וכה\"ג זהו הנק' בירור שני אחר בירו' הראשון בדרך כללות והיינו שיש בזה ב' אופנים למע' שנק' בירורים דאו\"י שהוא הבירור שני אחר בירור דאו\"ח בכל עולם לפי מה שהוא כמו בעולם העשיי' עולה בבירור דאו\"ח שהוא בירור בין טו\"ר דנגה דעשיי' ואח\"כ מתברר עוד בירור שני ע\"י המשכה דאו\"י להיות הטו\"ר מובדלים בדקות שלהם וכמו\"כ עד\"ז בעולם היצירה בחי' מ\"ן בירור והעלאה בטו\"ר דנגה דיצירה ואח\"כ נמשך בירור שני דמ\"ד לברר בדקות כו' וכמו\"כ בעולם הבריאה כו' וכמו נשמות דבריאה שכבר הובררו בבירור ראשון שעולין ע\"ג מזבח נבררו ע\"י המשכת מ\"ד מאצי' בירור שני וכך הוא עד רום המעלות כו' ונמצא שבירור שני דמ\"ד דעשי' נעשה בבחי' או\"ח ביצירה כו' וד\"ל וכפי זה המשל הרי הכסף פסולת דבירור השני יותר טוב מכסף נקי דבירור האחרון כך בירור השני דבריא' גם הפסולת יותר טוב מהטוב ונקי דבירור שני דיציר' וכן מיציר' לעשי' וכן להיפך הטוב ונקי דבירור שני דעשי' נחשב פסולת מעורב בבחי' בירור הראשון דיצירה וכן מיצירה לבריאה ומבריאה לאצילות שהן נשמות בבירור שני דבריאה צריכים לבא בבירור ראשון באצילות והוא כדי לאשתאב' בגופ' דמלכ'<sup data-n=\"1891\">1</sup> מקריבין ע\"ג מזבח דאצי' שנק' בירו' ראשון וד\"ל:\n(נ) <b>ולהבין</b> כל זה יש להקדים תחלה ע\"ד דוגמא בעבודת ה' בתפלה בנשמה האלקית שמברר לנה\"ב דהיינו שם מ\"ה שמברר לב\"ן<sup data-n=\"1892\">2</sup> דהיינו אדם מ\"ה כי יקריב מן הבהמה ב\"ן<sup data-n=\"1893\">3</sup> כידוע דהנה ידוע דנה\"ב נלקחה מק\"נ דעשי' שמעורב טו\"ר בתכלית<sup data-n=\"1894\">4</sup> היינו שאין כל חלק ממנה שלא יהיה הטוב מעורב ברע ורע מעורב בטוב בכל חלקי חלקיו כתערובת לח בלח וכה\"ג וע\"כ גם בעשותו הטוב שם ימצא רע הרבה כמו העושה צדקה להתייהר וכמתפלל ולבו רחוק מאד ולא עוד אלא גם במי שמתפלל בהתפעלות הלב מיד אחר התפל' יוכל ליפול בתאות רעות כזולל וסובא וגזל וניאוף וכעס ורציחה וכה\"ג שאם היה התפעלותו בהתלהבות אמיתית ודאי היה רחוק מכל אלה אשר תעוב בעיני ה' מאד וזהו כמו ב' הפכים ממש מן הקצה לקצה אלא מוכרח לומר דההתפעלו' היה שקר דהיינו שהי' בתערובו' גדולה מטו\"ר עד שהטוב שבו גם הוא כשקר",[["1891","1","<b>לאשתאב' בגופ' דמלכ'</b>: זהר ויחי ריז, ב. ראה הנסמן במאמרי אדה\"א ויקרא ח\"א ע' מה־ תו\"ח בראשית מ, ב הערה 25."],["1892","2","<b>מ\"ה שמברר לב\"ן</b>: נסמן לקמן קלג, א."],["1893","3","<b>אדם מ\"ה. . הבהמה ב\"ן</b>: ויקרא א, ב [בדילוג]. ראה גם מאמרי אדה\"א שמות ח\"א ע' צה. וש\"נ."],["1894","4","<b>דעשי' שמעורב טו\"ר בתכלית</b>: ראה ע\"ח (שער הקליפות) שמ\"ח פ\"ג. מאמרי אדה\"א ויקרא ח\"ב ע' תדש. וש\"נ. הנחות תקע\"ז ע' פג. וש\"נ."]]],[2800530163,"יחשב שהרי סופו מוכיח שמיד יפנה לבו להיפוכו לסתור מה שהיה חושב בלבו כמו אמת בנפשו כו' ויכול להיות ג\"כ להיפך שבעשותו הרע יתעורר אח\"כ בתשוב' לשוב אל ה' לתורה ותפלה ולעזוב רשעתו וחוזר מיד לסורו וכענין רשעים מלאים חרטות<sup data-n=\"1895\">5</sup> כו' ששב ומתחרט וחוזר לסורו וחוזר ומתחרט כו' וכל זה רק מצד בחי' גודל עוצם התערובות טו\"ר שבנפשו' הרשעי' ע\"כ לפעמים יגבר הטוב ולפעמים יגבר הרע בכל פרטי חלקיו כו' (וז\"ש אליהו עד מתי אתם פוסחי'<sup data-n=\"1896\">6</sup> כו' וכמ\"ש במ\"א בענין בינוני' זו\"ז שופטן<sup data-n=\"1897\">7</sup> ) ועד\"ז אנו רואים תערוב' טו\"ר בדקו' יותר אבל הוא ג\"כ באותו אופן שמעורב טו\"ר בתכלית כנ\"ל והוא בענין ריבוי המ\"ז בתפלה<sup data-n=\"1898\">8</sup> דהנה אנו רואים בעת התפלה גם בשעת הכושר שמכוין לבו בהתפעלות תשוקה בלב נכון מיד במעט רגע חולפת ועוברת ונופלים לו מ\"ז רבות של כל דבר רע וטמא המטמא את הנפש שזה ג\"כ תרתי דסתרי ב' הפכים ממש ברגע א' כנ\"ל אלא שזהו בדקות יותר לכאורה כי אין זה בפועל רע רק במחשבה ולא ברצון באמת אך הנה באמת לא קרב זא\"ז כלל אדרבה הן ב' הפכים מן הקצה כו' דהיינו שזה נק' תערובות טו\"ר באמת בלי יפרדו לעולם יחדיו ישכנו תמיד ואינם סותרים זא\"ז כלל והוא מה שמתפלל ולבו רחוק שמיד יעשה היפוכו ואינו מרגיש כלל כנ\"ל וכנותן לעני ומביישו או להתייהר בלבד וכה\"ג וזהו כמו דבר גוש המעורב טו\"ר בתכלי' בעצם בכל חלקיו העצמיים מורגש הרע עם הטוב יחדיו כא' כו' אבל ענין המ\"ז הנופל ממילא שלא ברצון דוקא בעת הכושר שיכשר לבו בעבודתו בתפלה כנ\"ל זהו בא רק מסיבת פירוד התערובות טו\"ר שבנפשו שיצאו הטו\"ר מפורדים מדיבוקם יחד ע\"כ יתעוררו החלקי רע לצא' בפ\"ע והן המ\"ז כו' שהרי בלא זמן תפלה אין התעוררו' בלבו למ\"ז כאלה הגם שכבר היה לבו נמשך ומהרהר בהן אבל נשאר הרע גנוז בנפשו בתערובת בהעלם ובעת התגברותו לעלות בעבודה תמה שבלב אז דוקא יתעורר הרע הגנוז לצאת מהעלמו והן כל המ\"ז מכל דבר רע שהיה טמון בלבו עד הנה שנופלים לו בעת כשרון לבו דוקא בתפל' וכשאין התעוררו' העבודה שבלב כלל וכלל בעת התפלה רק בפיו ושפתיו יכבד<sup data-n=\"1899\">9</sup> ולבו רחוק לגמרי אזי לא יפלו מ\"ז כלל (רק שמעורב טו\"ר בעצם וע\"כ יכול לעשות היפוכו מיד אחר התפל' כנ\"ל) והענין הוא עד\"מ הידוע בקדרה של מים ותבשיל שמבשלים באש הרבה שע\"י הבישול באש יבלבל וירתיח כל המים ובשר שבקדרה עד שעולה ויורד ברתיחה ובלבול גדול מלמטה למעלה ומלמעלה למטה כמה פעמים רבות כו' ואז יפוררו ויפרדו כל החלקים שבבשר ותבשיל זה מזה דהיינו הטו\"ר שבו יצאו מפורדים והיינו מה שהיה חלקי פסולת ורע במאכל יוצא לגלוי לחוץ וגם החלקי טוב שבו יוצאים לחוץ ומתבלבלין יחד וע\"י הרתיח' ובישול זמן רב יותר יותר יצא כל חלקי הרע ופסולת ויתגלה יותר הטוב טעם שבמאכל ויהי' מאכל ותבשיל טוב למאכל אדם משא\"כ בלא בישול באש כלל נשאר כל חלקי הפסולת ורע בהעלם בתערובת עצמי במאכל ואינו ראוי למאכל כלל כי הטוב שבו אינו טוב טעם כלל מצד התערובת רע שבו ונמצא הבישול עשה ענין הגלוי ופירוד התערוב'",[["1895","5","<b>רשעים מלאים חרטות</b>: ראה גם לעיל מ, א ובהנסמן במ\"מ לשם."],["1896","6","<b>עד מתי אתם פוסחי'</b>: מלכים-א יח, כא. ראה גם מאמרי אדה\"א שמות ח\"ב ע' שפ. תו\"ח וישב רא, א. שמות נב, ב."],["1897","7","<b>בינוני' זו\"ז שופטן</b>: ברכות סא, ב. ד\"ח שער התפלה עז, ב."],["1898","8","<b>ריבוי המ\"ז בתפלה</b>: ראה גם שע\"ת מט, ד ובהנסמן במ\"מ לשם."],["1899","9","<b>בפיו ושפתיו יכבד</b>: ע\"פ ישעי' כט, יג."]]],[2800530164,"טו\"ר שלא היה ניכר כלל קודם הבישול כו' והנמשל יובן בענין התפעלו' שלהבת האלקי מן ההתבוננות בתפלה בעבודה תמה ברשפי אש התשוקה שהוא כמו רתיח' המים בקדירה מן האש כנ\"ל אז יפרדו חלקי הטו\"ר שבנפש ויוצא הרע ופסולת בהבדלה לחוץ ולא שחפץ ברע זה אדרבה מרגישו ביותר ויותר יהיה לו למנגד לחפצו ורצונו הטוב ורואה בעצמו כל הרע שבו ויכאב לבו על זה להבדילו ולהרחיקו מה שאין כן בלא התפעלות בעבודה שבלב בתפלה לא ידע כי ברע הוא והי' צדיק בנפשו בלתי מרגיש כלל ע\"כ יכול לימשך אחר הרע בפ\"מ תומ\"י וטח עיניו מראות כי בחושך ילך כו' וא\"כ מובן שבשעת התפלה שהוא כמו הבישול נק' בירור גמור שמתברר הרע מן הטוב ונופל כל חלקי הגסות ופסולת ובזה יטהר לבו מכל סיג ופסולת שהי' גנוז ונעלם בנפשו עד הנה מתאות חומריות עוה\"ז ולא הי' ניכר כלל ועתה יצא הרע מובדל ושב בתשוב' כי הרי חוזר ומתגבר בנפשו למאוס ברע זה שנפל בלבו וזהו שאמרו בזהר דשעת צלותא שעת קרבא<sup data-n=\"1900\">1</sup> וכמ\"ש בחרבי ובקשתי<sup data-n=\"1901\">2</sup> כו' שזהו לנצח הרע העומד לנגדו בגילוי מטעם שיצא מן ההעלם לעמוד לנגד הטוב וא\"כ זהו היפך גמור מתערובת טו\"ר בעצם הנ\"ל וד\"ל אך הנה עדיין אין זה נק' בירור גמור לתכליתו וכמשל הבישול באש לקדירה שאע\"פ שנפרדו כל חלקי הגסות והפסולת בפ\"ע הרי הן עולין ויורדי' ברתיחת הבישול ולא ניכר בין טו\"ר עד שתנוח הרתיחה לגמרי אז יפול כל הפסולת למטה והטוב שבתבשיל נשאר למעלה והן<sup data-n=\"1902\">3</sup> הפסולת הנדבק בשולי הקדרה שנק' ציקי קדירה כידוע והנה ידוע שכדי שיפרד ויפול הפסולת למטה בשולי הקדרה היינו אחר גמר בישול' דוקא שכ\"ז שלא נתבשל כ\"צ מבולבל הכל אע\"פ שכבר יצא הטעם שבתבשיל אך לאחר גמר הבישול דוקא אז נותנים בקדרה מים יפים כדי להמתיקה כידוע וזהו עיקר גמר הבישול שבזה יבדל הטוב ויפול הרע והפסולת למטה ונעשה מתוקן וראוי למאכל כל צרכו משא\"כ בלא נתינ' מים הללו שלא נמתק עדיין הרתיח' והבלבול כלל וד\"ל והנמשל יובן מזה בענין בירור שני שאחר בירור הראשון הנ\"ל דהנה הגם שכבר נפרדו כל חלקי הרע והפסולת שבנה\"ב בעת כשרון לבבו עד שגובר הטוב על הרע ומנצחו אין זה נצוח גמור כי הרי חלק הרע חוזר ונעור בשעת התפלה כי גובר עוד חלק הרע לבלבלו ויפול במחשבות לא טובות למונעו מעבודתו כידוע רק שחוז' ומתגבר חלק הטוב בעבודת הלב ביגיעת הנפש עד שמואס בכל רצון זר זולת לה' לבדו ונעשה אצלו הסכם חזק בקבלת עומ\"ש על כל היום והרי מ\"מ לא יצא י\"ח הבירור לתכליתו כי לא נתבער הרע מכל וכל אלא ישנו במציאותו עד שעול' גם הוא בעלו' הטוב לבלבלו כנ\"ל וזהו כמשל הקדר' שבאש דגם שע\"י הבישול כבר הוברר הפסול' לעצמו והטוב לעצמו מ\"מ בעוד שהרתיחה בתקפה מתבלבל הכל כא' הפסולת עולה ויורד וכן הטוב והתמצית עולה ויורד מבלי היכר ביניהן כלל עד שתנוח הרתיחה לאחר גמר הבישול אז יתנו מים בקדרה להמתיקה זהו גמר הבירור שע\"י הבישול כנ\"ל כך הוא בשעת התפלה גם לאחר בישול",[["1900","1","<b>דשעת צלותא שעת קרבא</b>: ראה זהר (רע\"מ) פינחס רמג, א. ויחי רמ, ב. ת\"ז תי\"ג (כט, ב). הנסמן לעיל לז, א הערה בתפלה."],["1901","2","<b>בחרבי ובקשתי</b>: ויחי מח, כב. ראה גם מאמרי אדה\"א דברים ח\"ב ע' תפז. וש\"נ."],["1902","3","<b>והן</b>: כ\"ה בדפו\"ר. ובמהדורת לעמבערג: וכן."]]],[2800530165,"באש התשוקה שבלב עולה גם הרע לבלבלו ואין זה בירור לתכליתו רק נק' בירור ראשון אלא עיקר גמר הבישול היפה הוא כאשר לא יפול עוד במ\"ז כלל והוא כמו כאשר תנוח הרתיח' בקדרה ע\"י המתקה במים יפים (בל\"א אפ גילעשט) היינו בחי' המשכת השוב שהוא מי החסדים דאו\"י שממתיק לגבורו' דבחי' רצוא הנ\"ל והוא ענין אור ההארה האלקי' שמאיר ונמשך בנפשו מלמעלה למטה בבחי' או\"י והוא אור האלקי בבחי' כח מ\"ה דנשמה האלקי' שהוא בחי' הביטול לאין האלקי בעצם כידוע שיורד מגבוה לנמוך להמתיק לגבורו' רשפי אש הבישול דבחי' רצוא ותשוק' שבלב לעלות למעלה שזהו כמו מים יפים שנותנין בקדרה לקרר הבישול והרתיחה כדי שיפלו הפסולת למטה כך הוא המשכת אין ומ\"ה דחכמה דנשמ' בנפשו אשר עי\"ז נשקט הרתיחה ונברר בנפשו כל חלקי הגסות ופסולת אשר נתעוררו גם הם לעלות ע\"י הבישול שירדו ויפלו למטה מטה ולא יוסיפו עוד לעלות ולבלבל כלל וזהו עיקר שלימות הבירור ונק' בירור שני דבחי' או\"י אחר בירור הראשון דאו\"ח והוא בחי' המשכת מ\"ד דשם מ\"ה דחכמה שמברר בירור שני להעלאת מ\"ן דב\"ן שנק' בירור ראשון (וכמו העלאת מ\"ן דנוק' לגבי דכורא שעולה ברתיחה וכמ\"ש אשה כי תזריע<sup data-n=\"1903\">4</sup> כו' דאשדי מיין<sup data-n=\"1904\">5</sup> לקבל טיפת מ\"ד אך נק' בירור ראשון עד\"מ בישול הקדרה הנ\"ל אע\"פ שמופרד הטו\"ר נקי ופסולת ע\"י הגבורו' דנוק' דואל אישך תשוקתך<sup data-n=\"1905\">6</sup> ברשפי אש ממש אבל מבולבל כא' ואח\"כ נמשך המ\"ד על המ\"ן לבררו בירור שני והוא כמו מים יפים שממתיקים לבישול ורתיחת הקדר' וכמ\"ש בזה' אתבסמ' נוק'<sup data-n=\"1906\">7</sup> כו' דהיינו שנשקט הרתיח' והשתוק' כשמקבלת השפע מ\"ד ואז שלימות הבירור להיות הולד נולד מן הברור שבטפה<sup data-n=\"1907\">8</sup> כו' דהיינו מן הברור שבטפת מ\"ד ומ\"ן כלובן דאב שממנו עצמו' ומוח וצפרניים ואודם דאם<sup data-n=\"1908\">9</sup> שממנו בשר וגידים<sup data-n=\"1909\">10</sup> ושערות כו' עד גם השחור ולובן שבעין שכלולים ממ\"ן ומ\"ד<sup data-n=\"1910\">11</sup> ג\"כ ומן הפסולת נעשה השליא<sup data-n=\"1911\">12</sup> כו' הרי נעשה בירור גמור בכל שפע המ\"ן רק ע\"י המ\"ד להיות הולד נוצר ברמ\"ח אברים פנימיים וחיצונים עד שערות וצפרני' ושחור ולובן שבעין משא\"כ בלא בירור שני דמ\"ד הי' הכל מעורב כא' כו' וכ\"ש שלא הי' נבדל הפסול' גמור להיות בפ\"ע כמו השליא וכה\"ג וזהו כדמיון הנ\"ל בנתינ' מים יפים בקדר' להמתיק שיפול הפסולת למטה<sup data-n=\"1912\">13</sup> (והיינו כמ\"ש במ\"א שזהו כמחבץ<sup data-n=\"1913\">14</sup> שנותן עור קיבה בחלב רותחת שנקפא החלב ונבדל הנסיובי דחלבא וז\"ש וכגבינה תקפיאני עו\"ב תלבישני<sup data-n=\"1914\">15</sup> מן הבירור הראשון שבמ\"ן ובירור שני וכגבינה תקפיאני כו' וזהו מים ראשונים מצוה מ\"ד מים אחרונים חובה להעביר פסולת שבמ\"ן מים אמצעים<sup data-n=\"1915\">16</sup> בין גבינה לבשר כו' כמ\"ש במ\"א וד\"ל):\n(נא) <b>ובכל</b> דוגמא זאת יובן ענין בירור השני דמ\"ד דאו\"י דשם מ\"ה אחר בירור הראשון דהעלאת מ\"ן דאו\"ח למעלה בבחי' שם מ\"ה וב\"ן העליונים שז\"ש דבהמה רבה רביעא כו' ושתת לון הוא בירור הראשון דאו\"ח כנ\"ל הענין הוא עד\"מ הנ\"ל בבישול הקדרה שזה נק' בירור",[["1903","4","<b>אשה כי תזריע</b>: תזריע יב, ב."],["1904","5","<b>דאשדי מיין</b>: ראה זהר נח ס, ב. ביאוה\"ז שם ו, ב."],["1905","6","<b>דואל אישך תשוקתך</b>: בראשית ג, טז."],["1906","7","<b>אתבסמ' נוק'</b>: ראה זהר לך צד, א."],["1907","8","<b>הולד. . הברור שבטפה</b>: נדה לא, א."],["1908","9","<b>כלובן דאב. . ואודם דאם</b>: ראה נדה שם."],["1909","10","<b>דאם. . וגידים</b>: כ\"ה בכ\"מ בדא\"ח ? ראה לקמן צט, ב. מאמרי אדה\"א ויקרא ח\"א ע' שנו. וש\"נ. בראשית ע' תעה. וש\"נ. שמות ח\"א ע' ט. תו\"ח תולדות קמח, ג.\nומ\"ש בע\"ח (שער טנת\"א) ש\"ה פ\"ה ?השס\"ה גידין של הדם הוא מהנקבה\" אינו שייך לענינינו.\nבכתבי הרח\"א ביחובסקי [ברוקלין, תש\"נ] ע' קלד מביא ?בגידין יש ב' גירסאות בנדה אם הם מהאב או מן האם\". אמנם לא ציין מקורו."],["1910","11","<b>השחור ולובן. . ממ\"ן ומ\"ד</b>: נדה שם."],["1911","12","<b>ומן הפסולת נעשה השליא</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'תפד. וש\"נ. תו\"ח לך צד, א ובהערה 13. וראה גם אוה\"ת שופטים ע' תתל."],["1912","13","<b>למטה</b>: אוצ\"ל: למטה)."],["1913","14","<b>שזהו כמחבץ</b>: ראה ביאוה\"ז נח ו, ג. מאמרי אדה\"א ויקרא ח\"ב ע' תכ ואילך."],["1914","15","<b>וכגבינה תקפיאני עו\"ב תלבישני</b>: איוב י, י. יא."],["1915","16","<b>מים ראשונים. . אחרונים. . אמצעים</b>: ראה חולין קה, א. זהר (רע\"מ) פינחס רמו, א. ביאוה\"ז נח שם. בחוקותי פד, ב. אמ\"ב שער הק\"ש לא, א ואילך. פיה\"מ סה, א. מאמרי אדה\"א ויקרא שם ע' תרא."]]],[2800530166,"עכ\"פ ולא כמו שבלעדי האש שהכל מעורב טו\"ר בעצם בלי יפרדו לעולם אלא עולין רפ\"ח ניצוצין בבחי' הבירור דעה\"ד טו\"ר דוקא כנ\"ל בענין התפעלות רשפי אש בעבודה שבלב בתפלה כו' שהטוב האלקי עולה ונפרד מן הרע כך יש מלאכים שנבראים מרפ\"ח ניצוצין שנפלו בעה\"ד טו\"ר ועולין בפי בהמה רבה שהוא שם ב\"ן בבחי' בירור דוקא וז\"ש מצמיח חציר לבהמ' כו' כנ\"ל (וכך יש גם בנשמות שמיכאל מקריב כו' כנ\"ל) אך זהו בירור הראשון דהעלאת מ\"ן דב\"ן שזהו כרתיחת הקדרה שהכל עולה ומבולבל יחד כו' עד שיומשך המשכת מ\"ד דאצילות משם מ\"ה מלמעלה למטה לברר להעלאת מ\"ן הזה בבירור שני שהוא להמתיק לגבורות דמ\"ן זה העולה כמשל זיווג דונו\"ק<sup data-n=\"1916\">1</sup> שהמ\"ד מברר למ\"ן וכמים יפים בקדר' רותחת להמתיק כנ\"ל ומה שלא יוכל ליברר נופל למטה בשולי הקדרה כך מה שלא יוכל ליברר ולעלות באצילות בבחי' המשכת דאו\"י זה נופל למטה בבחי' פסולת דנוגה דבריאה כי המובחר עולה באצילות כו' ובעולם הבריאה מתברר עוד ע\"י שם מ\"ה דז\"א דבריאה ומה שלא יוכל ליברר ולעלות בבריאה נופל הסיגים ביצי' וכן מיצי' לעשי' עד הסיגים היותר גסים דעשי' שלא יוכלו ליברר בבירורים דאו\"י ואו\"ח דמ\"ד ומ\"ן מ\"ה וב\"ן דעשי' נופלים ויורדים למטה ממש ונעשים קליפות ורע גמור (וכמו הנפילים היו בארץ<sup data-n=\"1917\">2</sup> כו' שהיו מפסולת מ\"ד ומ\"ן דעשי' שלא נבררו כלל וכה\"ג) ונמצא מובן עכ\"פ מכ\"ז שאין עיקר שלימות הבירורים דרפ\"ח ניצוצין שנפלו בעה\"ד טו\"ר גם כשעולין למעלה ונכללין במ\"ן דמל' דאצי' (כידוע בפי' ר\"ת בא\"ר בידך<sup data-n=\"1918\">3</sup> כו' שהן העלאת מ\"ן דנשמות ביסוד דנוקבא שנקרא באר מים חיים<sup data-n=\"1919\">4</sup> כו' וז\"ש עלי באר מלמטה למעלה ענו לה<sup data-n=\"1920\">5</sup> בהמשכת מ\"ד כו' וזהו בחי' בארה של מרים<sup data-n=\"1921\">6</sup> גם עתה שכל הרוחות ונשמות עולין ונכללים שם וכמו בע\"ת וצדיקים הכל כא' כו' וע\"י המשכת מ\"ד כתיב מלפני אדון חולי ארץ שנמתקים גבורות דנוק' ההופכי הצור<sup data-n=\"1922\">7</sup> כו') אין נמתקים לתכליתן עד שיפרדו ויפלו הפסולת למטה כל מה שלא יוכלו להתברר ולעלות כנ\"ל אלא ע\"י בחי' המ\"ד דאו\"י דוקא שהוא בחי' שם מ\"ה דחכמה שמברר למ\"ן שבחכמה אתברירו<sup data-n=\"1923\">8</sup> דוקא שהן מי חסדים שיורדים מלמעלה למטה דוקא והיינו בחי' שוב שאחר הרצוא בתפלה שמשקיט הצמאון והרתיחה כמ\"ש אם רץ לבך שוב<sup data-n=\"1924\">9</sup> כו' וזהו בחי' התגברות דאו\"י על או\"ח שזהו עיקר שלימות הבירור דמ\"ן דאו\"ח שנק' בירור שני דמ\"ד כנ\"ל וד\"ל ובכל זה יובן מ\"ש בענין קי\"ס ג' פסוקים אלה זא\"ז לגוזר י\"ס לגזרים כל\"ח והעביר ישראל בתוכו כל\"ח וניער פרעה וחילו בי\"ס כל\"ח הרי חלק בחי' חסד לכל א' בפ\"ע ולמה לא כללם יחד והול\"ל לגוזר י\"ס והעביר וניער כל\"ח כו' דהנה מבואר למעלה בענין אז ישיר משה ובנ\"י כו' בשרש קי\"ס שהוא רק ענין התגברות דחסדים דאו\"י על גבורות דאו\"ח והענין הוא כידוע שגלי הים שמתנשאים זהו כמו רשפי אש העולה בבחי' גבורות והסתלקות דמקבל לגבי המשפיע וכמ\"ש בזהר כד סליק ימא גלגלוהי<sup data-n=\"1925\">10</sup> כו' והיינו כמו העלאת מ\"ן דנוק' וע\"כ כל נוני ימא מתבדרין כו'",[["1916","1","<b>דונו\"ק</b>: דכר ונוק'."],["1917","2","<b>הנפילים היו בארץ</b>: בראשית ו, ד. ראה גם לקמן ק, א ובהנסמן במ\"מ לשם."],["1918","3","<b>ר\"ת בא\"ר בידך</b>: תהלים לא, ו. ראה פע\"ח (שער קשעהמ\"ט) שט\"ז פ\"ב. פ\"י. משנת חסידים וסידור האריז\"ל במקומו. ספר הגלגולים פ\"ח. מאמרי אדה\"ז על פרשיות התורה ח\"ב ס\"ע תשטו. תקס\"ה ח\"א ס\"ע קיג ואילך (נוסחא שני'). לקמן ק, ב."],["1919","4","<b>באר מים חיים</b>: שה\"ש ד, טו. ראה ע\"ח (שער הארת המוחין) של\"ב פ\"ו. פ\"ז. אוה\"ת ויצא (כרך ה) ע' תתסו."],["1920","5","<b>עלי באר. . ענו לה</b>: חוקת כא, יז."],["1921","6","<b>בארה של מרים</b>: ראה גם לקמן ק, ב ובהנסמן במ\"מ לשם."],["1922","7","<b>מלפני אדון. . ההופכי הצור</b>: תהלים קיד, ז. ח. ראה גם לקמן ק, ב. מאמרי אדה\"א ויקרא ח\"א ע' כח ואילך. וש\"נ. נ\"ך ע' יז. וש\"נ."],["1923","8","<b>שבחכמה אתברירו</b>: נסמן לקמן קלג, א."],["1924","9","<b>אם רץ לבך שוב</b>: ס\"י פ\"א מ\"ח. ת\"ז בהקדמה (ז, א)."],["1925","10","<b>כד סליק ימא גלגולהי</b>: ראה זהר בשלח מח, ב."]]],[2800530167,"שנעשים מבולבלין בסדרן ומדרגתן (כמ\"ש ביאור המאמר באריכות<sup data-n=\"1926\">11</sup> במ\"א) עד דאתא דברא בימא שהוא המתק' חסדי' דמ\"ד שנשקט הים מזעפו כו' עד שכל א' על מקומו יבא כו' כמו משל הנ\"ל במים יפים בקדרה רותחת כמ\"ד דדכורא שמשקיט רתיח' התשוקה דמ\"ן דנוק' ועושה בירור שני כל א' על מקומו עד שהפסול' נדחה למטה לגמרי כו' כנ\"ל וכך היה ממש סיבת בקיעת הים מפני ישראל לפי שישראל המה בשרשם מבחי' או\"י דבחי' יושר דאור הזרוע לצ\"ע שהוא בחי' מ\"ה דאור אבא דאצי' כמ\"ש כי אתה אבינו<sup data-n=\"1927\">12</sup> כידוע ע\"כ נמתקו ונתבטלו בחי' הגבורות דים ששרשו בבחי' או\"ח דעיגולים כנ\"ל בחסדים דאו\"י שנמשך מלמעלה למטה כמו מבחי' השוב דחכמה שנמשך על בחי' הרצוא וזהו לגוזר י\"ס לגזרים והעביר ישראל דהיינו שנתן כח ועוז לישראל שיגברו על הגבורות דים וזהו לגוזר י\"ס ע\"י רוח קדים עזה כנ\"ל כדי שיעברו ישראל לגבור על או\"ח כו' ולכך חלקם לב' חסדים חסד הא' מה שגוזר בעצמו נגד י\"ב שבטים וחסד הב' והעביר ישראל בתוכו להמתיקם כו' ואח\"כ חסד הג' וניער פרעה כו' דהיינו מצד שבאו ישראל בים ונמתקו הגבורות די\"ס ממילא נפלו כל חלקי הרע והפסולת למטה שלא יוכלו לעלות כלל ונופלים בתחתית המדריגה למטה מטה כך צללו כעופרת במים<sup data-n=\"1928\">13</sup> כו' (וזהו שאמר תחלה וברוח אפיך נערמו מים שהוא העלאת מ\"ן דגלי הים בירור ראשון ונצבו כמו נד<sup data-n=\"1929\">14</sup> מפני ישראל בחי' או\"י ואח\"כ ונער פרעה כו' והוא מ\"ש נשפת ברוחך<sup data-n=\"1930\">15</sup> להמתיק הגבורות צללו כעופרת כו') וזהו שאמר כד ארי' ואריותא<sup data-n=\"1931\">16</sup> קיימי ווי למאן דעבר בינייהו דזווג דמ\"ד ומ\"ן דארי' ראיה<sup data-n=\"1932\">17</sup> דחכמה<sup data-n=\"1933\">18</sup> קו ימין<sup data-n=\"1934\">19</sup> דחסדים כו' מבררים בירור שני שאז דוקא הסיגים נופלים למטה וע\"כ יאבדו ויתפרדו כו' וד\"ל:\n<b>ולהבין</b> בתוס' ביאור טעם דגוזר י\"ס קודם והעביר ישראל כו' דלכאורה לפי טעם הנ\"ל עיקר בקיעת הים היה רק מפני משה וישראל כשעברו וכתיב ויט משה את ידו<sup data-n=\"1935\">20</sup> כו' אך מבואר למעלה<sup data-n=\"1936\">21</sup> בענין המאמר בכל מקום דאינון תלתא אינון ארבע כו' הענין מובן ע\"פ הידוע בענין ד' בתים דתפילין<sup data-n=\"1937\">22</sup> שמוח הדעת נחלק לחו\"ג ומהיכן בא כח המחלקו הוא מבחי' קוצא דשערי שמכה כו' והוא מה\"ג דע\"י וא\"א ששרשו בה\"ג דרוח קדים עזה שבקע הי\"ס כנ\"ל וביאור הענין הנה ידוע דמוח הדעת כולל חו\"ג<sup data-n=\"1938\">23</sup> וענין חו\"ג זה היינו מה שיש בשכל להטות כלפי זכות זהו בחי' חסד שבחו\"ב ומה שיש בשכל להטו' כלפי דין וחוב זהו בחי' גבורו' שבחו\"ב והדעת כוללם יחד שהרי יש בכח הדעת להטות לזכות או לחוב ע\"כ נקרא דעת נוטה<sup data-n=\"1939\">24</sup> שהוא המכריע לזכות או לחוב כמו ב\"ש אוסרים ששכלם מטה כלפי חוב וב\"ה מתירי'<sup data-n=\"1940\">25</sup> ששכלם מטה כלפי זכות וחסד וא\"כ הדעת אין זה מוח שלישי רק שכולל חו\"ג הללו ולמה נקרא מוח הדעת בשם בפני עצמו אלא צריך לומר דגם שהשכל עצמו יש בו לזכות ולחוב ואין כאן אלא ב' גם במוח הדעת הכוללם אבל בחי' הטיי' זו להטות כלפי א' מהן אם לזכות או לחוב זהו כח מיוחד בפ\"ע ששרשו בא מלמעלה מחו\"ג דחו\"ב בהכרח שהרי מאין יש כח בדעת זה להטות כלפי חסד ולא כלפי דין או להיפך זהו כקו המשקולת",[["1926","11","<b>ביאור המאמר באריכות</b>: ראה ביאוה\"ז בשלח מ, ד ואילך."],["1927","12","<b>כי אתה אבינו</b>: ישעי' סג, טז."],["1928","13","<b>צללו כעופרת במים</b>: בשלח טו, י."],["1929","14","<b>וברוח אפיך. . ונצבו כמו נד</b>: שם שם, ח."],["1930","15","<b>נשפת ברוחך</b>: התחלת הכתוב צללו."],["1931","16","<b>כד ארי' ואריותא</b>: ראה זהר ואתחנן ער, א."],["1932","17","<b>דארי' ראיה</b>: ראה ת\"ז ת\"ע (קכב, א). הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'ל."],["1933","18","<b>ראי' דחכמה</b>: ראה גם לעיל מג, ב ובהנסמן במ\"מ לשם."],["1934","19","<b>דחכמה קו ימין</b>: נסמן לקמן קכד, ב."],["1935","20","<b>ויט משה את ידו</b>: בשלח יד, כא."],["1936","21","<b>מבואר למעלה</b>: לעיל עג, א."],["1937","22","<b>ד' בתים דתפילין</b>: ראה סידור שער התפילין ז, סע\"א ואילך. מאמרי אדה\"א דברים ח\"ד ע' א'רמא. וש\"נ."],["1938","23","<b>דמוח הדעת כולל חו\"ג</b>: ראה גם לקמן קלא, ב ובהנסמן במ\"מ לשם."],["1939","24","<b>דעת נוטה</b>: ראה גם תו\"ח וירא קי, ג ואילך."],["1940","25","<b>ב\"ש אוסרים. . וב\"ה מתירי'</b>: פסחים נה, א במשנה. נסמן לקמן קכד, א."]]],[2800530168,"שמכריע לצד אחד הרי זה בא מכח העליון מב' המאזנים דימין ושמאל והוא קו האמצעי ששרשו בפנימית הכתר<sup data-n=\"1941\">1</sup> והיינו מבחי' הגבורות שבכתר שמשם בא הכח לחלק הדבר ולהפריד לבד להיות שגם שהבחנה זו בין חו\"ג לזכות ולחוב הכל קדם בשכל עצמו אבל הכל היה בהעלם ובהתכללות לא נודע עדיין הפסק דבר כו' אבל ע\"י הדעת הרי יוצא מן ההעלם לגלוי דבר מהיפוכו כמו בחי' החסדים שהיה כלול בשכל יצא מופרד לעצמו במהות בפ\"ע וכח הדין שהיה כלול בשכל בהעלם יצא מופרד בפ\"ע והכל ע\"י בחי' מוח הדעת דוקא שהוא כאשר יטה דעתו להטות לזכות יצא השכל של זכות בגלוי מופרד מהיפוכו אבל קודם שהטה לחסד בגלוי הרי היה כלול עם היפוכו כו' וא\"כ מי הכריח לעשות הטייה זאת לחלק ולהפריד דבר מדבר כו' אין זה רק מכח העליון והוא מבחי' ה\"ג שבח\"ס שנקרא כח המשכיל כל שכל אם לזכות או לחוב ששם גם בהעלם לא היו עדיין רק שמשם מקור מוצא שיבא מן ההעלם לגלוי בחו\"ב ע\"כ יכול להיות משם דוקא כח המחלק ומפריד להטות הטייה זו לזכות ע\"י מוח הדעת שמט' כלפי זכות או לחוב וד\"ל וזהו ענין ההא' מכח ה\"ג דע\"י שנקרא כאן בקי\"ס רוח קדים עזה לחלק במוח הדעת לחו\"ג בגלוי והוא ענין בירור השני הנ\"ל בעה\"ד טו\"ר להפריד ולהבדיל בין טמא לטהור שהטמא טמא יקרא ויפול למטה כמו ההטייה לדין בגלוי שמשם שרש היניק' לרע והטהור שמקו החסדים יתגלה למהות בפ\"ע וזהו ע\"י בחי' המתקת הגבורות דים בחסד דאו\"י שצריך הי' שיבוא הכח והעוז לבירור זה שיפלו הפסולת למטה מבחי' רוח קדים עזה דוקא כדי שיהיה בכח ישראל לעבור בים ויבדלו הגבורות קשות ויפלו למטה וזהו שאמר לגוזר תחלה והוא מבחי' ה\"ג דרוח קדים כו' ואח\"כ והעביר כו' והיינו שאמר כד אינון ג' שהן חב\"ד אינון ד' שהדעת נחלק לב' חו\"ג בגילוי כמו ענין ד' בתים כו' וזהו ענין קי\"ס שהיה לי\"ב גזרים דוקא מפני שי\"ב שבטים נחלקו ממוח הדעת שנחלק לחו\"ג ונעשה ד' והן ד' דגלים<sup data-n=\"1942\">2</sup> כמ\"ש בזוהר וד\"ל:\n(נב) <b>ומעתה</b> יש להבין<sup data-n=\"1943\">3</sup> ענין הפך ים ליבשה<sup data-n=\"1944\">4</sup> בנהר יעברו ברגל דהפך לשון עבר קאי על יצ\"מ וכתיב כימי צאתך מא\"מ אראנו נפלאות היינו מ\"ש בנהר יעברו ברגל לשון עתיד כידוע ושם דוקא נשמח' בו ואעפ\"כ אמר למען תזכור יום צאתך מא\"מ כל ימי חייך אפילו לימהמ\"ש<sup data-n=\"1945\">5</sup> כו' דהנה מ\"ש לגוזר י\"ס לגזרים היינו לי\"ב גזרים<sup data-n=\"1946\">6</sup> נגד כל שבט גזר ביחוד לעבור בו כו'. ויש להבין למה צריך גזר וקרע לכל שבט ושבט בפ\"ע דוק' ועוד יש להבין למה בנהר שיעברו ברגל לעתיד כתיב והניף ידו על הנהר<sup data-n=\"1947\">7</sup> והכהו לז' נחלים בלבד ולא לי\"ב גזרים הרי אמר כימי צאתך מא\"מ אראנו משמע בדוגמא זו ממש א\"כ או שהיה צריך להיות גם לעתיד לי\"ב גזרים כמו ביצ\"מ או שגם בקי\"ס הי' די בקריעה לז' ולא לי\"ב כו' אך הנה לעתיד כתיב (בישעי' יא) והיה ביום ההוא<sup data-n=\"1948\">8</sup> יוסיף ה' שנית ידו לקנות את שאר עמו אשר ישאר מאשור וממצרים כו' ונשא נס לגוים<sup data-n=\"1949\">9</sup> ואסף נדחי ישראל כו' מד' כנפות הארץ כו' והחרים<sup data-n=\"1950\">10</sup>",[["1941","1","<b>קו האמצעי. . הכתר</b>: נסמן לקמן קכה, א."],["1942","2","<b>שי\"ב שבטים. . ד' דגלים</b>: ראה לעיל עג, א ובהנסמן במ\"מ לשם."],["1943","3","<b>ומעתה יש להבין</b>: להבא להלן (פנ\"ב-ס\"א) ראה הנסמן לעיל בריש הדרוש (ח, ב)."],["1944","4","<b>הפך ים ליבשה</b>: תהלים סו, ו."],["1945","5","<b>כימי צאתך מא\"מ. . למען תזכור. . לימהמ\"ש</b>: מיכה ז, טו. . נסמן לעיל ב, ב."],["1946","6","<b>לגוזר. . לי\"ב גזרים</b>: תהלים קלו, יג. נסמן לעיל סח, ב."],["1947","7","<b>והניף ידו על הנהר</b>: ישעי' יא, טו [בדילוג]."],["1948","8","<b>והי' ביום ההוא</b>: ישעי' שם, יא."],["1949","9","<b>ונשא נס לגוים</b>: ישעי' שם, יב."],["1950","10","<b>והחרים</b>: שם שם, טו."]]],[2800530169,"ה' את לשון ים מצרים והניף ידו על הנהר בעיים רוחו והכהו לז' נחלים והדריך בנעלי' והיתה מסילה לשאר עמו אשר ישאר מאשור כאשר היתה לישראל ביום עלותו מא\"מ<sup data-n=\"1951\">11</sup> ע\"כ והנה משמע מכל אלה הפסוקים שלעתיד יהי' קיבוץ גליות מד' כנפות הארץ ויקבצו כולם יחד בימות המשיח ותחלת עברם יהיה דרך אותו הנהר הידוע והוא נהר שיוצא מעדן הארץ להשקות הגן כו' והיינו נהר פרת וכמ\"ש ונהר יוצא מעדן כו' ומשם יפרד והיה לד' ראשים שם האחד פישון<sup data-n=\"1952\">12</sup> כו' ושם הנהר השני<sup data-n=\"1953\">13</sup> גיחון כו' עד והנהר הרביעי הוא פרת<sup data-n=\"1954\">14</sup> ודקדקו רז\"ל על תיבת הוא פרת וגם למה לא אמר ושם הנהר הרביעי אלא סתם וכתב ונהר הרביעי כו' דהוא זה היינו הנהר הראשון שיוצא מעדן והוא שאמרו הוא פרת הוא דמעיקרא<sup data-n=\"1955\">15</sup> דהיינו הנהר שיוצא מעדן שממנו נחלקו לד' נהרות וכמ\"ש ומשם יפרד והי' לד' כו' והנה נהר פרת זה שהוא הנהר הראשון שיוצא מעדן כו' בו יעברו ברגל לעתיד כמ\"ש הפך ים כו' בנהר יעברו ברגל בנהר פרת שהוא הנהר דמעיקרא שיבקע לעתיד כמ\"ש והניף ידו על הנהר והכהו לז' נחלים כו' ועל ענין העברת נדחי ישראל לע\"ל בנהר זה דוקא אמר שם נשמחה בו שם דוקא וכמ\"ש כימי כו' אראנו נפלאות וזה סותר לכאורה מ\"ש ז\"ל דמזכירין יצ\"מ לע\"ל דהרי אמרו שם דוקא נשמחה בו וכמ\"ש ולא יאמר עוד<sup data-n=\"1956\">16</sup> חי ה' אשר כו' (ואולי אין הכוונה על קי\"ס אלא על יציאת מצרים דוקא שהרי אמ' כל ימי חייך ג\"כ אפי' לעוה\"ב ומ\"ש שם נשמחה בו היינו בעברם בנהר דקי\"ס לא יזכר אז ואין פשט הכתוב דכימי צאתך כו' משמע כן ועוד שהרי אמ' כאן על העברת הנהר לע\"ל והיתה מסילה כו' כאשר היתה לישראל ביום עלותו מא\"מ דמשמע דלשבח קאמ' שיהי' כמו בעלותו מא\"מ ומ\"ש שם נשמחה בו משמע ששם דוקא נשמח וקי\"ס יהי' אז טפל בלבד וד\"ל) והנה להבין כ\"ז יש להקדים תחילה בשרש הטעם במה שהעביר ישראל בי\"ס ע\"י קריעה דוקא שילכו תוך הים ביבשה לאיזה טעם הי' דאם מטעם שלא רצה לנחם העם דרך ארץ פלשתי' כי קרוב הוא כו' ע\"כ הסב את העם דרך המדבר י\"ס<sup data-n=\"1957\">17</sup> הרי כמה דרכים היו לפניו להעבירם ולמה דרך י\"ס דוקא ולמה צוה שיחנו על הים<sup data-n=\"1958\">18</sup> דוקא ויחזק לב פרעה וירדוף אחריהם בים דוקא ואם כדי לטבוע למצרים<sup data-n=\"1959\">19</sup> בים אחר שיעברו ישראל בו ביבשה הלא הוא ית' כל יכול ויש לפניו כמה דרכים לאבדם ולהמיתם כולם בדבר ובכל מכה כמו שעשה במצרים ולמה היה חפץ ה' שיטבעו מצרים בי\"ס דוקא ושיעברו ישראל בים בשביל זה כדי שיטבעו מצרים דלכאורה לא היה צריך לזה כו' אך הענין הפשוט מורה האמת שלא בשביל טביעת מצרים בים העבירם לישראל עמו בים כי זה היה ממילא דרך אגב שכאשר הוצרך להעביר לישראל בתוך הים ביבשה מטעם הכמוס עמדו היה זה ממילא שרדפו מצרים אחריהם בים ונטבעו ולא בשביל טביעת מצרים העבירם בים אלא רק בשביל תועלת וטובה גדולה לנשמות ישראל מצד עצמם הוצרך להעבירם בי\"ס תחילה והיינו כדי שיהיה עי\"ז הכנה טובה וגדולה בנפשם האלקית לקבלת התורה<sup data-n=\"1960\">20</sup> בהר סיני פב\"פ ואם לא היו עוברים בי\"ס ביבשה דוקא לא היו מוכנים להיות בית קיבול לקבל אור התורה בקירוב גדול שיוקבע בהם לדורות כמ\"ש לא את<sup data-n=\"1961\">21</sup>",[["1951","11","<b>והיתה מסילה. . מא\"מ</b>: ישעי' יא, טז."],["1952","12","<b>ונהר יוצא. . שם האחד פישון</b>: בראשית ב, י. יא."],["1953","13","<b>ושם הנהר השני</b>: שם ב, יג."],["1954","14","<b>והנהר הרביעי הוא פרת</b>: בראשית שם, יד."],["1955","15","<b>רז\"ל. . הוא דמעיקרא</b>: בכורות נה, ב."],["1956","16","<b>ולא יאמר עוד</b>: ירמי' טז, יד."],["1957","17","<b>שלא רצה לנחם. . המדבר י\"ס</b>: בשלח יג, יז. יח."],["1958","18","<b>צוה שיחנו על הים</b>: שם יד, ב ואילך."],["1959","19","<b>כדי לטבוע למצרים</b>: ראה גם לעיל לב, ב."],["1960","20","<b>בי\"ס. . לקבלת התורה</b>: נסמן לעיל שם."],["1961","21","<b>לא את אבותינו</b>: ואתחנן ה, ג."]]],[2800530170,"אבותינו כו' וזה דבר פלא גדול שמה שייכות יש לקי\"ס עם מ\"ת שיהיה קי\"ס הכנה גדולה לקבלת התורה כו' והנה יש להקדים תחלה בשרש ענין הים מהו ובעיקר ענין קי\"ס שיש בזה מחלוקת לפי הנראה בזהר ובכתבי האריז\"ל<sup data-n=\"1962\">1</sup> ובאמת שניהם עולין למכוון א' כמשי\"ת ב\"ה דהנה ידוע מאמר הזהר ע\"פ זה הים גדול כו' שם אניות יהלכון<sup data-n=\"1963\">2</sup> כו' דכמו דאית ימא לתתא אית ימא לעילא ושם ג\"כ אניות יהלכון כו' ארבין דסלקין ונחתין כו' ויובן כל זה ע\"פ הקדמה פשוטה בהפר' שבין ים ליבשה דהנה ארז\"ל כל מה שיש בים<sup data-n=\"1964\">3</sup> יש ביבשה כו' דהיינו כל מיני ברואים שיש במציאות חי באופן א' נמצאו בים וביבשה וכן כל מיני צומח ודומם כו' וזה פלא דודאי ברואים שבים משונים מברואים שביבשה אלא הכונה שכדוגמא זו שיש ברואים רבים במינים שונים כך נמצאו ממש בים רק שחיותם נבדל בהיפך גמור זה מזה דהיינו מה שהבריות שבים לא יוכלו לחיות ביבשה כלל דמיד שיעלו ליבשה אפי' שעה אחת<sup data-n=\"1965\">4</sup> ימותו וכן הבריות שביבשה א\"א שיוכלו לחיות בים אפי' שעה אחת מפני שנחנקים ממי הים מיד כי א\"א לבריות שביבשה<sup data-n=\"1966\">5</sup> לחיות בלא אויר הארץ אפי' שעה אחת וכמו\"כ הבריות שבים עיקר חיותם מן מי הים וא\"א להם להתקיים אפי' שעה ביבשה כי נחנקים מאויר הארץ כו' כידוע וזה דבר פלא גדול לכאור' מאחר שהן מין ברואים באופן א'<sup data-n=\"1967\">6</sup> בים וביבשה כמאמר כל מה כו' למה הובדל ונשתנה אופן חיותם כ\"כ מן הקצה לקצה דמה שזה יחיה הוא ממית לזולתו ומה שממית לזה יחיה לזה כו' כנ\"ל (ואם מצד חלוקי המאמרות דמאמר תוצא הארץ נפש חיה ע\"כ חיותם מאויר הארץ דוקא ומאמר ישרצו המים<sup data-n=\"1968\">7</sup> שרץ נפש חיה כו' ע\"כ חיותם מן המים דוקא דמאמר ישרצו המים ביום ה' ומאמר תוצא הארץ ביום ו' אך זה גופא יש להבין איך נחלקו הברואים שבים מברואים שביבשה כ\"כ מן ההיפך להיפך ע\"י מאמר לכל אחד בפ\"ע כו') אך הענין הוא דהים עצמו הוא העושה חק וגבול להבדיל ולהפרי' בין בריות שבים לבריות שביבשה והוא במה שהים מכסה על כל הברואים שבו שמובלעים בו באופן שיחיו רק ממי הים ולא יוכלו לחיות כלל מאויר הארץ ושם ה' חוק וגבול לים<sup data-n=\"1969\">8</sup> שנעשה כמו דבר מגביל שלא יעבור ביבשה והוא מה שמגביל שלא יוכלו הבריות שביבשה לחיות ממי הים אפי' רגע ונמצא הגבול הזה שמגביל הוא להבדיל בין בריות שבים לבריות שביבשה שלא יוכלו הבריות שבים לעלות ליבשה ולא יוכלו בריות שביבשה לירד לים אבל אם חסר א' משתי אלה היינו שהיה הים עובר גבולו הי' גם בריות שביבשה לחיות מן הים או שלא היה הים מכסה על הברואים שבו היה גם ברואים שבים לחיות ביבשה אבל מצד שתי אלה שהים מכסה ומעלים ומבדיל על הבריות שבים ושם חוק וגבול לים שלא יעבור ביבשה עי\"ז נבדל החיות לבריות שבים מחיות אויר היבשה לבריות שבה עד שא\"א להיות בהם חיבור ושיתוף כלל ונעשין ב' הפכים מן הקצה לקצה (והעיקר הוא מטעם שהים מכסה על הברואים שמובלעים בו שממילא נבדלו מבריות שביבשה בתכלית כו') והנמשל מהקדמה זו שבים ויבשה למטה יובן ג\"כ למעל' בבחי' ים ויבש' העליו' דכתי' יקוו המי'<sup data-n=\"1970\">9</sup> כו' ותראה היבש' וידוע בזהר דים<sup data-n=\"1971\">10</sup>",[["1962","1","<b>קי\"ס. . בזהר ובכתבי האריז\"ל</b>: ראה לקמן פו, א ואילך. הנסמן לעיל עא, ב."],["1963","2","<b>זה הים. . שם אניות יהלכון</b>: תהלים קד, כה. כו. ראה זהר בשלח מח, ב."],["1964","3","<b>כל מה שיש בים</b>: ראה חולין קכז, א. ירושלמי שבת פי\"ד, ה\"א."],["1965","4","<b>שהבריות שבים. . דמיד. . שעה אחת</b>: ראה חולין שם. ביאוה\"ז בשלח מב, סע\"ג. סה\"מ תקס\"ג ח\"א ע' קנד (נוסח א'). תו\"א בשלח סב, ב. תו\"ח תולדות קנח, ב. לקו\"ש (ימי הקיץ) כרך ח ע' 363 בשולי הגליון להערה 1."],["1966","5","<b>א\"א לבריות שביבשה</b>: ראה חולין שם. ביאוה\"ז שם מא, ד. מב, ג. תו\"ח שם. לקו\"ש (אלול) כרך י\"ט ע' 161 הערה 31."],["1967","6","<b>מין ברואים באופן א'</b>: ראה אוה\"ת (יהל אור) תהלים ע' תד."],["1968","7","<b>תוצא הארץ. . ישרצו המים</b>: בראשית א, כד. כ."],["1969","8","<b>חוק וגבול לים</b>: ירמי' ה, כב. ב\"ב עג, א."],["1970","9","<b>יקוו המי'</b>: בראשית א, ט."],["1971","10","<b>דים. . עלמא דאתכסייא והיבשה. . דאתגלייא</b>: נסמן לעיל לב, ב."]]],[2800530171,"העליון נק' עלמא דאתכסייא והיבשה עליונה נק' עלמא דאתגלייא וז\"ש ברוך ה' מן העולם ועד העולם<sup data-n=\"1972\">11</sup> כידוע והענין הוא ע\"ד הנ\"ל בהבדל שבין בריות שבים לבריו' שביבש' שהים הוא המבדיל כו' כך הוא למע' בימא עילאה שנק' י\"ס סופא דכל דרגין דאצי' והו' בחי' מל' דאצי' והוא העוש' מסך מבדיל ומפסיק בין אור אצי' לבריא' שנק' יבשה עלמא דאתגלייא שהן הברואי' שנבראו מאין ליש מארץ עילאה כמ\"ש תוצא הארץ תדשא הארץ<sup data-n=\"1973\">12</sup> כו' כידוע עד אשר לא יוכלו נשמות ומלאכים דאצי'<sup data-n=\"1974\">13</sup> לעבור ביבשה שהוא עולם הבריאה וכל אור מאורות עליונים דאצי' לא יוכלו לעבור מאצי' לבריאה לפי ששם חוק וגבול לים העליון להיותו מכסה על כל הבריות שבו כנ\"ל בים הגשמי שלמטה וכך לא יוכלו נשמות ומלאכים דבריאה וכל אור ומדרגה לעלו' מבריא' לאצי' כמו שלא יוכלו בריות שביבשה לחיות בים כנ\"ל ע\"ד הנ\"ל בים ויבשה שלמט' מטעם ב' סיבו' בים המגביל ומבדיל בתכלי' כנ\"ל וד\"ל:\n(נג) <b>ולהבין</b> זה יש להקדים תחלה ביאור ענין ים ויבשה העליונים מהו דהנה הגם שמבואר בכמה מקומות בענין ים ויבשה למעל' שזהו כמו משל מחשבה ודבור<sup data-n=\"1975\">14</sup> למט' שנק' מא' סתום ומא' פתוח<sup data-n=\"1976\">15</sup> שהמחשב' סתומה היא והדבור בא בגילוי לזולתו וע\"כ נק' מאמר פתוח וגם המחשבה שבדיבור לא נודע לזולתו אך הנה באמת גם בבחי' הדבור עצמו יש ב' מדרגות דסתים וגליא שנק' ים ויבשה דהנה ידוע שבחי' המל' נק' דיבור<sup data-n=\"1977\">16</sup> והן י' מאמרות כמ\"ש בדבר ה' שמים נעשו<sup data-n=\"1978\">17</sup> וברוח פיו כו' כמו ויאמר אלקים יהי אור יהי רקיע<sup data-n=\"1979\">18</sup> הרי מגופו של דיבור זה יהי אור נעשה ונתהווה המציאות של האור וכן ממאמר יהי רקיע נתהווה הרקיע מאין ליש וכן בדבר ה' ורוח פיו נתהוו כל הברואים מאין ליש שזהו הנק' עלמא דאתגלייא כידוע וא\"כ יפלא האיך נק' בחי' הדיבור עצמו בשם ים שהוא סופא דכל דרגין דאצי' שהוא בחי' ההעלם שבלתי בא בגילוי כלל וכלל שהרי נק' עלמא דאתכסייא או מאמר סתום כמו המחשבה שהיא בהעלם וסתימות בלי גילוי כלל כו' אך הענין הוא שבאמת גופו של הדיבור עצמו נק' ים המכסה על כל מה שבתוכו בלתי נגלה כלל אעפ\"י שמן הדיבור בא הכל בגילוי לזולתו ולכאורה האיך ימצאו ב' הפכים בנושא א' אמנם הנה אנו רואי' דכל אשר בא בגילוי מן אותיות הדיבור לזולתו השומע אין זה מהות ועצמו' הדבר כמו שהוא ממש רק בחי' גילוי האר' הדבר הבא בדרך הפסק בהבל הפה כו' כמו הרצון והתענוג שבא ונמשך באותיות הדבור הרי מהות ועצמות כמו שהוא ממש לאמיתתו נשאר מכוסה ונעלם ממש בתוך אותיות הדבור ולא נודע ונגלה מהותו כלל לשומע הדבור וכן דברי שכל וחכמה שאומר בדבור הרי אמיתית מהות ועצמות השכל כמו שהוא לא נודע כלל לשומע הדבר שכל ההוא (וראי' ממה דלא קאים איניש<sup data-n=\"1980\">19</sup> אדעתי' דרביה עד מ' שנין אע\"פ שהבין והשיג בכי טוב ע\"י הדבור לפי שמוה\"ע<sup data-n=\"1981\">20</sup> השכל לא השיג כלל) וכן דברי חסד ואהבה או להיפך דברי כעס ודין לא נודע אמיתית מהותן כמו שהן לשומע כי מכוסה ונעלם לגמרי בדבור עצמו כו' והטעם הוא כי הנה השומע אותיות הדבור אינו שומע רק אותיות",[["1972","11","<b>ברוך. . ועד העולם</b>: תהלים קו, מח? דהי\"א טז, לו [בדילוג]. ראה מאמרי אדה\"א דברים ח\"א ע' קכד. וש\"נ. הנחות תקע\"ז ע' נה. וש\"נ. שע\"ת צא, ג. לעיל לב, ב."],["1973","12","<b>תדשא הארץ</b>: בראשית א, יא."],["1974","13","<b>ומלאכים דאצי'</b>: ראה גם להלן פה, א. פו, ב. שע\"ת צב, ג ובהנסמן במ\"מ לשם."],["1975","14","<b>ים ויבשה. . מחשבה ודבור</b>: ראה גם סה\"מ תקס\"ז ע' רעג."],["1976","15","<b>מא' סתום ומא' פתוח</b>: ראה גם לקמן קלט, א ובהנסמן במ\"מ לשם."],["1977","16","<b>המל' נק' דיבור</b>: ראה זהר לך פו, ב. מאמרי אדה\"א דברים ח\"ב ע' שפב. וש\"נ."],["1978","17","<b>בדבר ה' שמים נעשו</b>: תהלים לג, ו."],["1979","18","<b>ויאמר אלקים יהי אור יהי רקיע</b>: בראשית א, ג. ו."],["1980","19","<b>דלא קאים איניש</b>: נסמן לקמן צב, ב."],["1981","20","<b>שמוה\"ע</b>: נסמן לעיל ב, א."]]],[2800530172,"שנחקקים בהבל הפה היוצא לחוץ שהוא הבל גשמי מורכב מאמ\"ר גשמי ונק' בחי' דומם כערך אות גולמי המצוייר בקלף שאע\"פ שמבין ומשיג הרצון או השכל מתוך אותיות אלה כשאומר יהי כך וכך אין זה השג' מהו' רצונו זה כמו שהוא נמשך מן הנפש בעצם כלי הדבור בה' מוצאות שנק' רוח ממללא<sup data-n=\"1982\">1</sup> שנחשב מן העצם ממש רק הוא בא דרך הפסק גדול בשינוי המהו' לגמרי לפי שאותיו' הדבור הרוחניים שבה' מוצאות המה המכסים ומסתירים על מהות ועצם הרצון ושכל ומדות שבהם כמו שהים מכסה על הברואים שבו כנ\"ל (ואע\"פ שאנו רואים בדברים שיוצאים מן הלב שנכנסים ללב<sup data-n=\"1983\">2</sup> שומע ועוש' רוש' בלבו שמתפעל כמו שהאהבה בלב המדבר כמו ראוה מדברת<sup data-n=\"1984\">3</sup> כו' הרי התענוג הפנימי שבלב נגל' בהבל הדבו' כו' וכמו\"כ בשכל אנו רואים שימצא תוס' ורבוי אור השכל בדבור דוקא וכה\"ג גם ברצון ותענוג כו' היינו לפרקים כשנפתח הסתום שבדבור ע\"י בקיעת הבל הלב בה' מוצאות ולמעלה היינו בחי' בקיעת המסך כו') ונמצא מובן דשניהם אמת ואינם ב' הפכים כלל דמהו\"ע הרצון ותענוג ושכל ומדות שבדבור מכוסי' ונעלמים בעצם הדבור ולא נגלה מהותן כלל אך מה שמתגלה לשומע אינו רק אחר הפסק בשינוי המהות כמו ע\"י מסך (שנק' הארה דהארה וזהו וברוח פיו כל צבאם רוח הבל הפה הנפרד שהוא מ\"ש אתוון אתגליפו<sup data-n=\"1985\">4</sup> כאותיו' הנחקקי' בדבר זר כו' והן אותיות שנבראו בהן שמים וארץ וכל צבאם שנק' יבשה עלמא דאתגליא אבל מהות האורות עליונים דאצילות כח\"ב ומדות הכל מכוסים ונעלמים בדבור העליון כי הדבור העליון מכסה עליהם ע\"כ נק' בשם ים העליון וד\"ל) ולפ\"ז הרי מובן שא\"א שיהי' השגה לנבראי' כמלאכי' שנתהוו מרוח פיו ית' במהות האורות עליונים דע\"ס דאצילות הגנוזים ונעלמי' בגופו של הדבור העליון מאחר שכל עיקר ומקור התהוותם אינו רק מבחי' הבל חיצוני היוצא נפרד לחוץ ואם יעלו ויבאו למעלה באותיות הדבור העליון עצמם יתבטלו שם ממציאותם כבריו' דיבשה שאין להם קיום בים כנ\"ל וד\"ל וכמו\"כ לא יוכלו נשמות ומלאכים דאצילות המכוסים ונעלמים בים העליון ונק' נוני ימא רבא<sup data-n=\"1986\">5</sup> לירד ביבשה שהוא הבל הדבור המתפשט למטה כמו שבריו' שבים לא יוכלו לעלות ליבשה כנ\"ל (ומ\"ש בזהר ע\"פ וידגו לרוב בקרב הארץ<sup data-n=\"1987\">6</sup> שהן נוני ימא רבא נשמות דאצי' ממש כנשמת רה\"מ סבא<sup data-n=\"1988\">7</sup> ובניו דאזלין ביבשתא בעלמא דאתגליא להתגלות בנשמות הצדיקים שבגופים בעה\"ז היינו רבותא גדולה מה שיוכל להיות התגלות מעלמא דאתכסיא לעלמא דאתגליא שנפתח הסתום והוא מצד עוצם מעלת מדרגות הנשמות דאצי' שלא ימנעו לבא ולהתגלות בעוה\"ז ג\"כ וגדולה מזו מצינו בענין האותות ומופתי' ובמראה הנבואה לנביאי' בעה\"ז וגילוי שכינה בהיכל ק\"ק וכה\"ג שכל זה הרי הוא בחי' גלוי מאצי' ממש לבי\"ע וזהו עיקר ענין קי\"ס כמשי\"ת ב\"ה) וכל זה מפני שבחי' דבור העליון נק' ים המכסה ומעלים על כל מה שבתוכו כנ\"ל שנעשה כמו מסך מעלים ומבדיל בין אצי' לבי\"ע עד שא\"א שיעלה מבריאה לאצי' ולא ירד מאצי'",[["1982","1","<b>רוח ממללא</b>: ת\"א לבראשית ב, ז."],["1983","2","<b>בדברים. . שנכנסים ללב</b>: ספר הישר לר\"ת שער י\"ג. הובא בשל\"ה שער האותיות אות כ (סט, א). שירת ישראל לר' משה בן עזרא (ירושלים תשכ\"ז ע' קנו)."],["1984","3","<b>ראוה מדברת</b>: ראה כתובות יג, א (במשנה). מאמרי אדה\"א נ\"ך ע' תפ? קונטרסים ע' רצה ובהנסמן בהנ\"ל."],["1985","4","<b>אותוון אתגליפו</b>: ראה גם לקמן קמא, ב ובהנסמן במ\"מ לשם."],["1986","5","<b>נוני ימא רבא</b>: זהר בלק קפח, א."],["1987","6","<b>וידגו לרוב בקרב הארץ</b>: ויחי מח, טז. ראה זהר בלק קפז, ב וביאוה\"ז לשם (קמט, א). הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'כד."],["1988","7","<b>רה\"מ סבא</b>: ראה זהר בהקדמה ו, א. מאמרי אדה\"א בראשית ע' קנא. וש\"נ. שע\"ת מה, א ובהנסמן במ\"מ לשם."]]],[2800530173,"לבריאה כנ\"ל וד\"ל וזהו מ\"ש בזהר על מ\"ש זה הים גדול כו' דאניות יהלכון שם היינו ארבין דסלקין ונחתין כו' דהנה עד\"מ הנ\"ל בברואים שבים למטה שהמים מכסים עליהם הרי הם מובלעים בתוך הים כדגים שבים שהמים הם חיות עצמי להם יותר מחיות האויר לבריות שביבשה שבריות היבשה יש להם חיות נפשי רק שמקבלים מן האויר ויוכלו להתקיים זמן מה בלא אויר הארץ אבל דגים שבים א\"א להם להתקיים ביבשה בלי מים אפי' רגע לפי שהמים מובלע בהם בחיות עצמי וע\"כ מובלעים הן בתוך הים כו' וכך הוא ההפרש בין נשמות דאצילות שבמל' דאצילות שנק' ים העליון כנ\"ל כמו נשמות רהמ\"ס ורשב\"י<sup data-n=\"1989\">8</sup> וכה\"ג שנק' נוני ימא רבא שמתאחדים ומתכללים שם בביטול לאין האלקי בחיות עצמי ממש שלא יוכלו להפרד משם אפי' רגע א' ממש וכמ\"ש רשב\"י בחד קטירא אתקטרנא בי' אחידא בי' להיטא<sup data-n=\"1990\">9</sup> כו' וכמו שאמרו על ת\"ח שנמשלו לדגים<sup data-n=\"1991\">10</sup> שבים שמיד שפורשות ליבשה מתים והיינו לפי שת\"ח חיותם העצמי בחכמ' שבתורה ומיד שיפרשו משם ימותו וכך בפנימית ח\"ע משא\"כ בחי' ביטול והתכללו' דנשמו' ומלאכי' דבריאה יש מאין מהבל הדבור העליון שנק' בשם יבשה שזהו כחיו' הבע\"ח מאויר הארץ כך מקבלים מהבל רוח פיו יתב' כמ\"ש וברוח פיו כל צבאם כנ\"ל דודאי אין להם קיום המציאות רק מרוח הדבור העליון אבל<sup data-n=\"1992\">11</sup> עכ\"ז הן במציאות יש ודבר בפ\"ע רק שהן בבחי' ביטול ישותו ע\"י השגתו בכח אלקי שבהבל דבור העליון המהווה אותו מאין ליש כו' ואין זה ערך כלל לבחי' ביטול והתכללות העצמי' שבנשמות דאצילות במל' דאצי' בחיות עצמי שאינם יש במציאות בפ\"ע כלל אפי' רגע כדגים בים (וכעובר ירך אמו<sup data-n=\"1993\">12</sup> או כל מה שאמו אוכלת<sup data-n=\"1994\">13</sup> או בבחי' מ\"ן<sup data-n=\"1995\">14</sup> כו') אך הנה מ\"מ יוכל להיות חיבור לנשמו' דבריאה באצי' והוא ע\"י המלאכים שנקראו ארבין<sup data-n=\"1996\">15</sup> כמו הספינה שהיא מעצים שצומח מן הארץ ואין לה חיבור עם מי הים רק ששטה בים לפי שיש בהעצים מיסוד הרוח<sup data-n=\"1997\">16</sup> כידוע ובנ\"א שחיות' מאויר הארץ יעברו בים ולא ישקעו שם ע\"י שהולכי' בספינות שמפסיקים עליהם שלא ישטפוהו עליהם מי הים כידוע והנמשל יובן למעלה בנשמות בנ\"א שגם למעלה הן בבחי' יש ודבר ולא יוכלו לילך בים העליון שלא יתבטלו שם לגמרי רק על ידי המלאכים שנק' עצי היער<sup data-n=\"1998\">17</sup> דבריאה עושין מהם כמו ספינות לנשמו' דבריאה שיעברו בהם על הים העליון וזה סוד שם אניות יהלכון וכמו שכתוב חונה מלאך ה'<sup data-n=\"1999\">18</sup> סביב ליריאיו והן הנשמות כו' ודוגמא לזה הוא שאמר גבי גוהרקי דר\"ח רבה<sup data-n=\"2000\">19</sup> דמנפשי' אזל כו' כמו שאמר במ\"א כי מפני שעוש' מלאכיו רוחות<sup data-n=\"2001\">20</sup> זהו יסוד הרוח שבעץ הצומח ששט ע\"פ המים ע\"כ יוכלו לשוט על הים העליון משא\"כ הנשמות דבריאה שהיו מתבטלים בים העליון כי אין להם חומר מורכב מאמ\"ר רק צורה פשוט' ובחכמה שבדבור העליון נכללים ומתבטלים לגמרי רק ע\"י המלאכים שנק' ארבין סלקין ונחתין עולין ויורדין שם כמו בשבת וי\"ט שאז עליית הנשמות<sup data-n=\"2002\">21</sup> מבריאה לאצילות (ודוגמא לזה מלאכי אלקים שעולים ויורדים<sup data-n=\"2003\">22</sup> ע\"י התפלות שמעלים מבריאה",[["1989","8","<b>נשמות דאצילות. . ורשב\"י</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה כאן ע' רנו. מאמרי אדה\"א ויקרא ח\"א ריש ע' רנב. נ\"ך ע' קפז. תו\"ח תולדות קנח, ב."],["1990","9","<b>בחד קטירא. . להיטא</b>: ראה זהר (אד\"ז) האזינו רפח, א. רצב, א. לקמן צח, ב. מאמרי אדה\"א שמות ח\"ב ע' שכט. וש\"נ. תו\"ח לך צו, א ובהערה 3."],["1991","10","<b>ת\"ח שנמשלו לדגים</b>: כ\"ה בכ\"מ ? ראה ברכות סא, ב. ע\"ז ג, ב. מאמרי אדה\"ז על פרשיות התורה כאן ע' רנז. מאמרי אדה\"א דברים ח\"ג ע' א'כד. וש\"נ. תו\"ח תולדות קנח, ב."],["1992","11","<b>אבל</b>: ניתוסף ע\"פ דפו\"ר."],["1993","12","<b>וכעובר ירך אמו</b>: גיטין כג, ב."],["1994","13","<b>כל מה שאמו אוכלת</b>: נדה ל, ב."],["1995","14","<b>בבחי' מ\"ן</b>: ראה סה\"מ תקס\"ה ח\"א ס\"ע קיא ואילך (נוסחא שני'). ע' קיג (נוסח א'). תו\"א וישב כח, א."],["1996","15","<b>המלאכים שנקרא ארבין</b>: ראה זהר בראשית מ, ב. מאמרי אדה\"ז על פרשיות התורה כאן ע' רנז. ע' רסז. ע' רעז? מארז\"ל ע' כז [בפי' הזהר ? בשלח מח, ב ? כאן]."],["1997","16","<b>שיש בהעצים מיסוד הרוח</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה כאן ע' רנז."],["1998","17","<b>המלאכים שנק' עצי היער</b>: ראה גם מאמרי אדה\"ז אתהלך לאזניא ע' לח. תקס\"ה ח\"ב ע' תשפא. פרשיות התורה ח\"א ע' יט וכאן (ע' רנז). מאמרי אדה\"א דברים ח\"ג ע' א'קיד. וש\"נ."],["1999","18","<b>חונה מלאך ה'</b>: תהלים לד, ח. ראה מאמרי אדה\"א נ\"ך ע' שמח ובהנסמן בריש המאמר שם."],["2000","19","<b>גוהרקי דר\"ח רבה</b>: ראה ב\"מ פה, ב. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שעט. מאמרי אדה\"א נ\"ך ע' תעח ובהנסמן בהנ\"ל."],["2001","20","<b>שעוש' מלאכיו רוחות</b>: תהלים קד, ד."],["2002","21","<b>בשבת. . הנשמות</b>: ראה בהנסמן לעיל לד, א."],["2003","22","<b>מלאכי אלקים שעולים ויורדים</b>: ויצא כח, יב. ראה סידור שער החנוכה רעג, ג. מאמרי אדה\"א שמות ח\"א ע' רמז."]]],[2800530174,"לאצילות וממשיכים מאצי' לבריאה וכן כל הנסים שנעשו ע\"י המלאכים וכה\"ג) וכמו\"כ יובן שיוכל להיות חיבור מאצילות לבריאה שנשמות דאצילות ירדו למטה בבי\"ע ג\"כ באופן שיתקיימו במציאות חיותם העצמי והוא מבחי' מים עליונים דחכמה שבתורה שמובלעים בהם כמו ת\"ח שלומדים תורה הנגלית לנו שאמר שנק' דגים שבים הרי גם בנשמות שבגופים בעוה\"ז יחיו כמו נשמות דאצי' בים העליון ממי החכמ' דתורה שנק' ים הקדמוני<sup data-n=\"2004\">1</sup> וכידוע בפי' ותמלא כדה ותעל<sup data-n=\"2005\">2</sup> כ\"ד ספרים דאורייתא כו' וע\"כ כל העוסק בתורה<sup data-n=\"2006\">3</sup> שכינה שבאצילות שורה בו וכמ\"ש ואשי' דברי בפיך<sup data-n=\"2007\">4</sup> דברי ממש כו' וע\"כ גם בעלמ' דאתגלי' יוכלו להיות נשמות דאצילו' ע\"י התלבשות' במי' דאורייתא בנגל' ובנסת' שזהו חיות' העצמי כמו גם בדגים שבים שישוטו בתיב' מלאה מים חיים יחיו ויתקיימו בארץ זמן רב כמו שיחיו בים ממש כך הנשמו' דאצי' בהיותם בכ\"ד ספרים דאורייתא יחיו חיים עצמיים כמו בים העליון כו' וזהו שאמ' וידגו לרוב בקרב הארץ דאזלי' נוני ימא רבא ביבשת' היינו בשעה שנשמות שבגופים עוסקי' בתורה דוקא ובפנימיות התורה דוקא כמובן שם וד\"ל:\n(נד) <b>ואחר</b> כל זה יובן שרש ענין קי\"ס דהנה כתיב ובנ\"י הלכו ביבשה<sup data-n=\"2008\">5</sup> בתוך הים מזה משמע שעיקר הנס הי' שנהפך ים ליבשה וכמ\"ש הפך ים ליבשה ולזה אמ' לרבותא שהלכו ביבשה בתוך הים לפי שזהו עיקר הרבותא שהים נהפך ליבשה ולמעלה היינו מה שההסתר וההעלם דאורות עליונים הגנוזים בדיבור העליון שנק' ים העליון נבקע ויצאו כל האורות דאצי' לבריא' בגילוי מן ההעל' כמו שהן במהותן ועצמותן בלי שום שינוי המהו' כלל וזה נק' קי\"ס העליון וכמו אור הרצון והשכל ומדות דאצילות שמכוסי' ונעלמים בדבור באו לגילוי בעולם הבריא' (וכמו י' הדברות שדיבר הוי' כו') (הרי שם הוי' דאצילות ירד מן ההעלם שבעצמות המאציל לגילוי בזה העולם דעשי' וזה נעשה ע\"י הכנה דקי\"ס שהי' גילוי ההעלם בים העליון וכמשי\"ת בסמוך בענין קבלת התורה בכנ\"י שהי' ע\"י קי\"ס כו') לפי שאין הדיבור העליון מכסה כלל על בחי' האורות עליונים דכח\"ב ומדות דאצילו' שבתוכו כו' (וה\"ז כמו שהיו בריות שבים יכולים לעלות ולירד ביבשה) וכה\"ג אנו מוצאים בגילוי שכינה בעוה\"ז בנביאים ובבהמ\"ק כנ\"ל (ואע\"פ שכבר הי' נסים ונפלאות במצרים בי' מכות אין זה גילוי אור האצילו' ממש בבי\"ע רק ע\"י כלים מכלים שונים והוא ע\"י שם הוי\"ה שבוקע ומאיר בשם אלקים עד מ\"ח צירופים האחרונים<sup data-n=\"2009\">6</sup> משא\"כ בקי\"ס וד\"ל) וזהו הטעם שבקי\"ס ראת' שפחה<sup data-n=\"2010\">7</sup> מה שלא ראה יחזקאל כו' מאחר שיצא האור דאצילות מן ההעלם לגלוי כמו שהוא בלי התלבשות וצמצומים הרי הכל יכולים לקבל גדול וקטן שוין ולא יפול בזה חילוק מדרגות כלל כי חילוק מדרגות בנבואה היינו לפי סדר ההשתלשלות דע\"ס דבי\"ע ישעי' ראה במרכבה דבריאה ויחזקאל במרכבה דיצי'<sup data-n=\"2011\">8</sup> שזהו אחר הבדלת המסך שבין אצילות לבריאה ומבריאה ליצי' כידוע אבל בקי\"ס שהי' האור דאצי' עצמו כמו שהוא בגילוי הרי שוין הכל ויכול' גם שפחה לראות כו' וזהו שראתה שפחה",[["2004","1","<b>דתורה שנק' ים הקדמוני</b>: ראה גם סה\"מ תקס\"ו ע' ערה. מאמרי אדה\"א דברים ח\"ד ע' א'תיח. וש\"נ. תו\"ח נח סב, ג ובהערה 23."],["2005","2","<b>ותמלא כדה ותעל</b>: ח\"ש כד, טז. ראה ת\"ז תכ\"א (מו, ב). ביאוה\"ז וישב כה, א. מאמרי אדה\"א דברים ח\"א ע' רכו. וש\"נ. שמות ח\"א ע' ק. וש\"נ. ח\"ב ע' שצו."],["2006","3","<b>כל העוסק בתורה</b>: ראה אבות פ\"ג מ\"ו. פי' המפרש לתמיד לב, ב. תניא פ\"ו. תניא מהדו\"ק ע' רסא הערה 48. אגה\"ק סכ\"ג ובליקוט פירושים לשם."],["2007","4","<b>ואשי' דברי בפיך</b>: ישעי' נא, טז."],["2008","5","<b>ובנ\"י הלכו ביבשה</b>: בשלח יד, כט."],["2009","6","<b>מ\"ח צירופים האחרונים</b>: ראה גם לקמן קמו, ב ובהנסמן במ\"מ לשם."],["2010","7","<b>ראת' שפחה</b>: מכילתא בשלח טו, ב."],["2011","8","<b>ישעי'. . דבריאה ויחזקאל במרכבה דיצי'</b>: נסמן לקמן קמה, ב."]]],[2800530175,"על הים מה שלא ראה יחזקאל כי היה מעצם אור אצי' בעשי' וכמ\"ש זה אלי<sup data-n=\"2012\">9</sup> לנוכח כידוע וד\"ל (וזהו דעת המקובלים בכתבי האריז\"ל<sup data-n=\"2013\">10</sup> וקורין שם לקי\"ס בלשון לידה כמו עיבור הולד במעי אמו ואח\"כ נפתח הסתום ויוצא הולד מהעלמו לגלוי אויר העולם כך ענין קי\"ס הוא בחי' לידת הנשמות מאצי' לבי\"ע שנשמו' דאצילות היו כלולים תחילה בבחי' עיבור במל' ונפתח ונקרע הרחם ויצאו לגלוי וז\"ש עד יעבור אותיות עיבור<sup data-n=\"2014\">11</sup> וכמו קול ה' יחולל אילו'<sup data-n=\"2015\">12</sup> וכמ\"ש בזוהר כהאי איילתא<sup data-n=\"2016\">13</sup> כו' כידוע) והנה יש עוד דעה ופי' בקי\"ס היפך זה והוא כפי המובן במאמרי הזוהר בענין קי\"ס שאמ' כד סליק ימא גלגלוהי<sup data-n=\"2017\">14</sup> כו' דמ\"ש ובנ\"י הלכו ביבשה בתוך הים עיקר הרבותא היא מה שבתוך הים הלכו ביבשה דהיינו שגם בהעלם דים העליון גם שם יכלו לילך ביבשה בבחי' גלוי שזהו שבהעלם עצמו הי' שם בחי' גלוי ולא שמן ההעלם יצא לגלוי והיינו כמו שבריות דיבשה יכולים לילך בים שזהו יותר פלא ממה שבריות דים יעלו וילכו ביבשה ובאמת הכל ענין א' אלא שזה הפי' בקי\"ס הוא בבחי' ההעלא' מלמטה למעל' דהיינו נשמות דבי\"ע שהן מעלמא דאתגלי' הלכו ביבשה בתוך הים העליון שעלו נשמו' דבריא' באצי' ולא נתבטלו במציאות שם כלל וזהו עיקר הרבותא שאמ' דבנ\"י נשמות דבריאה הלכו ביבשה כמו שהן בבחי' גלוי מאין ליש בתוך הים העליון דאצי' וזהו היפך פי' הראשון וד\"ל ולפ\"ז לא יתיישב לנכון מ\"ש הפך ים ליבשה דמשמע שעיקר הרבותא הוא שהים נהפך ליבשה שזהו בחי' ההעלם שיצא לגלוי וכן בעיקר קי\"ס שהיה ע\"י רוח קדים עזה כתיב ויבקעו המים<sup data-n=\"2018\">15</sup> כו' אמנם הענין הוא דבאמת אין נ\"מ כלל בגוף ענין קי\"ס בין ב' הפי' והדיעות הנ\"ל דודאי שניהם אמת דמאחר שנעשה חיבור וקשר לעליונים דאצי' עם התחתונים דבי\"ע ממילא יוכל להיות שניהם שמאצי' יוכל האור הנעלם בים העליון לבוא בגלוי למטה בבי\"ע וכן מבריאה יוכלו לעלו' באצי' אחר שאין מסך מבדיל ביניהם כלל וכלל כי בחי' אותיות הדבו' שהיו מכסים לאורות עליונים דאצי' הגנוזים בתוכם וממילא נעשה כיסוי והעלם זה עצמו לגבי התחתונים דבי\"ע כאשר לא יסתירו כלל אזי ממילא יש חיבור לאורות עליונים דאצי' עם אורות תחתונים דבי\"ע דע\"ס דאצי' ונשמות ומלאכים דאצי' יכולים לבא למטה בגלוי בבי\"ע וע\"ס דבי\"ע ונשמות ומלאכים שבהם יכולים לעלות למעלה באצי' שזהו כולל ירידת העליון למטה ועליית התחתון למעלה שאין נ\"מ בזה כלל לענין עצם יחודם וחיבור' עד\"מ ב' בנ\"א<sup data-n=\"2019\">16</sup> א' עומ' למעל' וא' עומ' למט' שיש ב' אופני' בחיבורם יחד או שהעליון יורד מלמעל' למט' או שהתחתון עול' למע' שאין נ\"מ בזה כלל רק במקו' ששם יהי' חיבורם אם למעל' או למטה אבל בענין עצם יחודם אין נ\"מ כלל וד\"ל. ונמצא שאין נ\"מ בין ב' הפי' הנ\"ל בגוף ענין קי\"ס דבין כך ובין כך הכל היה ע\"י קי\"ס רק שלפי פי' הראשון היה אופן ההתגלות בחיבור עליונים בתחתונים מלמעלה למטה ולפי פי' הב' היה אופן החיבור וההתגלות שלהם מלמטה למעלה אבל בגוף הענין שהוא ההתגלות והחיבור אין נ\"מ בזה כלל דבין כך ובין כך לא היה הפסק והבדל כלל בין אצילות לבי\"ע כי בחי' הדבור שנק' ים לא הפסיק ולא העלים והסתיר כלל (וכמ\"ש הים ראה וינוס<sup data-n=\"2020\">17</sup> כו') רק לפ\"ד",[["2012","9","<b>זה אלי</b>: בשלח טו, ב."],["2013","10","<b>בכתבי האריז\"ל</b>: נסמן לעיל עא, ב."],["2014","11","<b>עד יעבור אותיות עיבור</b>: בשלח טו, טז. ראה פע\"ח (שער הסליחות) שי\"ב פ\"ג. לקמן קב, א. מאמרי אדה\"א שמות ח\"א ע' סא. דברים ח\"א ע' יח ובהנסמן בהנ\"ל. תו\"ח נח נח, ב. וישב רח, ב."],["2015","12","<b>קול ה' יחולל אילו'</b>: תהלים כט, ט."],["2016","13","<b>כהאי איילתא</b>: ראה זהר פינחס רמט, ב. הנסמן לקמן קב, א."],["2017","14","<b>כד סליק ימא גלגלוהי</b>: ראה זהר בשלח מח, ב."],["2018","15","<b>ויבקעו המים</b>: בשלח יד, כא."],["2019","16","<b>עד\"מ ב' בנ\"א</b>: ראה גם סה\"מ תקס\"ג ח\"ב ע' תרסז. מאמרי אדה\"א ויקרא ח\"א ע' עדר. הנחות תקע\"ז ע' רסח. וש\"נ."],["2020","17","<b>הים ראה וינוס</b>: תהלים קיד, ג."]]],[2800530176,"האריז\"ל והמקובלים היה עיקר גלוי זה מלמעלה למטה שזהו גלוי אורות דאצי' בבי\"ע ולפ\"ד הזהר היינו שעלו נש\"י דבריאה באצילות מפני שאין עליהם בחי' הסתר וכיסוי כלל למנוע עלייתם וכמו\"כ אין מונע לאורות דאצי' לירד לבי\"ע ושניהם אמת וד\"ל (ובאמת יש בפי' ובנ\"י הלכו ביבשה בתוך הים כשני הפי' הנ\"ל ושניהם אמת ולא סתרי אהדדי כלל דמאחר שנבקע המסך יש דרך לעליון לירד לתחתון ויש דרך לתחתון לעלות לעליון כנ\"ל ושניהם נק' הליכה אלא שזה הולך ויורד מלמעל' למט' וזה הולך ועול' מלמט' למעל' ויתפר' ובנ\"י הלכו ביבשה בב' מיני הילוך הללו ושניהם אמת ולא סתרי כלל וכדוגמא זו מצינו באבות כמ\"ש במ\"א שהאבות הן המרכבה<sup data-n=\"2021\">1</sup> לבחי' חג\"ת דאצי' עשו קשר וחיבור<sup data-n=\"2022\">2</sup> ביח\"ע ע\"י עובדות שלהם מאצי' לבי\"ע ומבי\"ע לאצי' בכל המשכות בג' קוין דאצי' בבי\"ע וכל העלאו' מבי\"ע לאצי' וזה היה היסוד לקבל' ישראל תו\"מ לעשות יח\"ע כו' וזהו כל ענין ספר בראשי' שמדבר רק בסיפו' מעשה האבו' אברהם בעובדו' שלו עשה יח\"ע בקו ימין חח\"נ ויצחק בקו שמאל בג\"ה ויעקב ויוסף בקו האמצעי וע\"כ ספר בראשית יסוד<sup data-n=\"2023\">3</sup> ושרש לכל מ\"ע ול\"ת שבס' שמות ויקרא כו' ולפ\"ז כבר הי' הכנ' רבה לקבל' תו\"מ בפ\"מ ולמ' הוצרך לקי\"ס בשביל חיבור וקשר דאצי' ובי\"ע אך הילוך בנ\"י ביבשה בתוך הים הי' הכנה זו בנפשם ממש למט' שיעמדו ויקבלו בהר סיני כנ\"ל אבל הכנה דאבות בעובדות שלהם הי' למעלה באצילות לבד ולענין מעשה המצות לבד אבל שיקבע הכח הזה בנשמות ישראל בגופים ממש הוצרך לקי\"ס דוקא וד\"ל) אך הנה לב' הפי' הנ\"ל הי' צריך שיקרע הים לי\"ב קרעים דוקא למספר י\"ב שבטים דוקא והטעם ידוע להיות שד' דגלים דמחנה ישראל כל א' נחלק לג'<sup data-n=\"2024\">4</sup> שהן י\"ב היינו כמו למעלה בד' מחנות שכינה<sup data-n=\"2025\">5</sup> מחנה מיכאל כו' שכל א' נחלק לג' והן מספר י\"ב ודוגמא לזה הי' ים של שלמה<sup data-n=\"2026\">6</sup> למטה שי\"ב בקר תחתיהם כו' כך ים העליון הוא בחי' המל'<sup data-n=\"2027\">7</sup> עומד על ד' מחנות שהן י\"ב כנ\"ל ולמעלה באצילות עצמו ג\"כ נק' י\"ב ג\"א<sup data-n=\"2028\">8</sup> שהוא בבחי' ו\"ק דז\"א<sup data-n=\"2029\">9</sup> כידוע אך בבחי' מל' הוא בד' סטרי עלמא לבד מזרח ומערב צפון ודרום מחנה מיכאל לדרום<sup data-n=\"2030\">10</sup> וגבריאל לצפון כו' וכך היה סדר הד' דגלים דישראל כמ\"ש בזהר פ' פקודי<sup data-n=\"2031\">11</sup> ונמצא כלל הראשון הוא רק ד' ונחלק כל א' לג' עד שהן י\"ב שבטי' למטה בעולם הבריאה וכמו\"כ למעלה באצי' וכמ\"ש ששם עלו שבטים<sup data-n=\"2032\">12</sup> שבטי יה שבטים דעלמא דנוק' בבריאה שעולין באצילות ששם נק' שבטי יה והיינו בו\"ק דז\"א ששרשם במוחין דחו\"ב דז\"א שנק' י\"ה<sup data-n=\"2033\">13</sup> וזהו שאמרו השבטים ליעקב<sup data-n=\"2034\">14</sup> שבבחי' אצי' כשם שאין בלבך אלא אחד כו' דכגוונא דאינון<sup data-n=\"2035\">15</sup> כו' כידוע וד\"ל:\n(נה) <b>והנה</b> יש להבין הטעם למה נחלק כל אחד לג' דוקא ויובן זה ממה שאנו רואים שיש ג' פרקים ביד וג' פרקים ברגל<sup data-n=\"2036\">16</sup> והנה פרקי האצבעות הוא פרק העליון ביד וברגל האצבעות הוא פרק האחרון והטעם הוא כי ג' פרקים הן נגד ג' מדרגות חב\"ד חג\"ת נה\"י ופרק העליון הוא בחי' חב\"ד כמו ביד הימין שהוא בחי' החסד כידוע בענין דרועא ימינא<sup data-n=\"2037\">17</sup> כו' כלול מג' אלה חב\"ד שבחסד והוא העליון והיינו בפרקי האצבעות",[["2021","1","<b>שהאבות הן המרכבה</b>: ראה גם לקמן קלג, ב ובהנסמן במ\"מ לשם."],["2022","2","<b>שהאבות. . עשו קשר וחיבור</b>: ראה ד\"ה ויאמר וגו' לך לך תקס\"ז הנחת כ\"ק אדה\"א באוה\"ת לך (כרך ו) ע' תתרעו. תו\"ח לך פד, ג ואילך וראה בהנסמן שם פ, א הערה 1."],["2023","3","<b>ספר בראשית יסוד</b>: ראה גם אוה\"ת שם. תו\"ח שם פד, ד. ויצא קעג, ג ובהערה 22."],["2024","4","<b>שד' דגלים. . נחלק לג'</b>: ראה במדבר ב, ג ואילך."],["2025","5","<b>בד' מחנות שכינה</b>: נסמן בסמוך הערה ד\"ה מחנה מיכאל."],["2026","6","<b>ים של שלמה</b>: מלכים-א ז, כה. מד. דהי\"ב ד, טו."],["2027","7","<b>ים. . המל'</b>: נסמן לעיל סז, א."],["2028","8","<b>י\"ב ג\"א</b>: נסמן לקמן קכה, א."],["2029","9","<b>י\"ב ג\"א. . ו\"ק דז\"א</b>: ראה מאמרי אדה\"א שמות ח\"א ע' קסט. וש\"נ."],["2030","10","<b>מחנה מיכאל לדרום</b>: ראה זהר במדבר קיח, ב. ביאוה\"ז שם (פו, א ואילך). בשלח מב, א. הנסמן בתו\"ח נח נז, ד הערה 60."],["2031","11","<b>בזהר פ' פקודי</b>: כ\"ה בכ\"מ ומהם: שע\"ת ח\"א לג, א. מאמרי אדה\"א בראשית ע' תצח. וש\"נ. תו\"ח ח\"ש קכט, ג הערה 22."],["2032","12","<b>ששם עלו שבטים</b>: תהלים קכב, ד. ראה ביאוה\"ז במדבר פה, ד. מאמרי אדה\"א ויקרא ח\"א ע' רעח ואילך. וש\"נ. שע\"ת צב, ג ובהנסמן במ\"מ לשם."],["2033","13","<b>דחו\"ב. . י\"ה</b>: נסמן לעיל ו, א."],["2034","14","<b>שאמרו השבטים ליעקב</b>: ראה גם לקמן קמה, א ובהנסמן במ\"מ לשם."],["2035","15","<b>דכגוונא דאינון</b>: ראה זהר תרומה קלה, סע\"א."],["2036","16","<b>ג' פרקים ביד. . ברגל</b>: בלקו\"ת צו (כאן) מציין: וכמ\"ש בזהר פ' ויחי דרמ\"א ע\"א. וראה גם מאמרי אדה\"ז כאן על פרשיות התורה ע' רנט וע' רסח. תקס\"ח ח\"א ע' שעה. תו\"ח שמות סא, ב. בשלח קעח, ב. מאמר ד\"ה לה\"ע קי\"ס מכ\"ק אדה\"א [קה\"ת, תשמ\"ט] ע' 9. מאמרי אדה\"א נ\"ך ע' שכג וע' שמו. סה\"מ תרמ\"ז ע' נו ואילך."],["2037","17","<b>החסד. . דרועא ימינא</b>: ת\"ז בהקדמה (יז, א)."]]],[2800530177,"(אע\"פ שלענין נתינת שפע החסד האצבעות הנותן זהו כשמשפיל ידו לעני אבל ידו הפשוטה למעלה האצבעות בראש כמו בנשיאת כפים משא\"כ ברגל וד\"ל) שהרי אנו רואים שיש לבחי' מוחי' דחב\"ד באצבעות כמו ברמז שמרמז ביד באצבע דוקא והוא לכוין על אמיתת השכל והסברא שלא יוכל לגלות בדיבור ירמז ביד באצבעו כמו קא מחוי ליה<sup data-n=\"2038\">18</sup> כו' וכן במעשה הכתב כשחפץ לגלות עומק השכל שבמוח יביאנו בכתב באצבעותיו דוקא (וכן בשמחה ועונג שבמוח ולב יספק כף אל כף<sup data-n=\"2039\">19</sup> ולהיפך בצער כו' שזה מורה שגם מקיפים דחו\"ב וחו\"ג שבמוח ולב בפרק העליון שביד וכמ\"ש במ\"א) וכך הוא בבחי' החסד שביד ימין בחינת החכמה שבחסד זה הוא בפרק העליון שבאצבעות היד ובחי' חג\"ת שבחסד בפרק האמצעי שביד ופרק התחתון בכתף היד שהוא רק שפע חיצוניות דחסד שבלב בחי' נה\"י וכך הוא ביד השמאל בגבורת שמאל דוחה<sup data-n=\"2040\">20</sup> פרק העליון באצבעות חב\"ד שבגבורה והאמצעי חג\"ת שבגבורה כו' (וזהו בג\"ה כמו שמאלו תחת לראשי<sup data-n=\"2041\">22</sup> שהשמאל בכל מקום נכלל בימין<sup data-n=\"2042\">23</sup> ובימין הוא בחי' החסד בתגבורת בפרק העליון דוקא כמו ימין ה' רוממה<sup data-n=\"2043\">24</sup> כו' ונקרא יד רמה<sup data-n=\"2044\">25</sup> והגבורות ביד שמאל נק' יד החזקה<sup data-n=\"2045\">26</sup> ומ\"ש אצבע אלקים היא<sup data-n=\"2046\">27</sup> בגבורות דיד שמאל שגם במדת הדין עיקר הכח ועוז ביד שמאל דוחה בפרקי האצבעות כו') ונמצא ביד ימין ושמאל יש ששה פרקים והן בחי' חו\"ג חסד דרועא ימינא כלול מג' חח\"ן<sup data-n=\"2047\">21</sup> ובחי' גבורה דרועא שמאלא כלול מג' בג\"ה כו' וכמו\"כ ברגלים רגל ימין יש בו ג' פרקים השוק והירך כו' והירך פרק עליון ואצבעות הרגל פרק התחתון לפי שהרגלים בכלל הן בחי' נו\"ה והן תרין ירכין<sup data-n=\"2048\">28</sup> ירך ימין בחי' חב\"ד דנצח שמקבל בפנימית מנו\"ה דכליות יועצות<sup data-n=\"2049\">29</sup> כו' והשוק פרק האמצעי חג\"ת דנצח והעקביים ואצבעות פרק התחתון נה\"י דנצח וכן ברגל השמאל בבחי' הוד (כמ\"ש בזהר בענין יששכר וזבולון<sup data-n=\"2050\">30</sup> ובענין איהו בנצח<sup data-n=\"2051\">31</sup> כו') ונמצא ד' אלה חו\"ג דב' ידים ונו\"ה דב' רגלים כל אחד נחלק לג' פרקין הרי י\"ב וכמו\"כ יובן באדם העליון דאצי' בחו\"ג דידים ונו\"ה דרגלים מתחלקים לי\"ב ולכך מספר שבטים דלעילא י\"ב וכך הוא למטה במל' בד' מחנות שכינה שכל אחד נחלק לג' כנ\"ל רק שהוא באופן אחר דהיינו לד' סטרי עלמא והוא ענין ד' רבתי דאחד<sup data-n=\"2052\">32</sup> (ובד' רוחות העולם מזרח ומערב נו\"ה וצפון ודרום חו\"ג כמ\"ש במ\"א) והנה עכ\"פ בשעה שהלכו בנ\"י ביבשה בתוך הים היה כל שבט הולך ועולה בקרע וגזר מיוחד לעבור בו מאחר שנאמר ששם עלו שבטים שבטי יה ב' מיני שבטים בבריאה ובאצילות כנ\"ל ולב' הפי' הנ\"ל בהילוכם בים בין שירד האור מלמעלה למטה מאצילות לבריאה ובין שעלו נשמות דבריאה באצילות הכל צריך שיהיה י\"ב גזרים שיעבור כל שבט במסילה בפ\"ע אם הי' בדרך הילוך מלמטה למעלה עלה כל שבט בפ\"ע מבריאה לאצילות ואם היה בדרך ירידה והילוך מלמעלה למטה הרי הי' מאיר מי\"ב שבטים דאצילות לכל שבט הארה מיוחדת אליו וצריך שיהיה לו מסילה ודרך בים בפ\"ע מאחר שיש לכ\"א מדריגה בפ\"ע בהתחלקות מד' לי\"ב דוקא כנ\"ל הרי יש לכל שבט שרש מיוחד בפ\"ע באצי' (וכמ\"ש במ\"א בענין הברכות שבירך יעקב לבניו איש כברכתו<sup data-n=\"2053\">33</sup> דוקא בשרשו באצי' וכן משה שבירך לכל שבט ושבט היינו",[["2038","18","<b>קא מחוי ליה</b>: ראה חגיגה ה, ב. ב\"מ ז, א."],["2039","19","<b>בשמחה. . כף אל כף</b>: ראה גם מאמרי אדה\"ז תקס\"ג ח\"א ע' רפב וע' רפח. תקס\"ח ח\"א ע' סה ואילך. ע' עא. מארז\"ל ע' עט. ס\"ע תסא ואילך. תו\"ח שמות קצח, א ואילך."],["2040","20","<b>שמאל דוחה</b>: סוטה מז, א."],["2041","22","<b>שמאלו תחת לראשי</b>: שה\"ש ב, ו."],["2042","23","<b>שהשמאל. . נכלל בימין</b>: ראה גם תו\"ח וירא קטז, ד."],["2043","24","<b>ימין ה' רוממה</b>: תהלים קיח, טז."],["2044","25","<b>יד רמה</b>: בשלח יד, ח."],["2045","26","<b>יד החזקה</b>: בא יג, ט."],["2046","27","<b>אצבע אלקים היא</b>: וארא ח, טו."],["2047","21","<b>בג\"ה. . חח\"ן</b>: נסמן לקמן קכד, ב."],["2048","28","<b>נו\"ה והן תרין ירכין</b>: ראה ת\"ז תי\"ג (כט, א) ובהנסמן בניצוצי זהר שם."],["2049","29","<b>מנו\"ה דכליות יועצות</b>: נסמן לקמן קלד, א."],["2050","30","<b>דנצח. . הוד. . יששכר וזבולון</b>: ראה זהר (סבא) משפטים קד, ב."],["2051","31","<b>איהו בנצח</b>: ראה ע\"ח (שער הנסירה) שכ\"ט פ\"ה ופ\"ז. (שער לאה ורחל) של\"ח פ\"ו. הנסמן במאמרי אדה\"א נ\"ך ע' מ."],["2052","32","<b>ד' רבתי דאחד</b>: ראה הנסמן במאמרי אדה\"א דברים ח\"א ע' רפג."],["2053","33","<b>איש כברכתו</b>: ויחי מח, כט [בדילוג]. ראה סה\"מ תקס\"ח ח\"ב ס\"ע תרסו ואילך. מאמרי אדה\"א שמות ח\"ב ע' תכט."]]],[2800530178,"כברכתו בשרשו באצי' כידוע) וזהו לגוזר י\"ס לגזרים כל\"ח דהנה לפי ב' הפי' הנ\"ל הי' צריך שיקרע הים לי\"ב גזרים דוקא לכל שבט ושבט קרע וגזר בפ\"ע דכמו שלמטה יש י\"ב שבטים בבריאה כך למעלה באצי' יש י\"ב שבטים כנ\"ל ובשביל גלוי אורות עליונים דשבטים עליונים שמקבלים מבחי' ו\"ק דז\"א דאצי' שיומשכו למטה ביב\"ש שלמטה בהכרח שיהיה מקום מעבר בים העליון שיומשך מאצי' במסילה מיוחדת לכל אחד בפ\"ע כמו ג' דמסטר דרום כל אחד ואחד צריך דרך ומעבר לעצמו שיקבל משם כמו הילוך הדגלים או כמו ד' מחנות שכינה שכל אחד מדרגה בפ\"ע וכמו\"כ בבחינת העלאות שעולין יב\"ש דלמטה בבריאה ליב\"ש דאצילות כמ\"ש ששם עלו שבטים כו' כנ\"ל שזהו כמו פי' השני שלפ\"ד הזהר צריך להיות ג\"כ דרך ומעבר לעלות בו לכל או\"א בפ\"ע כי כל א' וא' מקבל אור שפעו מאצילות בפרטיות מובדל מזולתו וצריך להיות לו מסילה מיוחדת שיעלה בה שלא יוכל לעלות כלל במסילה של שבט זולתו ולכך נקרע הים העליון לי\"ב גזרים דוקא ובכל א' וא' יש חסד עליון בין בעלייה ובין בירידה מיוחד בפ\"ע והיינו שאמר לגוזר י\"ס לגזרים מחולקים נגד יב\"ש כי לעולם חסדו שיהי' חיבור לעולם מחסד עליון דאצי' בין בעלי' ובין בירידה כפי ב' הפי' הנ\"ל דשניה' אמת כנ\"ל וד\"ל (וגם עכשיו יש דוגמא זאת דיב\"ש שלמטה עם יב\"ש דאצי' כענין קי\"ס ממש בב' אופנים הנ\"ל בעלי' ובירידה כו' והיינו בתפלות דישראל שיש למעלה י\"ב שערים נגד י\"ב שבטים<sup data-n=\"2054\">1</sup> שכל שבט יש לו שער מיוחד אליו שתפלת כל השבט ההוא עולה דרך השער ההוא דוקא המיוחד אליו ולא יוכל לעלות תפלתו בשער של שבט זולתו כלל וכן בענין הירידה וההמשכה בח\"י ברכות דש\"ע וכה\"ג בכל גלוי אור העליון דאצילות לבי\"ע אינו יורד ונמשך רק באותו השער המיוחד אליו דוקא כי לכל שבט אור השפע שלו מיוחד בשרשו באצי' בדרך ושער מיוחד השייך אליו דוקא אך יש שער הי\"ג הכולל כל הי\"ב שערים<sup data-n=\"2055\">2</sup> והוא שער הפונה קדים כו' שבו יוכל כל שבט לעלות בתפלותיו לפי שכלול מכל הי\"ב שבטים ובו יוכל לעבור אור ושפע דאצילות לכל שבט ושבט מלמעלה למטה להיותו כולל כולם) (והיינו ענין שינוי נוסחות בתפלה לפי המקומות בספרד ואשכנז ופולין והאריז\"ל תיקן מכל הנוסחות כפי הנוסח שיוכל לעלות כל שבט מפני שעכשיו בגלות כל ישראל מעורבבים כו' וד\"ל) (וכמו שאנשי כנה\"ג תיקנו ח\"י ברכות<sup data-n=\"2056\">3</sup> על הסדר שיהי' כולל כל השבטי' והוא שער הי\"ג כך האריז\"ל תיקן בנוסח הברכות שלפני ק\"ש ובפסד\"ז וקודם לכן הכל באופן שיעלו בו כל נש\"י שהוא בחי' שער הי\"ג וד\"ל) (ומה שלא היה כן גם בקי\"ס שיהיה מסילה כוללת כולם כמו שער הי\"ג לפי שהיה צריך שיהיה הכנה בנפש כל אחד מהם לקבלת התורה בהר סיני שבהכרח שיהיה מקום לכל שבט ומשפחה בפ\"ע לעבור בים כנ\"ל וד\"ל):\n<b>ומעתה</b> הנה יש להבין ענין מה שהי' קי\"ס הכנה לקבלת התורה עד שבשביל מ\"ת דוקא הוצרך להעבירם בי\"ס דוקא כנ\"ל דהנה ידוע בפי' ענין קבלת התורה דהיינו שיהיה כל נשמה אלקי'",[["2054","1","<b>י\"ב שערים. . שבטים</b>: ראה שו\"ע אדה\"ז הל' ק\"ש סס\"ח, ס\"ב. פע\"ח (שער התפלה) ש\"א בהקדמה. עמה\"מ שער עולם הבריאה פי\"א בהגה (קעב, ב). תו\"ח וישב ריא, ג. בהערה הבאה."],["2055","2","<b>שער הי\"ג. . הי\"ב שערים</b>: ראה לק\"א להה\"מ סקל\"ג ובהנסמן לשם. שער הכולל בהקדמה. וש\"נ. תו\"ח נח עד, א ובהערה 17."],["2056","3","<b>שאנשי כנה\"ג תיקנו ח\"י ברכות</b>: ראה מגילה יז, ב. יח, א. שו\"ע אדה\"ז הל' תפלה רספ\"ט. שער הכולל פ\"ח ס\"ב."]]],[2800530179,"בחי' כלי בית קיבול גמור לקבל אור דתורה כמו שהיא למעלה בשרשה בבחי' ח\"ע דאורייתא מח\"ע נפקת<sup data-n=\"2057\">4</sup> והיינו בחי' גלוי אוא\"ס שבפנימית ח\"ע דתורה הוא שנמשך למטה בבחי' חכמה תתאה חכמה שבדבור שזהו בים העליון להיות מתקבל בנש\"י למטה ממש ששרשם בחי' המל' למעלה וע\"כ הוצרך לקי\"ס היינו שיקרע להם הים העליון ועי\"ז דוקא יהיו בחי' כלי בית קיבול לקבל בנפשם מגלוי אא\"ס שבחכמה עילאה דתורה שנק' קבלת התורה שהרי כל עיקר ענין קי\"ס היה רק שיוכל להיות גלוי אורות דאצי' בבי\"ע כמו בד' מחנות שכינה למעלה וכן בד' דגלים דישראל למטה שא\"א להיו' זה כ\"א ע\"י בקיע' הים שלא יעלים ויפסיק שזהו כמו בקיע' הפרסא שבין אצילות לבריאה כנ\"ל ואם לא היה קי\"ס הרי לא היו יכולים בנ\"י להגיע למדרג' זו להיות בית קיבול לקבלת התורה מאור א\"ס שבח\"ע דאצי' וכן לפי' הב' דהליכתם היה בתוך הים העליון בדרך העלאה שעלו נש\"י למעלה באצי' שזה ג\"כ א\"א בלא קי\"ס והוא הכנה בנפשם למ\"ת שעל כל דבור פרחה<sup data-n=\"2058\">5</sup> כו' וד\"ל אך הנה עיקר ענין קבלת התורה בהר סיני לא היה עכשיו רק בבחי' הנגלה שבתור' שהוא המעשה בפ\"מ והוא התורה הנגלית לנו בענין קיום המצות מעשיות ובפ\"מ כמ\"ש הנסתרות כו' והנגלות לנו ולבנינו לשמור ולעשות<sup data-n=\"2059\">6</sup> כו' דהיום לעשותם<sup data-n=\"2060\">7</sup> דוקא ובודאי יש גלוי אור א\"ס בח\"ע עד ח\"ת דתורה הנגלית לנו בכל מצוה ומצוה שעושין בפ\"מ דוקא אך הוא בהעלם ולבוש כידוע וגם במצות ת\"ת שכנגד כולם<sup data-n=\"2061\">8</sup> הכל בבחי' הנגלה דוקא שהן הן כל הלכות דתשבע\"פ באיסור והיתר טומאה וטהרה חייב זכאי כו' לברר לעה\"ד טו\"ר בפ\"מ להבדיל בין טמא לטהור כו' שבדצ\"ח גשמיים דוקא (וגם בג\"ע דעשיי' ויצירה לומדין דיני נגעים<sup data-n=\"2062\">9</sup> בהרת ושער לבן וכל הדינין והלכות דטומאה וטהרה ואו\"ה כו' כמו בעוה\"ז הגם שהוא ע\"ד הרוחניות בודאי מ\"מ עיקר הלימוד שם הוא בפסקי ההלכות ע\"ד הפשט<sup data-n=\"2063\">10</sup> רק שיודעי' ומשיגי' אפס קצהו מן הטעמים וסודות שבהן שיתגלו לע\"ל כמשי\"ת ב\"ה) אבל הנה ידוע דאוריית' סתי' וגלי'<sup data-n=\"2064\">11</sup> וכל ענין מ\"ת הי' על בחי' גליא שבתורה ברמ\"ח מ\"ע ושס\"ה ל\"ת בגשמיות וגם חכמה שבתורה באה הכל ע\"ד הנגלה כנ\"ל (ומכריזין בג\"ע ג\"כ אשרי מי שבא לכאן<sup data-n=\"2065\">12</sup> ותלמודו שלמד בעוה\"ז בידו) ובחינת סתים שבתורה היינו בחי' הנסתר שבה שנקרא נסתרות לה' אלהינו הנק' פנימית התורה והוא התגלות טעמי המצות וסודותיהן בשרשן בח\"ס בחי' פנימית ח\"ע דתורה שלנו נקרא רק נובלות חש\"מ<sup data-n=\"2066\">13</sup> לבד כו' ועכשיו הרי הן סתומים ונעלמים למעלה מעלה גם באצילות שהרי גם משה ביקש הראני נא כבודך<sup data-n=\"2067\">14</sup> כבוד ל\"ב נ\"ח<sup data-n=\"2068\">15</sup> הפנימים ונעלמים והשיבו ופני לא יראו<sup data-n=\"2069\">16</sup> כו' שפנימית סודות התורה כמוס עמדו סתום וחתום ולא נודע כלל וכלל כו' והיינו מ\"ש על עדן עין לא ראתה<sup data-n=\"2070\">17</sup> אלקים זולתך יעשה למחכה לו דעין לא ראתה משמע אפי' משה והאבות וכה\"ג רק למחכה לו בימות המשיח ועוה\"ב וזהו שאמר היום לעשותם בגשמיות כנ\"ל ולמחר לקבל שכרם<sup data-n=\"2071\">18</sup> למחר דוקא יומשך לכנ\"י פנימית טעמי תורה וכדפרש\"י ע\"פ ישקני<sup data-n=\"2072\">19</sup> מנשיקות",[["2057","4","<b>דאורייתא מח\"ע נפקת</b>: נסמן לעיל כג, א."],["2058","5","<b>שעל כל דבור פרחה</b>: נסמן לעיל ט, ב."],["2059","6","<b>הנסתרות. ולבנינו לשמור ולעשות</b>: נצבים כט, כח [ושם: ולבנינו עד עולם לעשות ? ראה תו\"ח בראשית ה, ג הערה 11]."],["2060","7","<b>דהיום לעשותם</b>: ואתחנן ז, יא."],["2061","8","<b>ת\"ת שכנגד כולם</b>: פאה רפ\"א."],["2062","9","<b>בג\"ע. . דיני נגעים</b>: ראה ב\"מ פו, א. מאמרי אדה\"א ויקרא ח\"ב ע' תמג ובהנסמן לשם. ע' תנו."],["2063","10","<b>בפסקי ההלכות ע\"ד הפשט</b>: ראה גם מאמרי אדה\"א בראשית ע' תקסז."],["2064","11","<b>דאוריית' סתי' וגלי'</b>: ראה זהר אחרי עא, ב. עג, א."],["2065","12","<b>אשרי מי שבא לכאן</b>: פסחים נ, א. ראה מאמרי אדה\"א דברים ח\"ד ע' א'תיד. וש\"נ. הנחות תקע\"ז ע' רצט. וש\"נ."],["2066","13","<b>דתורה. . נובלות חש\"מ</b>: ב\"ר פי\"ז, ה. פמ\"ד, יז."],["2067","14","<b>הראני נא כבודך</b>: תשא לג, יח [ושם: את כבודך]."],["2068","15","<b>כבוד ל\"ב נ\"ח</b>: ראה פרדס (שער ערה\"כ) שכ\"ג מערכת כבוד. מאמרי אדה\"א בראשית ע' ג ואילך. דברים ח\"ב ע' שפ. וש\"נ."],["2069","16","<b>ופני לא יראו</b>: תשא שם, ג."],["2070","17","<b>עדן עין לא ראתה</b>: ראה גם לעיל סא, ב ובהנסמן לשם."],["2071","18","<b>ולמחר לקבל שכרם</b>: ראה עירובין כב, א."],["2072","19","<b>וכפרש\"י ע\"פ ישקני</b>: נסמן לעיל ג, ב."]]],[2800530180,"פיהו שהן טעמי תורה שלא נגלו עתה רק לע\"ל יתגלו לישראל כידוע וד\"ל:\n(נו) <b>ולהבין</b> זה הנה כתיב במשיח הנה ישכיל עבדי<sup data-n=\"2073\">1</sup> ירום ונשא וגבה מאד ומבואר במ\"א בפי' מאד למעלה מבחי' אדם<sup data-n=\"2074\">2</sup> שזהו בחי' גילוי עצמות אא\"ס בפנימית התענוג והחכמה שבמהו\"ע ממש שלמעלה מעלה גם מאור דתו' שבח\"ע שנקרא ח\"ס דזהו פי' ישכיל עבדי ישכיל ממקור החכמה שהוא הנקרא טוב טעם ותענוג וחכמה הנעלם בעצמות ממש שלא נגלה עדיין לשום אדם גם למשה במ\"ת ולא לאבות כו' (כמ\"ש במ\"א על ענין המאמ' במנחות יבא טוב ויקבל טוב<sup data-n=\"2075\">3</sup> מטוב לטובים יבא טוב זה משה שנאמר בו כי טוב<sup data-n=\"2076\">4</sup> הוא ויקבל טוב זה אור התורה כו' והיינו קבלת התורה בפנימית טעמי המצות שע\"י משיח שנקרא גואל אחרון<sup data-n=\"2077\">5</sup> והוא שאמר משה שלח נא<sup data-n=\"2078\">6</sup> כו') וכידוע<sup data-n=\"2079\">7</sup> דשרש משה בפנימית אבא ושרש משיח בפנימית ע\"י<sup data-n=\"2080\">8</sup> ואמר בע\"ח בכמה דוכתי דפנימית אבא הוא פנימית ע\"י<sup data-n=\"2081\">9</sup> והיינו משה שנקרא גואל ראשון<sup data-n=\"2082\">10</sup> ומשיח נקרא גואל אחרון כמ\"ש גאלתי אתכם אחרית כמבראשית<sup data-n=\"2083\">11</sup> ובאמת בשרש א' הם וע\"כ א' יבא טוב דקאי במשה והוא שיבא בביאת משיח שיקבל טוב בפנימית התורה כמשי\"ת ועכ\"ז נקרא משיח מלכא משיחא<sup data-n=\"2084\">12</sup> ולא הי' משה נקרא מלכא אלא משה רבינו<sup data-n=\"2085\">13</sup> והוא בהיותו מלמד תורה לישראל בבחי' הנגלה כמ\"ש תורה צוה לנו משה<sup data-n=\"2086\">14</sup> כו' אבל משיח יהיה בבחי' מלך דוקא בדוגמא דמלך מלכי המלכים<sup data-n=\"2087\">15</sup> מפני שבו יגלה ממהו\"ע אא\"ס ממש וע\"כ נא' בו מאד למעלה מבחי' אדם כידוע דאדם הוא שם מ\"ה<sup data-n=\"2088\">16</sup> דחכמה עד רום המעלות שהוא בבחי' חכמה הקדומה שנקרא א\"ק וזהו שרש משה דכתיב ביה מה שמו כו' ומאד בהיפך אותיות דאדם<sup data-n=\"2089\">17</sup> למעלה הוא מבחי' אדם קדמאה להיותו במהו\"ע ממש וד\"ל). וזהו ירום ונשא וגבה ג' אלה היינו באבות וירום מאברהם<sup data-n=\"2090\">18</sup> בחי' החסד דקו ימין דאצי' חח\"נ ונשא מיצחק<sup data-n=\"2091\">19</sup> קו שמאל בג\"ה וגבה מיעקב<sup data-n=\"2092\">20</sup> קו האמצעי דאצי' דת\"י וע\"ז אמר אל יתהלל חכם<sup data-n=\"2093\">21</sup> כו' כי שרש משיח בפנימית ועצמות המאציל שלמעלה משרש התחלקות הקוין שמתחלקים מח\"ס כו' וזהו שע\"י משיח דוקא יומשך ויושפע לישראל בחי' פנימית התורה שהן טעמי תורה ומצות שהן עתה בבחי' ההעלם גנוז בתורה בלתי נגלה גם בח\"ס שרש האצילות כולו כו' והוא הנקרא עדן סתימאה<sup data-n=\"2094\">22</sup> דעין לא ראתה כו' שלא נתגלה גם למשה והאבות כנ\"ל רק לעתיד בימהמ\"ש דוקא כמ\"ש ישקני לשון עתיד כו' וכמו שע\"י משה ניתן ונמשך תורה הנגלית לנו כך ע\"י משיח יומשך לנו פנימית וסודות התורה הנגלית דעכשיו וזהו למחר לקבל שכרם כנ\"ל והנה ההפרש בין חיצוניות התורה הנגלית לנו לפנימית התור' אע\"פ שהפנימית היינו בחיצוניות שהוא טעמים וסודות של כל דין והלכה שבתורה הנגלית דוקא מ\"מ הרי על פנימית התורה אמר ארוכה מארץ מדה<sup data-n=\"2095\">23</sup> ורחבה מני ים דהיינו שהאורך הוא בחי' ההמשכה למטה ארוכה מארץ שהוא בבחי' א\"ס ממש ורחבה בעצם מקורה בבחי' א\"ס בעלוי אחר עלוי",[["2073","1","<b>במשיח הנה ישכיל עבדי</b>: ישעי' נב, יג. מאמרי אדה\"א ויקרא ח\"א ע' קיב. וש\"נ."],["2074","2","<b>מאד למעלה מבחי' אדם</b>: ראה לקו\"ת להאריז\"ל תשא לג, ה. מאמרי אדה\"ז על פרשיות התורה כאן ע' רסא וע' רסט. מאמרי אדה\"א קונטרסים ע' דש. וש\"נ. סה\"מ תרל\"ה ח\"א ע' רסה ואילך."],["2075","3","<b>יבא טוב ויקבל טוב</b>: ראה מנחות נג, ב. ראה גם ביאוה\"ז בהקדמה. מאמרי אדה\"ז אתהלך לאזניא ע' לו ואילך. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' שנט. דרושי חתונה ח\"ב ע' תרכה ואילך. לקמן צה, ב."],["2076","4","<b>משה. . כי טוב</b>: שמות ב, ב."],["2077","5","<b>משיח שנקרא גואל אחרון</b>: ראה גם מאמרי אדה\"א קונטרסים ע' שנב. וש\"נ."],["2078","6","<b>שלח נא</b>: שמות ד, יג."],["2079","7","<b>וכידוע</b>: אוצ\"ל: (וכידוע."],["2080","8","<b>דשרש משה. . משיח. . ע\"י</b>: ראה מאמרי אדה\"א ויקרא ח\"א ע' קצג ואילך. שע\"ת נו, ד ובהנסמן במ\"מ לשם."],["2081","9","<b>בע\"ח. . דפנימית אבא. . ע\"י</b>: נסמן לקמן קכח, א."],["2082","10","<b>משה שנקרא גואל ראשון</b>: ראה במדב\"ר פי\"א, ב."],["2083","11","<b>גאלתי אתכם אחרית כמבראשית</b>: בסידור אדה\"ז בקדושת כתר: כבראשית (ראה שער הכולל פכ\"ז, ס\"ו הובא באג\"ק כ\"ק אדמו\"ר שליט\"א חי\"ב ע' רפט)? מאמרי אדה\"ז נביאים ע' סא."],["2084","12","<b>נקרא משיח מלכא משיחא</b>: ירושלמי ברכות פ\"ב ה\"ד. ראה לקמן צה, א. מאמרי אדה\"א דברים ח\"ג ע' א'קכד. וש\"נ."],["2085","13","<b>משה נקרא. . רבינו</b>: ראה גם אמ\"ב שער התפילין קכו, ב."],["2086","14","<b>תורה צוה לנו משה</b>: ברכה לג, ד."],["2087","15","<b>דמלך מלכי המלכים</b>: ברכות כח, ב."],["2088","16","<b>דאדם. . מ\"ה</b>: נסמן לעיל ס, א."],["2089","17","<b>ומאד בהיפך אותיות דאדם</b>: ראה זהר (רע\"מ) פינחס רמו, ב. ב\"ר פ\"ח, ה. פ\"ט, יב. ראה גם שע\"ת קמ, ד."],["2090","18","<b>וירום מאברהם</b>: כ\"ה גם במאמרי אדה\"א במדבר ח\"ב ע' תיג בשם הזהר ? ראה תנחומא תולדות יד. יל\"ש ישעי' נב, יג (רמז תעו)."],["2091","19","<b>ונשא מיצחק</b>: כ\"ה גם במאמרי אדה\"ז על פרשיות התורה כאן ע' רסט. תנחומא שם (ולהעיר מענף יוסף לשם). ראה גם לקו\"ש שמות (כרך ו) ע' 254. ע' 255. (כרך טז) 491. נדפס גם באג\"ק מכ\"ק אדמו\"ר שליט\"א ח\"ד ע' קפא. חי\"ג ע' נד. חכ\"ב ע' שסה."],["2092","20","<b>וגבה מיעקב</b>: תנחומא שם."],["2093","21","<b>אל יתהלל חכם</b>: ירמי' ט, כב."],["2094","22","<b>עדן סתימאה</b>: ראה גם לעיל סא, ב ובהנסמן במ\"מ לשם."],["2095","23","<b>ארוכה מארץ מדה</b>: איוב יא, ט. ראה גם תו\"ח מקץ רכח, ב."]]],[2800530181,"בפנימית ועצמות אא\"ס שאין לו שיעור למעלה ואין לו שיעור למטה משא\"כ התורה הנגלית לנו באה דוקא במדה ושיעור וגבול<sup data-n=\"2096\">24</sup> כידוע לפי שהיא בבחי' החיצוניות דח\"ע ואע\"פ שנקרא משל הקדמוני<sup data-n=\"2097\">25</sup> מקדמונו ש\"ע אבל ירדה למטה מטה בבחינת גבול ושיעור דוקא ואמנם על ידה דוקא יבא גילוי אור פנימית התורה ע\"י משיח דהא בהא תליא דוקא וד\"ל ובאמת הנה גם הדרך הפשוט מורה כך שעיקר ביאת משיח לא יהיה רק בשביל קבלת התורה בפנימית שבה שנקרא טעמי תו\"מ ולא בשביל קבלת תורה בנגלה שהרי ביהמ\"ש אמר ואת רוח הטומאה<sup data-n=\"2098\">26</sup> אעביר מן הארץ ולא יהיה רע כלל גם בברואים גשמיים כמ\"ש וגר זאב עם כבש<sup data-n=\"2099\">27</sup> כו' ועיקר התורה הנגלית היא להבדיל בין טו\"ר בעה\"ד טו\"ר ואילנא דטו\"ר יתברר לעתיד וא\"כ לא יהי' לימוד התורה אז בכשר ופסול טמא וטהור כו' כמ\"ש בר\"מ<sup data-n=\"2100\">28</sup> אלא יהיה כל התו\"מ הכל בבחי' הרוחניות כמו קודם חטא אדה\"ר בעה\"ד כו' וכמ\"ש במ\"א (אע\"פ שאין בין גלות לימהמ\"ש רק שעבוד מלכיות<sup data-n=\"2101\">29</sup> זהו קודם תחה\"מ דוקא) ועוד שאחר תחה\"מ הרי יקומו הכל והיינו גם מכל הדורות הראשוני' שלפני האבות והאבות ומשה ואהרן וכל צדיקים ונביאים ויהיו לאלפי אלפים רבבות לאין שיעור ואיך יתכן לומר שמשיח יהיה משפיע לכולם תורה הנגלית לנו ועוד שאיך ילמוד למשה ויהושע וזקנים וכל דורות התנאים שהיו יודעים כבר כל התורה הנגלית כולה שבודאי לא יצטרכו לקבל דין והלכה חדשה ממשיח שלא יבא לחדש דבר וח\"ד<sup data-n=\"2102\">30</sup> כו' אלא מוכרח לומר שמשיח יהיה משפיע לכולם טוב טעם ודעת בסודות פנימית התורה כולה כנ\"ל אשר עין לא ראתה עדיין גם למשה והאבות כו' מטעם הנ\"ל רק למשיח יתגלה כמ\"ש בו וגבה מאד כנ\"ל וד\"ל. והנה כמו שמבואר למעלה בענין קבלת התורה הנגלית לנו במ\"ת ע\"י משה שהוצרך ה' להעביר לישראל עמו בי\"ס מטעם הנ\"ל שיהיה הכנה בנפשם לקבלת התורה ע\"י בקיעת המסך בים העליון שיוכל להיות חבור וגלוי ההעלם מאצי' לבי\"ע ומבי\"ע לאצילות בחיצוניו' ע\"י קיום התו\"מ בפ\"מ בהעלאות והמשכות כנ\"ל כך ממש יהיה לעתיד כאשר יצטרכו בנ\"י לקבל התורה בפנימית וטעמי המצות ע\"י משיח כנ\"ל יהי' מן ההכרח שיהי' הכנ' רבה בנפשם בשביל קבל' טוב' וגדול' זו והוא במה שיעבירם בנהר פרת שהוא הנהר היוצא מעדן<sup data-n=\"2103\">31</sup> כו' שהוא למעל' הרב' מאד נעל' במדריג' מקי\"ס (דקי\"ס היינו רק בה\"א תתא' דמל' ובנהר הזה דלעתיד הוא בבחי' ה\"א עילא' בחי' בינה כמשי\"ת ב\"ה) והיינו הך ממש דכמו שהוצרכו בנ\"י לעבור בי\"ס לקבלת התור' בחיצוניות בנגל' בפ\"מ כך ממש יצטרכו לעבור בנהר פרת בשביל קבלת התור' בנסתר שנקרא עדן עילא' סתימא' דעין לא ראת' כנ\"ל והוא כשיעברו בנהר פרת שהוא הנהר שיוצא מעדן עילא' זה כו' וד\"ל. וזהו מ\"ש עד יעבור עמך הוי' עד יעבור עם זו קנית<sup data-n=\"2104\">32</sup> דלא נזכר ביעבור הב' שם הוי' רק סתם עד יעבור עם זו כו' וזה מרמז על ב' מדריגות הנ\"ל העבר' ראשונ' בקי\"ס בשביל קבלת התור' בנגל' שזהו בבחי' שם הוי' דחכמ' יו\"ד חכמ' וה\"א בינ'<sup data-n=\"2105\">33</sup> כו' כל ע\"ס דאצי' שזהו הנאמר בכל מצות שנתנה ע\"י משה כמ\"ש ויאמר<sup data-n=\"2106\">34</sup> הוי' אל משה",[["2096","24","<b>התורה הנגלית. . במדה ושיעור וגבול</b>: להעיר מהל' ת\"ת לאדה\"ז פ\"א ס\"ה."],["2097","25","<b>התורה. . משל הקדמוני</b>: נסמן לעיל סא, ב."],["2098","26","<b>ואת רוח הטומאה</b>: זכרי' יג, ב."],["2099","27","<b>וגר זאב עם כבש</b>: ישעי' יא, ו."],["2100","28","<b>ואילנא דטו\"ר. . כמ\"ש בר\"מ</b>: ראה זהר (רע\"מ) נשא קכד, ב. קכה, א. אגה\"ק סכ\"ו. מאמרי אדה\"א ויקרא ח\"ב ע' תרפה ואילך."],["2101","29","<b>שאין בין. . שעבוד מלכיות</b>: ראה ברכות לד, ב. ראה גם [ד\"ה אוסרי לגפן תקס\"ד ב]תו\"ח ויחי רלו, א ובהערה 5."],["2102","30","<b>וח\"ד</b>: וחצי דבר."],["2103","31","<b>בנהר פרת. . מעדן</b>: ראה לעיל פג, ב."],["2104","32","<b>עד יעבור. . קנית</b>: בשלח טו, טז."],["2105","33","<b>יו\"ד חכמ' וה\"א בינ'</b>: נסמן לעיל כב, ב הערה דמל'."],["2106","34","<b>ויאמר. . ועשו להם ציצית</b>: שלח טו, לז. לח [בדילוג]."]]],[2800530182,"ועשו להם ציצית כו' וכה\"ג אבל בשביל קבלת התורה בפנימית שלעתיד אמר עד יעבור סתם ולא הזכיר שם הוי' כלל להיותו למעלה משם הוי' דאצי' שבא בגלוי אור מאצי' לבי\"ע כי פנימית וסודות התור' שרשם במהו\"ע המאציל ממש שנקרא סדכ\"ס<sup data-n=\"2107\">1</sup> דלמת\"ב כלל<sup data-n=\"2108\">2</sup> אפי' מחשב' דא\"ק כו' וז\"ש עדן עין לא ראת' אלקים זולתך דלא ידע לי' בר איהו<sup data-n=\"2109\">3</sup> כו' וד\"ל (וזהו ג\"כ מ\"ש למשה אהי' אשר אהי'<sup data-n=\"2110\">4</sup> אהיה הראשון בבחי' כתר<sup data-n=\"2111\">5</sup> דע\"י וא\"א והוא כתר פרטי ואהיה שני אנא זמין לאתגלאה<sup data-n=\"2112\">6</sup> במשיח ותחה\"מ ועוה\"ב הוא בחי' כתר הכללי שיאיר במשיח וזהו עד יעבור סתם לעתיד דוקא) וזהו מ\"ש הפך ים ליבשה<sup data-n=\"2113\">7</sup> לשון עבר שזהו בקי\"ס שהי' בחי' הכנ' רק למ\"ת בנגל' אבל בשביל מ\"ת בפנימית וסודות התור' לעתיד אמר בנהר יעברו ברגל היינו בנהר פרת שהוא נהר שיוצא מעדן הנ\"ל ואז שם נשמחה בו שם דוקא ונשמח' בו דוקא במהו\"ע ממש וכמ\"ש יחיינו מיומיים<sup data-n=\"2114\">8</sup> במ\"ת הנגלית לנו וביום הג' יקימנו ונחיה לפניו ממש בימות המשיח ועוה\"ב וקי\"ס יהיה אז רק בדרך טפל בעלמא מטעם הנ\"ל וד\"ל:\n(נז) <b>והנה</b> מעתה יש להבין ביאור ענין העבר' שני' בנהר פרת דוקא בשביל קבלת התור' בפנימית ע\"י משיח כנ\"ל ויש להקדים תחל' במ\"ש ונהר יוצא מעדן<sup data-n=\"2115\">9</sup> כו' מהו ענין נהר הזה שיוצא מעדן כו' דהנה ידוע שהמח' נקרא נהר<sup data-n=\"2116\">10</sup> כמו הנהר שיוצא ונמשך בתמידות בלי הפסק אפי' רגע אחד כך המח' משוטטת תמיד<sup data-n=\"2117\">11</sup> ואינה נחה אפי' רגע וכמו הנהר נביעתו ממקורו מן המעיין כך המחשב' שרש נביעת' ממוח החכמ' שנקרא מעיין<sup data-n=\"2118\">12</sup> כידוע וזהו ונהר יוצא מעדן שהוא בחי' מחשב' דבינ' שיוצא מחכמ' שנקרא עדן<sup data-n=\"2119\">13</sup> כידוע וביאור הדברים הנה מבו' בזהר דאית ימא ואית ימא<sup data-n=\"2120\">14</sup> ימא תתאה וימא עילא' והיינו כמו שהדבור העליון נקרא ים התחתון וכמ\"ש כל הנחלים הולכים אל הים<sup data-n=\"2121\">15</sup> והיינו כל האורות עליונים דכח\"ב ומדות הכל באין ונמשכים בדבור העליון וגם הרצון ותענוג כנ\"ל ואותיות הדבור עצמן מכסה עליהם שמהו\"ע שלהם בלתי נגלה לשומע הדבור כנ\"ל באריכות כך ממש יובן בים העליון שהוא בחי' המחשבה עליונה שבמוח הבינ' שנק' נהר כנ\"ל דכמו שיש ב' מדרגות אלה דדבור ומחשבה באדם התחתון כך יש למעלה בחינת דבור ומח' עליונה וכמו שאין דבורו כדבורינו כי אין לו גוף כו' ועם כל זה אמר בדבר ה' שמים<sup data-n=\"2122\">16</sup> כו' ויאמר אלקים<sup data-n=\"2123\">17</sup> כו' כך גם בבחי' מחשבותיו ית' אמר כי לא מחשבותי מחשבותיכם<sup data-n=\"2124\">18</sup> כו' ואמנם בזה עכ\"פ יובן שכמו שהדבור בא להעלים אמיתית המהות דרצון ושכל ומדות כו' כנ\"ל אע\"פ שעצם הדבור הנה הוא בא כדי לגלות לזולתו דוקא כנ\"ל באורך כך הוא גם בערך זה במדרגה עליונה יותר גם במח' שאע\"פ שהיא סתומה יותר מן הדבור כי אין המחשבה נודע לזולתו מ\"מ יש בה בחי' העלם וגלוי דכאשר חושב בצירופי אותיות הרי זה אותיות מח' עכ\"פ ונקרא בשם מאמר ג\"כ כמו שידוע בענין אמירה ודבור דאמירה במחשב'<sup data-n=\"2125\">19</sup> כו' ואמנם בחי' הסתימות במחשבה היינו ג\"כ ע\"ד הנ\"ל בדבור והוא מה שהמחשבה ג\"כ בבחי' כיסוי והעלם להעלים ולהסתיר לכל אורות העליונים שבאין ומתלבשי' במח' כמו אור השכל שהוא רוחני בעצם מהותו ונקרא רוח חכ'",[["2107","1","<b>סדכ\"ס</b>: ראה זהר בהקדמה ב, א. ועוד."],["2108","2","<b>דלמת\"ב כלל</b>: ת\"ז בהקדמה (יז, א)."],["2109","3","<b>דלא ידע לי' בר איהו</b>: נסמן לעיל יב, א."],["2110","4","<b>אהי' אשר אהי'</b>: שמות ג, יד."],["2111","5","<b>אהי'. . כתר</b>: נסמן לעיל ס, א."],["2112","6","<b>אנא זמין לאתגלאה</b>: ראה זהר ויקרא יא, א. אחרי סה, א."],["2113","7","<b>הפך ים ליבשה</b>: ראה לעיל רפנ\"ב."],["2114","8","<b>יחיינו מיומים</b>: הושע ו, ב. ראה גם תו\"ח לך צו, ג ובהערה 29. שע\"ת ח\"א סח, סע\"ד ואילך."],["2115","9","<b>ונהר יוצא מעדן</b>: בראשית ב, י."],["2116","10","<b>שהמח' נקרא נהר</b>: ראה גם תו\"א נח ט, ב. תו\"ח שם סב, ב. הנסמן במאמרי אדה\"ז על פרשיות התורה כאן לע' רסב. ד\"ה והמשכילים יזהירו סה\"מ תש\"כ (ברוקלין תשנ\"ד) ע' 114. וש\"נ."],["2117","11","<b>המח' משוטטת תמיד</b>: ראה לקמן צא, א. מאמרי אדה\"ז על פרשיות התורה ח\"א בהוספות ע' 7. תו\"ח ויצא קסט, ד ואילך."],["2118","12","<b>החכמ' שנקרא מעיין</b>: ראה זהר בא מב, ב. הנסמן במאמרי אדה\"א דברים ח\"ב ע' תתצב. תו\"ח לך פא, ב ובהערה 9. לקמן קט, א ובהנסמן במ\"מ לשם."],["2119","13","<b>מחכמ' שנקרא עדן</b>: ראה זהר (אד\"ז) האזינו רצ, א. יתרו צ, א. סה\"מ תקס\"ג ח\"א ע' רג ואילך. וע' קמח. מאמרי אדה\"א דברים ח\"ג ע' תתסד. וש\"נ. וראה גם לעיל סא, ב ובהנסמן לשם."],["2120","14","<b>דאיתא ימא ואית ימא</b>: ראה זהר בשלח מח, ב."],["2121","15","<b>כל הנחלים הולכים אל הים</b>: קהלת א, ז."],["2122","16","<b>בדבר ה' שמים</b>: תהלים לג, ו."],["2123","17","<b>ויאמר אלקים</b>: בראשית א, ג."],["2124","18","<b>כי לא מחשבותי מחשבותיכם</b>: ישעי' נה, ח."],["2125","19","<b>דאמירה במחשב'</b>: ראה גם לקמן קלח, ב ובהנסמן במ\"מ לשם."]]],[2800530183,"או רוח בינה והוא בחי' רוחניות ההשכל' והשגה שכלי' כמו שהיא בעצם וכאשר היא באה בהתלבשות בצירופי אותיות המח' כשחושב השכל והשגה ההיא אזי נעשה המחשבה שחושב את אור ההשכלה הרוחניות כמו לבוש ממש להעלים ולהסתיר מהות ועצם אור השכל הרוחני לבלתי הגלות נגלות ממנו כמו שהיא בעצם מהותו כלל וכמ\"כ אור המדות כאהבה ויראה שבלב שמהות ועצם שלהם הוא בבחי' רוחניות ממש כמו שנראה בחוש בהתעוררות אור האהבה הרוחניות בלב וכן הפחד או הכעס וכה\"ג וכאשר באה רוחניות אור האהבה לכלל הרהור במח' שבמוח הרי נתפסת שם ומתלבשת בבחי' לבוש מח' להעלים מהותה העצמי כמו אדם שמלבי' גופו בלבו' דבר זר כו' וראיה לזה ממה שיכול אדם לפשוט עצמו מלחשוב כמו שפושט לבושו וחוזר ולוב' וחוזר ופושט כך יכול לפשוט את לבו' המחשבה שלא יחשוב באותו השכל או באותה המדה שבלב וכה\"ג ואם היה המחשבה בבחי' עצם ומהות כשחושב בשכל ומדות איך יוכל לפושטו כו' אלא מוכרח לומר שהמחשבה נקרא לבוש לשכל ומדות שהן באין במחשבה בהתלבשות להיות בה בהעלם עצם מהותן כו' ואע\"פ שהמחשבה שבמוח נובעת מן השכל והוא מבחי' ההשגה דבינה שמיד שישיג בהשגה יבא לכלל אותיות מחשבה הנקרא מחשבה עיונית (ולא כהרהור המחשבה במדות שבלב שנקרא הרהור ולא מח') וכמ\"ש במ\"א דהמח' נקרא לאה<sup data-n=\"2126\">20</sup> ושרשה מאחוריים דאימא כו' והוא קשר של תש\"ר כו' וגם הרי מבואר במ\"א בענין אור מים רקיע דההשג' לאורך ורוחב בהסבר וטוב טעם שנקרא בינה הוא הנקרא נהר והוא בחי' מים שנמשכים בהתפשטות וכאשר אגלידו מיא ונקרא קרח היינו כאשר ההשג' נתפסת במציאת דבר עומד בלי התפשטות והיינו כשבא במח' בצירופי אותיות מוגבלים שמתהווים מגופו של השכל עצמו כו' הענין הוא דעצם ההשג' שכלית כמו שהיא נקרא נהר שיוצא מעדן שהוא מוח החכמ' שנק' אין ונמשך מאין ליש בבחינת בינה כידוע אך בחי' התפשטותה והמשכת' במח' אין זה עצם מהותה כלל אדרב' המחשב' היא בבחי' כיסוי והעלם להעלים אמיתית מהות השגת שכל הרוחני שהרי במח' העיוני' בא לכלל ענינים שונים וזרים שאינם ממהות רוחניות ההשג' כלל ע\"ד דוגמא כשמשיג בכי טוב איך שנתהווה הבריא' יש מאין שהשג' זו רוחניות היא וכאשר באה לכלל אותיות מח' עיונית שמעיין במחשבתו איך הוא ומה הוא אז יצייר הדבר בענינים שונים שאינן מכוונין כלל לאמיתת הדבר השגת רוחנית הזאת כמו שהיא בעצם כלל לא מיני'<sup data-n=\"2127\">21</sup> כו' ועוד ראיה לזה ממה שאנו רואים בחוש שכאשר נולד התפעלות המדות בלב מן השכל שבמוח א\"א להיות כ\"א ע\"י התלבשות השכל במח' באותיות דוקא שנקרא הרהור ואז יתפעל בלב כמו שמשיג איך הדבר מו\"מ טוב לו יבא אור השג' זו בכלל מח' והרהור דוקא ואז יתפעל בלבו לחשוק לזה וכן להיפך בהשגת דבר רע ומזיק יבא בהרהור במח' תחילה ואז יתפעל בפחד בלב וזה דבר פלא לכאורה למה לא יומשך מן השכל במדות כמו שהוא ולא יצטרך להביא במחשבה ועוד יפלא יותר ממה שאנו רואים במדות שבלב שאינן נתפסים בלב בהתפעלות כ\"א באמצעות המח' דוקא אז הן נתפסים במציאת מדה בלב שאם",[["2126","20","<b>דהמח' נקרא לאה</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"א בהוספות ע' 7. 8. ובהנסמן במ\"מ לשם. לקמן קי, ב. קלג, ב ובהנסמן במ\"מ לשם."],["2127","21","<b>לא מיני'</b>: לשון הגמרא סוטה ה, א."]]],[2800530184,"לא יהרהר בדבר הנחמד ואהוב לא יבא לכלל מציאת התפעלות אהב' בלב וכן אם לא יהרהר במח' בדבר רע ומזיק לא יבא לכלל מציאת התפעלות יראה בלב וכה\"ג גם במציאת השכל וההשג' הנה אנו רואים בחוש שא\"א שיבא אור השכל לכלל גלוי מציאת דבר מה להיות נתפס במציאות סברא ממש רק ע\"י אמצעות המח' דוקא אז נתפס אור השכל הרוחני במציאת דבר מה דהיינו ע\"י הרהור המח' שתופס בתוכו למהות אור השכל וכאשר נתפס על ידי המחשבה אז יוכר במציאת דבר וכן המדות שבלב על ידי המחשבה נתפסים במציאות כנ\"ל ואם כן הרי יובן מכל זה שעיקר מהות המחשבה הוא בחי' כסוי ולבוש והיינו שהמחשבה תופסת לדבר השכל והמדות בתוכה וה\"ז כמו בחי' כסוי והעלם עליהם ע\"כ ע\"י המח' דוקא נתפסים במציא' וד\"ל (וזהו ראיה הנ\"ל שהתפעלות המדות מן השכל אינו רק ע\"י אמצעו' המח' שמגשמת ותופסת השכל בכסוי ולבוש ע\"כ יכול להיות התפעלות מדות מן השכל ממהות למהות אחר מטעם הנ\"ל וד\"ל) ובכל זה יובן ענין מ\"ש ונהר יוצא מעדן שזהו בחי' המחשבה דוקא שהשגה דבינ' נתפסת שם ואז מתפשטת ומתרבה ביותר כמו הנהר שעיקרו ענין התפשטות יתירה כמו המחשבה שמשוטטת בענין שכל א' בעניני' שונים וחלוקי' מענין זה לזולתו בלי שיעור והפסק כלל השקט לא יוכל וכמו שכל שנמשך הנהר יותר יותר הוא מתגבר כך הוא במחשבה כמו שנראה בחוש שכל שיעמיק מחשבתו יותר תתגבר ויותר יתפס הדבר במורגש לפי שעיקר מהות המח' לעשות תפיסה לדבר מה ואמנם בבחי' כסוי ולבוש הוא בלתי בא<sup data-n=\"2128\">1</sup> בגלוי למטה בדבור כלל כמו אדם שטרוד במחשבתו יותר יותר<sup data-n=\"2129\">2</sup> לא יוכל לבא לכלל דבור להיות שטבע המחשבה לכסות ולהעלים מה שבתוכו כנ\"ל אבל נק' נהר ע\"ש בחי' ההתפשטות וההמשכה ברבוי וקיבוץ כידוע דשם תיבת נהר הוא ע\"ש הקיבוץ וריבוי ההתפשט' בתמידות בלי הפסק וכמו ונהרו אליו כל הגוים<sup data-n=\"2130\">3</sup> שיתקבצו ויומשכו כו' וזהו שאנו רואים שהמחשב' היא תמידית שמשוטטת תמיד ברעיונות שונות בלי הפסק כלל כנראה בחוש שא\"א לאדם לנוח ממחשבה ורעיונות אפי' רגע כי השקט לא תוכל ותמיד עוברים רעיונות בכלי מוחו בכל דבר ודבר לא תנוח לעולם כנהר ממש שהתפשטותו והמשכתו בלי הנחה לעולם וזהו ההפרש בין ים לנהר דהים הוא מן הנחלים שהולכי' ומתקבצי' שם וינוחו ולא יתפשטו עוד וכמ\"ש ולמקוה המים קרא ימים<sup data-n=\"2131\">4</sup> ואמנם הנהר טבעו לילך ולהתמשך דניידי ואזלי<sup data-n=\"2132\">5</sup> כו' וזהו הוראה על היות שרש הנהר מן המעיין שמחודש במקורו תמיד ע\"כ יגבר המשכת הנהר במים מחודשי' תמיד שאין זה במי הים שכבר מכונסי' ועומדים מן הנחלים ומים א' הן אבל מי הנהר מתחדשי' שמים שהולכי' בנהר בכל רגע הן מים חדשים שבאו מחדש ממקורם במעיין והרוצ' לשאוב מים בנהר בכל רגע שואב מים אחרי' שהראשוני' הלכו להם וזהו לפי שהנה' נביעתו והמשכתו מן המעיין והמעיין מתחדש נביעתו ממקורו בכל רגע מגידי הארץ גם שנובע טיפין טיפין אבל נביעת המעיין בתמידות בלי הפסק כלל ע\"כ גם משיכ' הנה' בלי הפסק ונמצא שהנהר בערך ויחוס א' מתייחס אל גופו של מעיין באופן ההתחדשו' המשכ' ובלי הפסק משא\"כ הים בשניהם חסר מאחר שאינו מקבל רק מן הנחלי'",[["2128","1","<b>בא</b>: ניתוסף ע\"פ דפו\"ר."],["2129","2","<b>יותר</b>: כ\"ה גם בדפו\"ר."],["2130","3","<b>ונהרו אליו כל הגוים</b>: ישעי' ב, ב. ראה גם פרדס (שער ערה\"כ) שכ\"ג מערכת יאור."],["2131","4","<b>ולמקוה המים קרא ימים</b>: בראשית א, י. ראה גם תו\"ח נח סב, ב."],["2132","5","<b>דניידי ואזלי</b>: ראה גם עירובין מו, רע\"א. שו\"ע אדה\"ז הל' ברכת הפירות סר\"ו סי\"א."]]],[2800530185,"שמתכנסי' בו לאחר שהוגבלו ולא שיהי' מוכרח שמצד שהנחלי' נמשכי' בלי הפסק גם הים יהי' בלתי גבול<sup data-n=\"2133\">6</sup> שהרי יש גבול לים ואין זה פלא שהרי א' אל מקום שהנחלים הולכים שם הם שבים ללכת<sup data-n=\"2134\">7</sup> שאם לא היו שבים הי' הים שוטף העול' אלא שבין לילך אל התהו' ע\"כ התהו' הוא בלתי הפסק ואמנ' מן התהו' חוזר ונובע מלמטה למעלה דרך גידי הארץ והן המעיינו' ששולח כנחלים<sup data-n=\"2135\">8</sup> כו' וכך חוזר חלילה כמ\"ש במ\"א וד\"ל ובזה יובן ההפרש בין ים לנהר בענין המחשבה ודבור דהנה המחשבה אע\"פ שנמשכ' ומתפשטת ביות' אבל שרשה רק מן המעיין דחכמה דוקא שנק' אין והוא הנובע מן המקור בלי הפסק וכמ\"ש והחכמ' מאין<sup data-n=\"2136\">9</sup> כו' ונמשך למוח בינה בהשג' לאורך ומתפשט במח' בריבוי גדול והוא הנקרא נהר וכל שיגדל יותר כח החכמ' דוקא אזי יגדל וירבה כח המחשב' דבינה לחשוב בריבוי ובעומק יות' שהרי אנו רואים בתינוק שדעתו וחכמתו קטן אין לו מחשבה כלל היינו שמחשבתו בדמיון קצר ומופסק ביותר וכל שיגדל יותר בשנים יגדל ויגבר בו מחשבות עמוקות בהתפשטות יותר וכל שיהי' חכם גדול בחכמ' יותר יותר יגבר בו מחשבות עמוקו' בענינים רבים בלי הפסק ובתגבורת ההמשכה יותר וד\"ל:\n(נח) <b>וזהו</b> הפך ים ליבשה בנהר יעברו ברגל כו' דהנה עיקר ענין קי\"ס הי' בבחי' המל' שהוא בחי' הדיבור<sup data-n=\"2137\">10</sup> העליון שנק' ים העליון וכך כתיב בהעברה שני' דנהר פרת בנהר יעברו ברגל כו' והענין הוא כמארז\"ל ע\"פ ומעיין מבית ה' יצא<sup data-n=\"2138\">11</sup> והשקה את נחל השטים כו' דמעיין זה יוצא מבית ק\"ק תחלתו כמו קרני חגבים והולך ומתמלא כו' והרמז הוא על נהר שיוצא מעדן הנ\"ל שזהו בחי' בינה שנק' נהר שיוצא מן מעיין החכמ' והוא המחשבה שנובע' בהתגברו' גדול' והיא תמידי' בלי הפס' וכמו שהדבו' נק' ים שמכס' על כל אורו' שבאין מן המוחי' ומדו' שבלב ומחש' כך המחש' מכס' על כל אורו' הסתומים שבחכמ' שנק' מעיין חתום כי הרי כל מה שסתום ונעלם בעדן יוצא בנהר זה והיא נובעת ממקור' בתמידו' משא\"כ הדבור אינו רק לפרקי' כו' ע\"כ אין ערך כלל לדבור עם המחשבה שהדבור יש לו הפסק כמו שהים יש לו הפסק לפי ערך הנחלים שנתקבצו בו כנ\"ל אבל נביעת המח' בלי שיעור שלא יכילנו הדבור כלל וכלל וראי' לזה שבשעה שמעמיק במחשבתו אזי הדבור בטל לגמרי לגבי המחשבה ומרחש בשפתיו<sup data-n=\"2139\">12</sup> לימשך קצת אחר המחשבה העמוקה כו' וד\"ל וזהו הפך ים ליבשה בבחי' דבור העליון שמן ההעלם וכיסוי דים שהוא הדבור נהפך לגלוי דיבשה כך ממש יהי' בהעברה שני' בנהר פרת שהוא בחי' בינה במחשבה הנובעת ממקורה שיהפך מן ההעלם לגלוי והיינו גלוי כל אורות העליונים הסתומים בעדן סתימאה שיצאו לידי גלוי כמו שהי' כבר בקי\"ס וזהו בנהר יעברו ברגל לע\"ל שם נשמח' בו שם דוקא לפי שזהו שרש ענין קבלת שכר דלע\"ל בהגלות לישראל מפנימית סודות התור' שהיה סתום וגנוז בפנימית העדן העליון שהוא בחי' פנימית ועצמות התענוג והשעשועים העליונים שבעצמות אוא\"ס שמאיר בפנימית ע\"י והוא פנימית ועצמות העדן דעליו נאמר עין לא ראתה<sup data-n=\"2140\">13</sup> אלקים זולתך יעשה למחכה לו",[["2133","6","<b>הים. . גבול</b>: ראה שע\"ת ח\"א סו, ד."],["2134","7","<b>אל מקום. . ללכת</b>: קהלת א, ז."],["2135","8","<b>המעיינו' ששולח כנחלים</b>: תהלים קד, י."],["2136","9","<b>והחכמ' מאין</b>: איוב כח, יב."],["2137","10","<b>המל'. . הדיבור</b>: ראה לעיל פד, ב ובהנסמן במ\"מ לשם."],["2138","11","<b>ומעיין מבית ה' יצא</b>: יואל ד, יח. ראה יומא עז, סע\"ב."],["2139","12","<b>ומרחש בשפתיו</b>: ראה גם מאמרי אדה\"א נ\"ך ע' יט. וש\"נ. תו\"ח נח נב, ג ובהערה 27."],["2140","13","<b>העדן. . עין לא ראתה</b>: ראה ברכות לד, ב. ישעי' סד, ג."]]],[2800530186,"(ואמר בזהר למחכה למאן דדייק<sup data-n=\"2141\">1</sup> במילין דחכמתא כמו איוב חכה לו<sup data-n=\"2142\">2</sup> כו' עומד וממתין והוא עומק העיון בתושבע\"פ דוקא שמזה יזכה לקבל' שכר בהשגת טעמי סודות התורה ומצות כו') והנה באמת לכאורה יש להבין בזה דלמה דוקא לע\"ל יתגלה ולא עכשיו ועוד דגם עכשיו יש צדיקי' הרבה שזכו לגלוי אור הנעלם הזה כר\"ע ורשב\"י והאריז\"ל וכה\"ג גם בג\"ע העליון עכשיו הנשמו' נהנין מתענוג אלקי שבהשגו' סודות התורה כמבואר בזהר פ' שלח<sup data-n=\"2143\">3</sup> במאמרים נעלמים דרב מתיבתא כו' אך הנה יש להקדים הקדמה אחת והוא בענין בחי' המחשבה דבינה הנ\"ל בהיות מבואר למעלה באריכו' שהמחשב' נק' כסוי ולבוש להלביש ולהעלים למהות ועצם נקודת אור השכל כו' דהיינו מה שפנימית ועצמות החכמה נתפסת במציאת דבר מה ע\"י כלי ההשגה במח' הנה זהו הלבוש וכסוי דעכשיו ההשגה עצמה הוא המסתיר ומעלים לבחי' נקודה הפנימית ועצמית של החכמה כמו שהיא במהותה ועצמותה ממש וזהו כל ענין גלוי אור השגת הנשמות בג\"ע ובצדיקים הגדולי' כר\"ע ורשב\"י ובכל דור ודור כמ\"ש סוד ה' ליריאיו<sup data-n=\"2144\">4</sup> שסוד ה' זה בא אליהם ע\"י בחי' כלי ההשגה דבינה דוקא המכסה על הפנימית ועצמות דחכמה (רק לפרקים הי' גלוי בנשמות הגבוהות כרשב\"י וכה\"ג מעין דלע\"ל במשיח בפנימית ועצמות החכמה שנק' רזא דרזין<sup data-n=\"2145\">5</sup> וגם להאריז\"ל נתגלה מעין זה כשהי' מנמנם דוקא כמשי\"ת) ויובן זה ע\"ד דוגמא מכח המוליד שבטפה שכבר יש בטפה זו ברוחניות ובהעל' הנק' היולי כל כוחו' האברי' כולם פנימי' וחיצוני' מראש לרגל בכל ציור תמונתן (כמו שרואין בכלי האצטרלוב<sup data-n=\"2146\">6</sup> בגרעין התפוח כל ציו' התפוח<sup data-n=\"2147\">7</sup> שעתיד להצמיח) ואין כל חדש אח\"כ בגידול רמ\"ח אברי' בבטן בגשמיותו רק שיצא מן ההעלם לגלוי מאין הרוחני ליש גמור כי משם נמצאים במציאותם מן הרוחני אל הגשם א\"כ גם לאחר התגשמו' האברים הרי האור וחיות הרוחני ההיולי מאיר בהם ובלעדו אין לאברים קיום מציאות כלל ועכ\"ז הרי מוסתר הוא בהם ולא נראה רק הלבוש דעור ובשר וגידי' ועצמו' כמ\"ש עור ובשר תלבישני<sup data-n=\"2148\">8</sup> ונק' כסוי והעלם לגבי נקודה ההיולי' הרוחנית כו' וד\"ל וכך הוא ממש נקודת אור החכמ' הפנימי' והעצמי' שנק' אין והיולי הרי כולל כל מה שיבא מכחה כל התפשטות השגות שכליית בבינה ומח' שנק' השגת והבנת השכל בטוב טעם בכל פרטי החלקי' שבו בהסברות פנים כמו הטפה שכולל כל פרטי האברים מראש לרגל כנ\"ל וא\"כ גם אחר שבא מאין דחכמ' ליש בהשגה ומחשב' אין להם קיום מציאו' בכל פרט רק מן כח החכמה ועכ\"ז הרי כל השגה דמח' מכס' ומעלי' על נקוד' האין דחכמה אע\"פ שמכח' נמצאת ממש אין נרא' לעין הכח ההיולי דאין דחכמה כלל רק ההסבר בטוב טעם ההשגת שכל בעיון המחשבה לבד ששם מותפס הדבר חכמה במציאת דבר מה כשהוא משיג דבר מה משא\"כ בכח מ\"ה כו' וד\"ל וזהו כמו משל המעיין עם הנהר דאע\"פ שהנהר מציאותו ממקורו מן המעיין הוא בא דאם אין מעיין אין מציאות נהר כלל וכמ\"ש נהרא מכיפי' מיברך<sup data-n=\"2149\">9</sup> מכיפי' דוקא מכל מקום נביעת המעיין עצמו מוסתר",[["2141","1","<b>למחכה למאן דדייק</b>: ראה זהר ח\"ש קל, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תקעט? דברים ח\"ד ע' א'תטז ובהנסמן בהנ\"ל. תו\"ח בראשית לה, ג ובהערה 49."],["2142","2","<b>איוב חכה לו</b>: וכ\"ה בתו\"ח מקץ רכה, ד. ובאיוב לב, ד (הובא בזהר שם) חכה את איוב בדברים."],["2143","3","<b>בזהר פ' שלח</b>: ראה שם קסד, סע\"א ואילך."],["2144","4","<b>סוד ה' ליריאיו</b>: תהלים כה, יד."],["2145","5","<b>רזא דרזין</b>: לשון הזהר בראשית מא, א-ב. מה, א-ב. שמות ט, ב. יתרו ע, א ואילך. ועוד."],["2146","6","<b>בכלי האצטרלוב</b>: כ\"ה גם בביאוה\"ז בלק קג, ב. סה\"מ תקס\"ג ח\"א ע' סא [ושם נדפס: האצטרלו\"ג והוא טעות הדפוס. וצ\"ל האצטרלוב]. שערי אורה מח, א. מאמרי אדה\"א במדבר ח\"ה ע' א'תרסט [ושם נדפס: האצטרלוג והוא טעות הדפוס. וצ\"ל: האצטרלוב]. שו\"ע אדה\"ז הל' שבת סש\"ז סל\"א. אמנם בדרך חיים שער התפלה פנ\"ו סג, ד ?האצטרלוג\" [אבל במפתח שמות. . ביטויים מכ\"ק אדמו\"ר שליט\"א לשם מובא ?אצטרלוב\"]."],["2147","7","<b>בגרעין. . ציו' התפוח</b>: ראה גם סידור שחרית לשבת קצא, סע\"ב ואילך (בשם ספרי הטבע). מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תרלד (בשם ספרי הפילוסופים). ביאוה\"ז שם. תו\"ח בראשית כח, ד ובהערה 37."],["2148","8","<b>עור ובשר תלבישני</b>: איוב י, יא."],["2149","9","<b>נהרא מכיפי' מיברך</b>: שבת סה, ב. ראה לקו\"ת שה\"ש לט, א. אמ\"ב שער התפילין קכא, סע\"ג."]]],[2800530187,"ונעלם הוא על ידי אמצעות הנהר המתפשט ממנו כי לא נודע גלוי מקור המעיין מאין הוא נמשך ומתפשט מפני התפשטות הנהר שמכסה על מקורו (וכמו שאנו רואים ברוב דברי הסבר בטוב טעם שלא נודע כלל שרש ותמצית הכל שהוא העיקר ומקור כל הדברי טעם אשר ע\"כ יוכל לבא לידי טעות ושקר מצד שהנקודה דחכמה נעלם ברוחב היכל דבינה כו') וכיוצא בזה יובן איך שמחשבת שכל במחשב' בבינ' מלבשת ומעלמת לגוף נקודת אור החכמה כמו שהיא בעצם מהו\"ע הפנימית ומה שמכחה נמשך ההשגה ועל ידה נתפסת בדבר מציאת שכל עכ\"פ אין זה תפיסת מהותה ועצמותה כלל רק הוא הארה החיצוניות ממנה לבד אשר נגלה ע\"י השגה זו אע\"פ שגם זאת ההשגה מכח נקודת חכמה מאין ליש באה כמעיין ונהר כו' שהרי נק' חו\"ב תרדל\"מ<sup data-n=\"2150\">10</sup> (אך יש בחי' פנימית ועצמית בחכמה שלא נמשך כלל בבינה ונבדל ממנה בערך כמו שאמר בזהר קדש מלה בגרמיה<sup data-n=\"2151\">11</sup> כו' והוא פנימית חכמה כמו שמן שצף על גבי יין<sup data-n=\"2152\">12</sup> כמה שכתו' במ\"א ולפ\"ז אין זה דומה כלל למשל דמעיין ונהר שכל מה שבמעיין יוצא ונובע בנהר וכל כל מה שבטפה נמשך מן הרוחני אל הגשם בלתי נשאר לרוחני דבר שלא בא בהגשמה רק שהוא מוסתר ונעלם וצריך לומר דגם במעיין נשאר בהעלם שלא בא לידי המשכה בנהר והוא הנק' מעיין חתום והוא שרש נביעת המעיין עצמו שהוא בבחי' ההעלם ממש וכן ברוחניות שבטיפה נשאר על אור וחיות הרוחני שבא בהגשמה במוח ולב ואברים והוא בחי' מקיף דחי' יחידה כו' והיינו בחי' פנימית אבא שנק' נקודה סתימאה שמוסתר באמת וזהו נקודה בהיכל המוסתר ואינו נגלה כלל) (וראי' לכל זה הוא מה שאמרו דלא קאים איניש<sup data-n=\"2153\">13</sup> אדעתי' דרבי' כו' ואם הי' השגה דשמיע' דבינה מגיע למהו\"ע החכמה כמו שהיא מדוע לא קאים התלמיד ששומע מפי רבו דבר חכמה כפי השגתו על דעתא דרבי' כמו שהיא בדעת רבו ממש עד מ' שנין דוקא אלא צריך לומר דמה שהשיג בכלי ההשגה אין זה תפיסת מו\"ע התמצית ההיולי שנק' נקודת השכל שלמעלה מהבנת והשגת השכל עד מ' שנין דוקא אז קאים אדעתא דרבי' היינו בבחי' נקודת העצמית שבשכל וחכמה שהשיג ושמע כמה פעמי' ה\"ז מכריח שההשג' רק לבוש להעלים לנקודת דחכ'):\n(נט) <b>והנה</b> להבין זה בתוס' ביאור הנה ידוע שחו\"ב נק' ראי' ושמיעה<sup data-n=\"2154\">14</sup> דשמיעה בבינה וראי' בחכמ' ואינו דומה שמיעה לראי'<sup data-n=\"2155\">15</sup> אע\"פ שהרואה מספר אמיתת מה שראה לשומע ממנו ומדוע לא ידמה שמיעה לראי' דודאי לא כיחד דבר וח\"ד<sup data-n=\"2156\">16</sup> וכאשר השומע ירא' הדבר מה ששמע ימצאהו כמו שהי' בהשגתו ממש כששמע בלי נטי' כקש\"י ומ\"מ גזרו אומר דא\"ד שמיעה לראי' הענין הוא דגם שיוכל אדם להביא בדבור לזולתו כל מה שרא' מ\"מ לא יוכל להביא הדבר בדבור כמו שהוא באמיתית מהו\"ע רק ע\"י ראי' שרואה בפנימית ועצמות אמיתית הדבר דוקא וע\"כ אינו",[["2150","10","<b>חו\"ב תרדל\"מ</b>: ראה לקמן קכז, א ובהנסמן במ\"מ לשם."],["2151","11","<b>קדש מלה בגרמיה</b>: זהר אמור צד, ב."],["2152","12","<b>שמן שצף על גבי יין</b>: ראה שבת ה, ב. מאמרי אדה\"א דברים ח\"א ע' רמה ואילך. בראשית ע' מה ואילך. תו\"ח בראשית כא, ב. אמ\"ב שער הק\"ש פנ\"ד ואילך ובהנסמן במ\"מ לשם."],["2153","13","<b>דלא קאים איניש</b>: ראה ע\"ז ה, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תמד. וש\"נ. הנחות תקע\"ז ע' קמג."],["2154","14","<b>שחו\"ב נק' ראי' ושמיעה</b>: נסמן לעיל עז, ב."],["2155","15","<b>ואינו דומה שמיעה לראי'</b>: נסמן לעיל ט, ב."],["2156","16","<b>וח\"ד</b>: וחצי דבר."]]],[2800530188,"דומה שמיעה לראיה דגם שכבר הבינו והשיגו היטב כשרואהו רואה בפנימית אמיתית העצמות כמו שהוא ממש אשר לא היה מכיל בהשגה ושמיעה כלל וכלל וזהו שהחכמה היא בבחי' ראיה שנק' עין השכל וכמו איזהו חכם<sup data-n=\"2157\">1</sup> הרואה את הנולד רואה ממש ולא שמבין ומשיג בשכל אלא רוא' ראי' עין השכל וע\"כ החכמי' נק' עיני העדה<sup data-n=\"2158\">2</sup> כידוע וטעם הדברים ידוע שיש הפרש גדול בכל השגת דבר מה בין השגה דבינה שאינו רק מבין ומשיג באותו דבר איך הוא ומה הוא רק ע\"פ אופן קליטת כלי מוחו בהסבר הקרוב אל השכל עיוני לבד אבל לא שמשיג ורואה במהות ועצם אמיתית הדבר כמו שהוא ממש שהרי אינו רואה מהותו כלל רק יודע ומשיג בכי טוב למציאותו אבל ע\"י עין השכל דחכמה הרי הוא רואה לעצם הדבר באמיתת מהותו כמו שהוא ממש וברגע וסקירה א' אשר היה צריך להאריך בסיפורו כמה שעות וימים בדברי הסבר שונים להסביר מהות הענין לזולתו ובראי' נתפס ברגע א' ממש שבמהו\"ע ממש א\"צ הסבר כלל רק כאשר יבינו לזולתו יצטרך להסביר לו ברוב דברים רבים (כמו כל דברי תשבחות דס' תהלים שאמר דוד ברוה\"ק<sup data-n=\"2159\">3</sup> נק' הדבור בחי' עולם העליון שזהו כמו משל אדם שהיה רואה את המלך וראה כל כבוד היכלו פנימה ברוב גדולה ועושר ויוצא לחוץ ומספר הכל שצריך להאריך בסיפור זה לכל מי שלא ראה ברוב דברים אבל מי שהי' בהיכל המלך פנימה א\"צ לדבר בזה כלל כי ראה הכל ברגע א' וב' דברים יש כאן א' שאינו דומה השמיעה בכל זה בהיותו בחוץ שאין לו רק מה שמשיג ע\"י השמיעה לראיה בהיותו בפנים שרואה באמיתית ההוד וגדולת ופנימית ועצמו' המלך ממש והב' מה שצריך לשמוע בדבור כמה שעות וימים ובראיה בפנים נסקר בסקירה א' והא בהא תליא משום שרואה בראי' העין נתפס ברגע א' להיותו רואה בפנימית ועצמות אמיתי' מהותו) (וכמו\"כ לע\"ל דכתיב כולם ידעו אותי<sup data-n=\"2160\">4</sup> פי' ידעו לא בדעת והשגת שכל בשמיעה מרחוק אלא בראי' והכרה מקרוב דוקא כמ\"ש הנה אלקינו זה<sup data-n=\"2161\">5</sup> לנוכח כו' שיהיה אמית' עצמותו ית' נתפס ברגע א' וכמ\"ש אמתך אלקי<sup data-n=\"2162\">6</sup> כו' כמשי\"ת) וזהו עיקר הטעם מה שאינו דומה שמיעה לראי' לפי שהשומע אינו משיג רק לפי מה ששומע הסבר הדברים ולא יש לו השג' כלל במהו\"ע הדבר ממש ע\"כ צריך לשמוע כמה ימים וזמן רב עד שיעמוד על אמיתת הדבר וגם אז לא נודע לו עדיין מהות ועצם הדבר כמו שהוא ממש משא\"כ הרואה רואה במהו\"ע הדבר ממש וברגע קטן רואה כל מה שצריך לספר כמה ימים ושנים וד\"ל וזהו שנק' בחי' ראיה והסתכלות דחכמה שהוא בחי' פנימית חכמה וע\"ד שאמר בזהר בכמה דוכתי אסתכלנא ברזא דחכמת'<sup data-n=\"2163\">7</sup> נק' הסתכלות זו בשם ראי' במהות ועצמות באמית' הדבר חכמה כמו שהיא בלא לבוש דהשגה דבינה כלל (וכמו שאמ' על ר\"מ דבעין השכל דבלבא אתחזי כולא<sup data-n=\"2164\">8</sup> כו' וכמ\"ש למעלה בענין ידעו אותי דלע\"ל) ודוגמא לדבר זה אנו מוצאים בהאריז\"ל<sup data-n=\"2165\">9</sup> שפ\"א מצאו תלמידו הרא\"ה<sup data-n=\"2166\">10</sup> ז\"ל שהיה מנמנם ואמר לו האריז\"ל שברגע<sup data-n=\"2167\">11</sup> זו שהיה מנמנם היה רואה ומשיג בעמקי סודו' ורזין",[["2157","1","<b>איזהו חכם</b>: תמיד לב, א."],["2158","2","<b>החכמי' נק' עיני העדה</b>: נסמן לקמן ע' קסט, א."],["2159","3","<b>תהלים. . ברוה\"ק</b>: ראה לקו\"ש [בלק] כרך יח ע' 275 הערה 31."],["2160","4","<b>כולם ידעו אותי</b>: ירמי' לא, לג. ראה גם לעיל יב, ב."],["2161","5","<b>הנה אלקינו זה</b>: ישעי' כה, ט."],["2162","6","<b>אמתך אלקי</b>: תהלים עא, כב."],["2163","7","<b>בזהר. . אסתכלנא ברזא דחכמת'</b>: כ\"ה בכמה מקומות. ראה מאמרי אדה\"ז על פרשיות התורה כאן ע' רסה. מאמרי אדה\"א שמות ח\"ב ע' תקמט. במדבר ח\"ב ע' תרמז. וראה גם תו\"ח נח מח, ג ובהערה 22."],["2164","8","<b>דבעין השכל. . כולא</b>: נסמן לקמן קיא, א."],["2165","9","<b>אנו מוצאים בהאריז\"ל</b>: ראה פע\"ח (שער ק\"ש שעהמ\"ט) שט\"ז פ\"א. עמק המלך הקדמה שלישית פ\"ב (י, ב ואילך). שם שער קרית ארבע פקל\"ד (קיו, ב ואילך). שם שער רישא דזעיר אנפין פ\"ט (קכו, ג). ס' יסוד יוסף (לר\"י בר' יהודא יודל) פס\"א [בשינויים]. הנסמן במאמרי אדה\"ז על פרשיות התורה כאן לע' רסד הערה ד\"ה בכתבי האריז\"ל. מאמרי אדה\"א שמות ח\"א ע' ז. וש\"נ. נ\"ך ס\"ע קלז."],["2166","10","<b>הרא\"ה</b>: תוקן ע\"פ דפו\"ר. ובמהדורת לעמבערג: הרח\"ו.\nהרא\"ה [ הר' אברהם הלוי] כ\"ה בפע\"ח ובעמ\"ה שם [י, ב ואילך]. מאמרי אדה\"ז כאן (ע' ער).\nהרח\"ו כ\"ה בס' יסוד יוסף שם [ושם: סיפר החכם הקדוש ר' מסעד סגי נהור בשם. . רח\"ו עיי\"ש]. מאמרי אדה\"ז כאן (ע' רסד). מאמרי אדה\"א שמות ח\"א ע' ז."],["2167","11","<b>שברגע</b>: כ\"ה גם במאמרי אדה\"ז על פרשיות התורה כאן? תו\"ח נח מח, ג. וש\"נ בהערה 23."]]],[2800530189,"דאורייתא שאם היה צריך לגלותם בדבור ובכתב<sup data-n=\"2168\">12</sup> היה צריך להאריך בהם בדרושים זמן רב עד פ'<sup data-n=\"2169\">13</sup> שנה וכו' ובאמת זהו דבר פלא גדול לכאורה דגם אם הראי' והסתכלות זו שהיה ברגע א' היה רק בתמצית ונקודת ההשגות העמוקות איך יתכן שיתפוס ברגע א' מה שצריך לדבר או לכתוב פ' שנה<sup data-n=\"2170\">14</sup> דאע\"פ שאנו רואים בחוש דמה שצריך אדם לדבר שעה ושתים יתפוס בעיון המחשבה במעט רגע או ב' רגעים<sup data-n=\"2171\">15</sup> ה\"ז ודאי בא במדה ושיעור לפי ערך אריכות ההשכלות רבות דודאי מה שצריך לדבר יום ויומיים מוכרח שגם בעיון המחשבה יומשך בערך חצי שעה או רבע שעה ולא יספיק בב' וג' רגעים ומה שצריך לדבר חדש ימים מוכרח שיומשך תחלה בעיון השכל והמחשבה ג' או ד' שעות לכל הפחות עד שלערך הדבור בזמן ששים<sup data-n=\"2172\">16</sup> שנה צריך שיהי' תחלה בעיון השכל ומחשבה לתפוס במשך ב' וג' ימים עכ\"פ ואפשר חדש ימים ויותר שהרי עיון השכל הוא שכולל בכלל וסקירה א' מה שיחולק אח\"כ בדבור בדרך פרטי פרטות וא\"כ ה\"ז כמו הכלל לגבי הפרט שבודאי לפ\"ע הרבוי בפרט הוא ערך הכלל הכולל כי אין בפרט אלא מה שבכלל כו' ואיך יוכל להיות שלא יהיה הפרט בערך הכלל דודאי הפרט דומה לכלל כי חלקי הפרט יגבילו את הכלל לפ\"ע אם רב או מעט לא יוסיף ולא יגרע ואם עיון המחשבה כללות הדבור שבפרט הרי ודאי לפי ערך ריבוי הפרט כן יהיה ריבוי הכלל ואיך אמר שברגע א' יתפס מה שיחולק לפ' שנה בדבור בפרט שאין זה לפ\"ע בכלל לגבי הפרט ואף ע\"פ שרגע זו הי' בבחי' אור הראי' והסתכלות שלמעל' מן ההשגה היינו למעלה מן השגת אותיות מחשבת שכל אבל הרי גם הוא כמו פרט נחשב לגבי הכלל דראי' שהוא נקודת תמצית המושכל א\"כ גם זה צריך להיות לפ\"ע דהיינו מה שצריך לחשוב באותיות מחשבה והשגה שעה אחת יתפס בתמצי' הנקודה רק ברבע שעה או פחות דודאי א\"א לומר שיהי' נתפס ברגע א' תמצית השכל מה שצריך לחשוב אותו בעיון חדש ימים שאין זה לפ\"ע כלל ופרט כו' כי גם נקודה דחכמ' נק' כלל שכולל כל פרטי ההשגות שמסתעפים ממנה במח' הנק' מחש' עיוני' כידוע שהחכמ' נק' אין ובינה נק' יש וכמעיין ונהר או טפה שמוליד ולד כנ\"ל שאין זה הכלל רק לפ\"ע הפרט כו' וד\"ל אלא באמת צריך לומר דגם בבחי' ראיה והסתכלות דחכמה הנ\"ל יש ב' מדרגו' הא' בחי' נקוד' דחכ' שמתפשטת אח\"כ לאורך ורוחב בהשגה ומחשבה דבינה מאין ליש כנ\"ל שזהו רק בחי' אין של היש שדומה לכלל ופרט (כמעיין שנובע ונמשך בהתפשטות בנהר וכטפה בולד כנ\"ל) שבחי' אין דחכמ' הוא כולל לפרט ההשגה בדרך מוגבל לפ\"ע הפרט אם רב או מעט כנ\"ל וזהו הגבלת אותיות מח' דבינה העיונית כאשר אדם טרוד בעיון ההשגה להבין ולהסביר הטיב את הנקוד' ותמצי' הסברה שבזה העיון נתפס מציאות אור הנקוד' דחכמה כו' כנ\"ל והמדרג' הב' היינו בחי' פנימית נקודה דחכמה עצמ' כמו שהיא באה ממקור' העצמי בהעלם דהיינו בכח המשכיל ההיולי שעדיין לא יוכל לבא לכלל השג' דבינה",[["2168","12","<b>בדבור ובכתב</b>: בפע\"ח ועה\"מ (י, ג. קכו, ג) דורש. בעמ\"ה (קיו, ג) יכתוב אדם. ביסוד יוסף (וכתוב)."],["2169","13","<b>פ'</b>: תוקן ע\"פ דפו\"ר. ובמהדורת לעמבערג: ?ס'\"."],["2170","14","<b>פ' שנה</b>: וכ\"ה בסמוך בשו\"ה פ'. בשו\"ה שברגע. ולקמן צד, ב שו\"ה פ'. אמנם להלן בשו\"ה והמחשבה ? ?ששים\". וכ\"ה לקמן צד, א בשו\"ה לבא.\nבפע\"ח ועמ\"ה הנ\"ל ?שמונים\". וביסוד יוסף שם ?ארבעים\" [ושם משמע שזהו סיפור אחר ע\"ש]. ראה מאמרי אדה\"א שמות ח\"א ע' ז. וש\"נ. נ\"ך ס\"ע קלז. וראה סה\"מ תש\"א ע' 133 בהערה."],["2171","15","<b>שעה ושתים. . רגע או ב' רגעים</b>: ראה מאמרי אדה\"ז על פרשיות התורה כאן ע' רסד וע' ער. מאמרי אדה\"א דברים ח\"א ע' רפג. וש\"נ. הנחות תקע\"ז ע' רפג. וש\"נ."],["2172","16","<b>ששים</b>: ראה לעיל הערה פ' שנה."]]]]});
